insert into public.exercises
  (id, name, category, type, body_part, equipment, muscle_group, target, secondary_muscles, instructions, image, gif_url, attribution)
values
(1665, 'dumbbell one arm prone curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Lie face down on a flat bench with a dumbbell in one hand, palm facing down. Extend your arm fully, letting it hang straight down towards the floor. Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Sdraiati a faccia in giù su una panca piatta con un manubrio in una mano, il palmo rivolto verso il basso. Allunga completamente il braccio, lasciandolo pendere dritto verso il pavimento. Mantenendo fermo la parte superiore del braccio, arrotola il manubrio verso la spalla contraendo i bicipiti. Fermati un attimo in cima, poi abbassa lentamente il manubrio fino alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Bir elinizde bir dambıl, avuç içi aşağı bakacak şekilde düz bir bankta yüzüstü yatın. Kolunuzu tamamen uzatın ve yere doğru düz bir şekilde sarkmasına izin verin. Üst kolunuzu sabit tutarak, bicepslerinizi kasarak dambılı omzunuza doğru kıvırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo. Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Лягте лицом вниз на плоскую скамью с гантелью в одной руке ладонью вниз. Полностью вытяните руку, позволяя ей свисать прямо к полу. Удерживая плечо неподвижно, поднимите гантель к плечу, напрягая бицепс. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"脸朝下躺在平坦的长凳上，一只手握住哑铃，掌心朝下。 完全伸展你的手臂，让它垂直垂向地板。 保持上臂静止，通过收缩二头肌将哑铃向上卷曲至肩膀。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"एक हाथ में डम्बल लेकर, हथेली नीचे की ओर रखते हुए, एक सपाट बेंच पर मुंह करके लेट जाएं। अपनी बांह को पूरी तरह फैलाएं, उसे सीधे नीचे फर्श की ओर लटकने दें। अपनी ऊपरी भुजा को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Połóż się twarzą w dół na płaskiej ławce, trzymając hantlę w jednej ręce, dłonią skierowaną w dół. Wyprostuj rękę całkowicie, pozwalając jej zwisać prosto w dół w stronę podłogi. Utrzymując nieruchome ramię, unieś hantlę w stronę barku, napinając biceps. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 엎드려 한쪽 손에 덤벨을 들고 손가락이 아래를 향하도록 합니다. 팔을 완전히 펼쳐 땅을 향해 내립니다. 위팔은 고정한 채 이두근을 수축하며 덤벨을 어깨 방향으로 말아올립니다. 위에서 잠시 멈춘 후 천천히 덤벨을 처음 위치로 내립니다. 원하는 횟수만큼 반복한 후 반대쪽 팔로 바꿔 진행합니다.","fr":"Allonge-toi face vers le bas sur un banc plat avec un haltère dans une main, paume tournée vers le bas. Étends complètement ton bras, en le laissant pendre droit vers le sol. En gardant le haut du bras immobile, fléchis l''haltère vers ton épaule en contractant tes biceps. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1665-JWjujiY.jpg', 'videos/1665-JWjujiY.gif', '© Gym visual — https://gymvisual.com/'),
(1666, 'dumbbell one arm prone hammer curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended. Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Sdraiati a faccia in giù su una panca piatta con un manubrio in una mano, il palmo rivolto verso il corpo e il braccio completamente esteso. Mantieni fermo il braccio superiore e piega il manubrio verso la spalla, contraendo i bicipiti. Fermati un attimo in cima, poi abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Bir elinizde bir dambıl, avuç içi vücudunuza dönük ve kolunuz tamamen uzatılmış halde, düz bir bankta yüzüstü uzanın. Üst kolunuzu sabit tutun ve dambılı omzunuza doğru kıvırarak bicepslerinizi kasın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Лягте лицом вниз на плоскую скамью с гантелью в одной руке, ладонью к телу и полностью выпрямленной рукой. Держите плечо неподвижно и поднимите гантель к плечу, напрягая бицепс. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"面朝下躺在平坦的长凳上，一只手拿着哑铃，手掌面向身体，手臂完全伸展。 保持上臂静止，将哑铃向肩膀弯曲，收缩二头肌。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"एक हाथ में डम्बल लेकर एक सपाट बेंच पर मुंह के बल लेट जाएं, हथेली आपके शरीर की ओर हो और हाथ पूरी तरह फैला हुआ हो। अपनी ऊपरी बांह को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए डंबल को अपने कंधे की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Połóż się twarzą w dół na płaskiej ławce, trzymając hantlę w jednej ręce, dłonią skierowaną w stronę ciała, ramię w pełni wyprostowane. Utrzymuj nieruchome ramię i unieś hantlę w stronę barku, napinając biceps. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 엎드려 한쪽 손에 덤벨을 들고 손가락이 몸을 향하도록 팔을 완전히 펼칩니다. 위팔은 고정한 채 이두근을 수축하며 덤벨을 어깨 방향으로 말아올립니다. 위에서 잠시 멈춘 후 천천히 덤벨을 처음 위치로 내립니다. 원하는 횟수만큼 반복한 후 반대쪽 팔로 바꿔 진행합니다.","fr":"Allonge-toi face vers le bas sur un banc plat avec un haltère dans une main, paume tournée vers ton corps et bras entièrement tendu. Garde le haut du bras immobile et fléchis l''haltère vers ton épaule en contractant tes biceps. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1666-LIGZSTA.jpg', 'videos/1666-LIGZSTA.gif', '© Gym visual — https://gymvisual.com/'),
(1291, 'dumbbell one arm pullover on exercise ball', 'chest', 'strength', 'chest', 'dumbbell', 'triceps', 'pectorals', '["triceps","latissimus dorsi","rhomboids"]'::jsonb, '{"en":"Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell with one hand and extend your arm straight up above your chest. Slowly lower the dumbbell behind your head while keeping your arm straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una palla da ginnastica con i piedi piatti a terra e le ginocchia piegate a 90 gradi. Tieni un manubrio con una mano e allunga il braccio dritto sopra il petto. Abbassa lentamente il manubrio dietro la testa mantenendo il braccio dritto. Fermati un attimo, poi solleva il manubrio di nuovo alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Ayaklarınız yere düz basacak ve dizleriniz 90 derecelik bir açıyla bükülmüş olacak şekilde bir egzersiz topunun üzerine oturun. Bir elinizle dambılı tutun ve kolunuzu göğsünüzün üzerine doğru uzatın. Kolunuzu düz tutarak dambılı başınızın arkasına yavaşça indirin. Bir an duraklayın ve dambılı tekrar başlangıç ​​pozisyonuna kaldırın. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на гимнастический мяч, поставьте ступни на землю и согните колени под углом 90 градусов. Возьмите гантель одной рукой и вытяните руку прямо над грудью. Медленно опустите гантель за голову, сохраняя руку прямой. Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。 用一只手握住哑铃，将手臂伸直至胸部上方。 慢慢地将哑铃放到脑后，同时保持手臂伸直。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数，然后换臂。","hi":"अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक व्यायाम बॉल पर बैठें। एक हाथ से डम्बल पकड़ें और अपने हाथ को सीधे अपनी छाती के ऊपर फैलाएँ। अपने हाथ को सीधा रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ। एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na piłce gimnastycznej, stopy oprzyj płasko na podłodze, a kolana zegnij pod kątem 90 stopni. Trzymaj hantlę jedną ręką i wyprostuj rękę prosto nad klatką piersiową. Powoli opuszczaj hantlę za głowę, utrzymując wyprostowaną rękę. Zatrzymaj się na chwilę, a następnie unieś hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"익서사이즈 볼에 앉아 발을 땅에 고정하고 무릎을 90도로 굽힙니다. 한쪽 손으로 덤벨을 들고 팔을 가슴 위로 펼칩니다. 팔을 곧게 유지하며 덤벨을 머리 뒤로 천천히 내립니다. 잠시 멈춘 후 덤벨을 처음 위치로 올립니다. 원하는 횟수만큼 반복한 후 반대쪽 팔로 바꿔 진행합니다.","fr":"Assieds-toi sur un ballon d''exercice, les pieds à plat sur le sol et les genoux fléchis à un angle de 90 degrés. Tiens un haltère d''une main et étends ton bras droit au-dessus de ta poitrine. Abaisse lentement l''haltère derrière ta tête tout en gardant ton bras tendu. Marque une pause, puis ramène l''haltère à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1291-bQHPBU3.jpg', 'videos/1291-bQHPBU3.gif', '© Gym visual — https://gymvisual.com/'),
(358, 'dumbbell one arm reverse wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'wrist extensors', 'forearms', '["wrist extensors"]'::jsonb, '{"en":"Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in one hand with an overhand grip, palm facing down. Rest your forearm on your thigh, with your wrist hanging off the edge. Slowly lower the dumbbell towards the ground by flexing your wrist. Pause for a moment at the bottom, then slowly curl your wrist back up towards your body. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Siediti su una panca o una sedia con i piedi piatti a terra. Tieni un manubrio con una mano con una presa sopra la mano, palmo rivolto verso il basso. Appoggia l''avambraccio sulla coscia, con il polso penzolante dal bordo. Abbassa lentamente il manubrio verso terra flettendo il polso. Fermati un attimo in fondo, poi ripiega lentamente il polso verso il corpo. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun. Bir elinizde bir dambılı, avuç içi aşağı bakacak şekilde üstten kavrayarak tutun. Bileğiniz kenardan sarkacak şekilde ön kolunuzu uyluğunuzun üzerine koyun. Bileğinizi bükerek dambılı yavaşça yere doğru indirin. Altta bir an duraklayın, ardından bileğinizi yavaşça vücudunuza doğru kıvırın. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo. Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde. Baja lentamente la mancuerna hacia el suelo flexionando la muñeca. Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Сядьте на скамью или стул, поставив ноги на землю. Возьмите гантель в одну руку хватом сверху ладонью вниз. Положите предплечье на бедро так, чтобы запястье свисало с края. Медленно опустите гантель на землю, сгибая запястье. Задержитесь на мгновение в нижней точке, затем медленно согните запястье обратно к телу. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"坐在长凳或椅子上，双脚平放在地面上。 一只手握住哑铃，正手握住，手掌朝下。 将前臂放在大腿上，手腕悬在边缘。 弯曲手腕，慢慢地将哑铃降低到地面。 在底部停顿片刻，然后慢慢地将手腕向上卷向身体。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें। एक हाथ में डम्बल को ओवरहैंड ग्रिप से पकड़ें, हथेली नीचे की ओर हो। अपनी कलाई को किनारे से लटकाते हुए अपनी बांह को अपनी जांघ पर टिकाएं। अपनी कलाई को मोड़कर धीरे-धीरे डंबल को जमीन की ओर नीचे लाएं। नीचे एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाई को वापस अपने शरीर की ओर मोड़ें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Usiądź na ławce lub krześle, stopy oprzyj płasko na podłodze. Trzymaj hantlę w jednej ręce chwytem nachwytem, dłonią skierowaną w dół. Oprzyj przedramię na udzie, tak aby nadgarstek zwisał poza krawędzią. Powoli opuszczaj hantlę w stronę podłogi, zginając nadgarstek. Zatrzymaj się na chwilę na dole, a następnie powoli zegnij nadgarstek z powrotem w stronę ciała. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"벤치나 의자에 앉아 발을 바닥에 평평하게 놓으세요. 한쪽 팔에 오버핸드 그립으로 덤벨을 잡고 손바닥이 아래를 향하도록 하세요. 전완을 넓적다리에 얹고 손목이 벤치 가장자리에서 튀어나오도록 하세요. 손목을 굽혀 덤벨을 천천히 바닥 쪽으로 내리세요. 아래에서 잠깐 멈춘 후 천천히 손목을 몸 쪽으로 말아올리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Assieds-toi sur un banc ou une chaise, les pieds à plat sur le sol. Tiens un haltère dans une main avec une prise en pronation, la paume tournée vers le bas. Pose ton avant-bras sur ta cuisse, le poignet dépassant du bord. Abaisse lentement l''haltère vers le sol en fléchissant le poignet. Marque une pause en bas, puis enroule lentement ton poignet vers ton corps. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/0358-BwSNDGt.jpg', 'videos/0358-BwSNDGt.gif', '© Gym visual — https://gymvisual.com/'),
(359, 'dumbbell one arm reverse fly (with support)', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Sit on a bench with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing inwards. Lean forward and place your free hand on the bench for support. Keep your arm slightly bent and raise it out to the side until it is parallel to the ground. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una panchina con i piedi piatti a terra e la schiena dritta. Tieni un manubrio in una mano con il palmo rivolto verso l''interno. Piegati in avanti e appoggia la mano libera sulla panca per sostenerti. Tieni il braccio leggermente piegato e sollevalo di lato finché non è parallelo al terreno. Fermati un attimo in cima, poi abbassa lentamente il braccio fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Ayaklarınız yere düz basacak ve sırtınız düz olacak şekilde bir bankta oturun. Avucunuz içe bakacak şekilde bir elinizde bir dambıl tutun. Öne doğru eğilin ve serbest elinizi destek için bankın üzerine koyun. Kolunuzu hafifçe bükülü tutun ve yere paralel olana kadar yana doğru kaldırın. Tepe noktasında bir an duraklayın, ardından kolunuzu yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro. Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte. Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на скамью, поставив ноги на землю и выпрямив спину. Возьмите гантель в одну руку ладонью внутрь. Наклонитесь вперед и положите свободную руку на скамью для поддержки. Держите руку слегка согнутой и поднимите ее в сторону, пока она не станет параллельна земле. Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在长凳上，双脚平放在地上，背部挺直。 一只手握住哑铃，手掌朝内。 身体前倾，将空着的手放在长凳上以获得支撑。 保持手臂稍微弯曲并将其向侧面抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数，然后换臂。","hi":"अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके एक बेंच पर बैठें। अपनी हथेली को अंदर की ओर रखते हुए एक हाथ में डम्बल पकड़ें। आगे झुकें और समर्थन के लिए अपना खाली हाथ बेंच पर रखें। अपनी भुजा को थोड़ा मोड़कर रखें और इसे बगल की ओर तब तक उठाएं जब तक कि यह जमीन के समानांतर न हो जाए। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na ławce, stopy oprzyj płasko na podłodze, a plecy trzymaj proste. Trzymaj hantlę w jednej ręce, dłonią skierowaną do wewnątrz. Pochyl się do przodu i oprzyj wolną rękę na ławce dla stabilizacji. Trzymaj rękę lekko zgiętą i unieś ją na bok, aż będzie równoległa do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść rękę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 앉아 발을 바닥에 평평하게 놓고 등을 펴세요. 한쪽 팔에 덤벨을 잡고 손바닥이 안쪽을 향하도록 하세요. 몸을 앞으로 기울이고 다른 손을 벤치에 놓아 지지하세요. 팔을 약간 구부린 상태로 유지하고 옆으로 들어올려 지면과 평행하게 하세요. 위에서 잠깐 멈춘 후 천천히 팔을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un banc, les pieds à plat sur le sol et le dos droit. Tiens un haltère dans une main avec la paume tournée vers l''intérieur. Penche-toi en avant et place ta main libre sur le banc pour te soutenir. Garde ton bras légèrement fléchi et lève-le sur le côté jusqu''à ce qu''il soit parallèle au sol. Marque une pause en haut, puis abaisse lentement ton bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/0359-e25F58f.jpg', 'videos/0359-e25F58f.gif', '© Gym visual — https://gymvisual.com/'),
(1622, 'dumbbell one arm reverse grip press', 'chest', 'strength', 'chest', 'dumbbell', 'triceps', 'pectorals', '["triceps","shoulders"]'::jsonb, '{"en":"Sit on a flat bench with a dumbbell in one hand, palm facing towards your body. Place your feet flat on the ground and keep your back straight. Raise the dumbbell to shoulder height, keeping your elbow close to your body. Press the dumbbell upwards until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Siediti su una panca piatta con un manubrio in una mano, il palmo rivolto verso il corpo. Metti i piedi piatti a terra e tieni la schiena dritta. Alza il manubrio all''altezza della spalla, tenendo il gomito vicino al corpo. Premi il manubrio verso l''alto finché il braccio non è completamente esteso. Fermati un attimo in cima, poi abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Bir elinizde bir dambıl, avuç içi vücudunuza bakacak şekilde düz bir bankta oturun. Ayaklarınızı düz bir şekilde yere koyun ve sırtınızı düz tutun. Dirseğinizi vücudunuza yakın tutarak dambılı omuz yüksekliğine kaldırın. Kolunuz tamamen uzatılıncaya kadar dambılı yukarı doğru bastırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo. Coloca los pies planos sobre el suelo y mantén la espalda recta. Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Сядьте на ровную скамью с гантелью в одной руке ладонью к телу. Поставьте ноги на землю и держите спину прямо. Поднимите гантель на высоту плеч, держа локоть близко к телу. Нажмите гантель вверх, пока рука полностью не выпрямится. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"坐在平坦的长凳上，一只手拿着哑铃，手掌朝向身体。 将双脚平放在地面上，并保持背部挺直。 将哑铃举至肩膀高度，保持肘部靠近身体。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"एक हाथ में डम्बल लेकर एक सपाट बेंच पर बैठें, हथेली आपके शरीर की ओर हो। अपने पैरों को ज़मीन पर सपाट रखें और अपनी पीठ सीधी रखें। अपनी कोहनी को अपने शरीर के करीब रखते हुए डम्बल को कंधे की ऊंचाई तक उठाएं। डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपका हाथ पूरी तरह फैल न जाए। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Usiądź na płaskiej ławce, trzymając hantlę w jednej ręce, dłonią skierowaną w stronę ciała. Oprzyj stopy płasko na podłodze i trzymaj proste plecy. Unieś hantlę na wysokość barku, trzymając łokieć blisko ciała. Wypchnij hantlę w górę, aż ramię będzie w pełni wyprostowane. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"평평한 벤치에 앉아 한쪽 팔에 덤벨을 잡고 손바닥이 몸 쪽을 향하도록 하세요. 발을 바닥에 평평하게 놓고 등을 펴세요. 덤벨을 어깨 높이로 올리고 팔꿈치가 몸에 가깝게 유지하세요. 팔이 완전히 펴질 때까지 덤벨을 위로 누르세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Assieds-toi sur un banc plat avec un haltère dans une main, paume tournée vers ton corps. Place tes pieds à plat au sol et garde ton dos droit. Lève l''haltère à hauteur des épaules en gardant ton coude près de ton corps. Pousse l''haltère vers le haut jusqu''à ce que ton bras soit complètement tendu. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/1622-Ze7MoIb.jpg', 'videos/1622-Ze7MoIb.gif', '© Gym visual — https://gymvisual.com/'),
(1414, 'dumbbell one arm reverse preacher curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip. Lower the dumbbell slowly until your arm is fully extended. Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una panca da predicatore con il petto appoggiato al cuscinetto e il braccio esteso oltre il bordo della panca, tenendo un manubrio con una presa sotto. Abbassa lentamente il manubrio finché il braccio non è completamente esteso. Arrotola il manubrio verso la spalla, mantenendo fermo il braccio superiore. Stringi i bicipiti nella parte alta del movimento, poi abbassa lentamente il manubrio fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Göğsünüz yastığa dayalı ve kolunuz bankın kenarından uzatılmış şekilde bir vaiz bankına oturun, alttan kavramalı bir dambıl tutun. Kolunuz tamamen uzatılıncaya kadar dambılı yavaşça indirin. Üst kolunuzu sabit tutarak dambılı omzunuza doğru kıvırın. Hareketin üst noktasında bicepslerinizi sıkın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino. Baja lentamente la mancuerna hasta que el brazo quede completamente extendido. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на скамью для проповедника, прижав грудь к подушке и вытянув руку через край скамьи, держа гантель обратным хватом снизу. Медленно опускайте гантель, пока рука полностью не выпрямится. Поднимите гантель обратно к плечу, сохраняя плечо неподвижным. Напрягите бицепсы в верхней точке движения, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在牧师凳上，胸部靠在垫子上，手臂伸出长凳边缘，反握哑铃。 慢慢降低哑铃，直到手臂完全伸展。 将哑铃向后弯向肩膀，保持上臂静止。 在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर और अपनी बांह को बेंच के किनारे पर फैलाकर बैठें, एक डम्बल को अंडरहैंड ग्रिप से पकड़ें। डम्बल को धीरे-धीरे नीचे करें जब तक कि आपकी बांह पूरी तरह विस्तारित न हो जाए। अपनी ऊपरी भुजा को स्थिर रखते हुए, डम्बल को वापस अपने कंधे की ओर मोड़ें। गति के शीर्ष पर अपने बाइसेप्स को निचोड़ें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na ławce modlitewnej (Scotta), klatką piersiową opierając się o podkładkę, a rękę wyprostuj nad krawędzią ławki, trzymając hantlę chwytem podchwytem. Powoli opuść hantlę, aż ramię będzie w pełni wyprostowane. Unieś hantlę z powrotem w stronę barku, utrzymując nieruchome ramię. Ściśnij biceps na górze ruchu, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"프리처 벤치에 앉아 가슴을 패드에 대고 팔을 벤치 가장자리 위로 펼친 후 언더핸드 그립으로 덤벨을 잡으세요. 팔이 완전히 펼쳐질 때까지 덤벨을 천천히 내리세요. 팔 위쪽을 고정하고 덤벨을 어깨 쪽으로 말아올리세요. 동작의 위쪽에서 이두근을 꽉 조인 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un banc à prêcheur, la poitrine contre le coussin et ton bras tendu par-dessus le bord du banc, en tenant un haltère avec une prise en supination. Abaisse lentement l''haltère jusqu''à ce que ton bras soit complètement tendu. Enroule à nouveau l''haltère vers ton épaule, en gardant ton bras immobile. Contracte tes biceps en haut du mouvement, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1414-bWxq4op.jpg', 'videos/1414-bWxq4op.gif', '© Gym visual — https://gymvisual.com/'),
(1667, 'dumbbell one arm reverse spider curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Alzati dritto con un manubrio in una mano, il palmo rivolto verso il basso e il braccio completamente teso. Mantenendo fermo il braccio superiore, piega il manubrio verso la spalla flettendo il gomito. Fermati un attimo in cima, poi abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Bir elinizde bir dambıl, avuç içi aşağı bakacak ve kol tamamen uzatılmış şekilde dik durun. Üst kolunuzu sabit tutarak, dirseğinizi bükerek dambılı omzunuza doğru kıvırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Встаньте прямо, возьмите гантель в одну руку ладонью вниз и полностью выпрямите руку. Удерживая плечо неподвижно, поднимите гантель к плечу, сгибая локоть. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"站直，一只手握住哑铃，手掌朝下，手臂完全伸展。 保持上臂静止，弯曲肘部，将哑铃向肩膀方向卷曲。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"एक हाथ में डम्बल लेकर, हथेली नीचे की ओर और हाथ पूरी तरह फैलाकर सीधे खड़े हो जाएं। अपनी ऊपरी बांह को स्थिर रखते हुए, अपनी कोहनी को मोड़कर डंबल को अपने कंधे की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Stań prosto, trzymając hantlę w jednej ręce, dłonią skierowaną w dół, ramię w pełni wyprostowane. Utrzymując nieruchome ramię, unieś hantlę w stronę barku, zginając łokieć. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"몸을 곧게 펴고 서서 한쪽 팔에 덤벨을 잡고 손바닥이 아래를 향하며 팔을 완전히 펼친 상태로 서세요. 팔 위쪽을 고정하고 팔꿈치를 구부려 덤벨을 어깨 쪽으로 말아올리세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Tiens-toi bien droit avec un haltère dans une main, la paume tournée vers le bas et le bras complètement tendu. En gardant le haut du bras immobile, fléchis l''haltère vers ton épaule en fléchissant ton coude. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1667-VdLZ3nB.jpg', 'videos/1667-VdLZ3nB.gif', '© Gym visual — https://gymvisual.com/'),
(1668, 'dumbbell one arm seated bicep curl on exercise ball', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your arm fully extended. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una palla da ginnastica con i piedi piatti a terra e la schiena dritta. Tieni un manubrio in una mano con il palmo rivolto verso l''alto e il braccio completamente esteso. Mantenendo fermo il braccio superiore, arrotola il manubrio verso la spalla contraendo i bicipiti. Fermati un attimo in cima, poi abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Ayaklarınız yere düz basacak ve sırtınız düz olacak şekilde bir egzersiz topunun üzerine oturun. Avucunuz yukarı bakacak ve kolunuz tamamen uzatılmış halde bir elinizde bir dambıl tutun. Üst kolunuzu sabit tutarak, bicepslerinizi kasarak dambılı omzunuza doğru kıvırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину. Возьмите гантель в одну руку ладонью вверх и полностью выпрямите руку. Удерживая плечо неподвижно, поднимите гантель к плечу, напрягая бицепс. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，手掌朝上，手臂完全伸展。 保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें। अपनी हथेली को ऊपर की ओर रखते हुए और अपने हाथ को पूरी तरह फैलाकर एक हाथ में डम्बल पकड़ें। अपनी ऊपरी बांह को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na piłce gimnastycznej, stopy oprzyj płasko na podłodze, a plecy trzymaj proste. Trzymaj hantlę w jednej ręce, dłonią skierowaną do góry, ramię w pełni wyprostowane. Utrzymując nieruchome ramię, unieś hantlę w stronę barku, napinając biceps. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"운동 공에 앉아 발을 바닥에 평평하게 놓고 등을 펴세요. 한쪽 팔에 덤벨을 잡고 손바닥이 위를 향하며 팔을 완전히 펼친 상태로 하세요. 팔 위쪽을 고정하고 이두근을 수축시키며 덤벨을 어깨 쪽으로 말아올리세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un ballon d''exercice, les pieds à plat sur le sol et le dos droit. Tiens un haltère dans une main avec la paume tournée vers le haut et le bras complètement étendu. En gardant le haut du bras immobile, fléchis l''haltère vers ton épaule en contractant tes biceps. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1668-s999Hdo.jpg', 'videos/1668-s999Hdo.gif', '© Gym visual — https://gymvisual.com/'),
(1669, 'dumbbell one arm seated hammer curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in one hand with a neutral grip (palms facing each other). Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una panchina con la schiena dritta e i piedi piatti a terra. Tieni un manubrio con una mano con una presa neutra (palmi rivolti l''uno verso l''altro). Appoggia il gomito all''interno della coscia, appena sopra il ginocchio. Mantenendo fermo il braccio superiore, espira e arrotola il manubrio verso la spalla. Fermati un attimo in cima, stringendo i bicipiti. Inspira e abbassa lentamente il manubrio alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Bir elinizde bir dambılı nötr bir tutuşla (avuç içleri birbirine bakacak şekilde) tutun. Dirseğinizi uyluğunuzun iç kısmına, dizin hemen üstüne koyun. Üst kolunuzu sabit tutarak nefes verin ve dambılı omzunuza doğru kıvırın. Bicepslerinizi sıkarak tepede bir an duraklayın. Nefes alın ve dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí). Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Возьмите гантель в одну руку нейтральным хватом (ладони обращены друг к другу). Положите локоть на внутреннюю часть бедра, чуть выше колена. Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу. Задержитесь на мгновение в верхней точке, напрягая бицепсы. Вдохните и медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 一只手握住哑铃，保持中立握姿（手掌相对）。 将肘部放在大腿内侧、膝盖上方。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在顶部暂停片刻，挤压你的二头肌。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। एक हाथ में तटस्थ पकड़ के साथ डम्बल पकड़ें (हथेलियाँ एक दूसरे के सामने)। अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें। अपनी ऊपरी भुजा को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें। अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें। श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na ławce, trzymając plecy proste i stopy płasko na podłodze. Trzymaj hantlę w jednej ręce chwytem neutralnym (dłonie skierowane do siebie). Oprzyj łokieć o wewnętrzną stronę uda, tuż nad kolanem. Utrzymując nieruchome ramię, wykonaj wydech i unieś hantlę w stronę barku. Zatrzymaj się na chwilę na górze, ściskając biceps. Wykonaj wdech i powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 앉아 등을 펴고 발을 바닥에 평평하게 놓으세요. 한쪽 팔에 덤벨을 잡고 중립 그립(손바닥이 서로 향함)으로 하세요. 팔꿈치를 넓적다리 안쪽에 무릎 바로 위에 얹으세요. 팔 위쪽을 고정하고 숨을 내쉬며 덤벨을 어깨 쪽으로 말아올리세요. 위에서 잠깐 멈춘 후 이두근을 꽉 조이세요. 숨을 들이쉬며 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un haltère dans une main avec une prise neutre (paumes tournées l''une vers l''autre). Pose ton coude sur l''intérieur de ta cuisse, juste au-dessus du genou. En gardant le haut du bras immobile, expire et fléchis l''haltère vers ton épaule. Marque une pause en haut, en contractant tes biceps. Inspire et abaisse lentement l''haltère jusqu''à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1669-jK2hZ6n.jpg', 'videos/1669-jK2hZ6n.gif', '© Gym visual — https://gymvisual.com/'),
(1415, 'dumbbell one arm seated neutral wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","brachialis"]'::jsonb, '{"en":"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up. Rest your forearm on your thigh, allowing your wrist to hang off the edge. Keeping your forearm stationary, curl your wrist upward as far as possible. Pause for a moment at the top, then slowly lower your wrist back down to the starting position. Repeat for the desired number of repetitions, then switch to the other hand.","it":"Siediti su una panchina con i piedi piatti a terra e tieni un manubrio in una mano, con il palmo rivolto verso l''alto. Appoggia l''avambraccio sulla coscia, lasciando che il polso pendi dal bordo. Mantenendo fermo l''avambraccio, piega il polso verso l''alto il più possibile. Fermati un attimo in cima, poi abbassa lentamente il polso fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni, poi passa all''altra mano.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta oturun ve bir elinizde avuç içi yukarı bakacak şekilde bir dambıl tutun. Ön kolunuzu uyluğunuzun üzerine yaslayın, bileğinizin kenardan sarkmasına izin verin. Ön kolunuzu sabit tutarak bileğinizi mümkün olduğunca yukarı doğru kıvırın. Tepe noktasında bir an duraklayın, ardından bileğinizi yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer elinize geçin.","es":"Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde. Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra mano.","ru":"Сядьте на скамью, поставьте ноги на землю и возьмите в одну руку гантель ладонью вверх. Положите предплечье на бедро, позволяя запястью свисать с края. Удерживая предплечье неподвижно, согните запястье вверх как можно дальше. Pause for a moment at the top, then slowly lower your wrist back down to the starting position. Повторите необходимое количество повторений, затем переключитесь на другую руку.","zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。 将前臂放在大腿上，让手腕悬在边缘。 保持前臂静止，尽可能向上弯曲手腕。 在顶部暂停片刻，然后慢慢将手腕放回起始位置。 重复所需的重复次数，然后换另一只手。","hi":"अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली ऊपर की ओर रखें। अपनी बांह को अपनी जांघ पर टिकाएं, जिससे आपकी कलाई किनारे से लटक जाए। अपनी बांह को स्थिर रखते हुए, अपनी कलाई को जहां तक ​​संभव हो ऊपर की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाई को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरी ओर स्विच करें।","pl":"Usiądź na ławce, stopy oprzyj płasko na podłodze, i trzymaj hantlę w jednej ręce, dłonią skierowaną do góry. Oprzyj przedramię na udzie, pozwalając nadgarstkowi zwisać poza krawędzią. Utrzymując nieruchome przedramię, zegnij nadgarstek do góry tak daleko, jak to możliwe. Zatrzymaj się na chwilę na górze, a następnie powoli opuść nadgarstek z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 앉아 발을 바닥에 평평하게 놓고 한쪽 팔에 덤벨을 잡아 손바닥이 위를 향하도록 하세요. 전완을 넓적다리에 얹고 손목이 가장자리에서 튀어나오도록 하세요. 전완을 고정하고 손목을 위쪽으로 가능한 멀리 말아올리세요. 위에서 잠깐 멈춘 후 천천히 손목을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 손으로 전환하세요.","fr":"Assieds-toi sur un banc, les pieds à plat sur le sol, et tiens un haltère dans une main, paume tournée vers le haut. Pose ton avant-bras sur ta cuisse, en laissant ton poignet dépasser du bord. En gardant ton avant-bras immobile, fléchis ton poignet vers le haut aussi loin que possible. Marque une pause en haut, puis abaisse lentement ton poignet pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis passe à l''autre main."}'::jsonb, 'images/1415-YtaCTYl.jpg', 'videos/1415-YtaCTYl.gif', '© Gym visual — https://gymvisual.com/'),
(361, 'dumbbell one arm shoulder press', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'triceps', 'delts', '["triceps","upper back"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward. Press the dumbbell upward until your arm is fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Stai in piedi con i piedi alla larghezza delle spalle e tieni un manubrio con una mano all''altezza delle spalle, palmo rivolto in avanti. Premi il manubrio verso l''alto finché il braccio non è completamente esteso sopra la testa. Fermati un attimo in cima, poi abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde bir dambılı omuz hizasında, avuç içi öne bakacak şekilde tutun. Kolunuz tamamen yukarı doğru uzanana kadar dambılı yukarıya doğru bastırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Встаньте, ноги на ширине плеч, в одной руке держите гантель на уровне плеч ладонью вперед. Нажмите гантель вверх, пока ваша рука полностью не выпрямится над головой. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。 向上推哑铃，直到手臂完全伸过头顶。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में कंधे के स्तर पर डंबल पकड़ें, हथेली आगे की ओर हो। डम्बल को तब तक ऊपर की ओर दबाएँ जब तक कि आपका हाथ पूरी तरह से ऊपर की ओर न फैल जाए। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Stań w rozkroku na szerokość barków, trzymając hantlę w jednej ręce na wysokości barku, dłonią skierowaną do przodu. Wypchnij hantlę do góry, aż ramię będzie w pełni wyprostowane nad głową. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"발을 어깨 너비로 벌리고 서서 한쪽 팔에 덤벨을 어깨 높이에 잡고 손바닥이 앞을 향하도록 하세요. 팔이 완전히 펴질 때까지 덤벨을 위로 누르세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère d''une main à hauteur d''épaule, paume tournée vers l''avant. Pousse l''haltère vers le haut jusqu''à ce que ton bras soit complètement tendu au-dessus de ta tête. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/0361-84RyJf8.jpg', 'videos/0361-84RyJf8.gif', '© Gym visual — https://gymvisual.com/'),
(360, 'dumbbell one arm shoulder press v. 2', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'triceps', 'delts', '["triceps","upper back"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward. Engage your core and press the dumbbell straight up overhead, fully extending your arm. Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Stai in piedi con i piedi alla larghezza delle spalle e tieni un manubrio con una mano all''altezza delle spalle, palmo rivolto in avanti. Attiva il core e premi il manubrio dritto sopra la testa, estendendo completamente il braccio. Fermati un attimo in cima, poi abbassa lentamente il manubrio all''altezza delle spalle. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınızı omuz genişliğinde açın ve bir elinizde bir dambılı omuz hizasında, avuç içi öne bakacak şekilde tutun. Merkez bölgenizi devreye sokun ve kolunuzu tamamen uzatarak dambılları yukarıya doğru bastırın. Tepe noktasında bir an duraklayın, ardından dambılı yavaşça omuz hizasına indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante. Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo. Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Встаньте, ноги на ширине плеч, в одной руке держите гантель на уровне плеч ладонью вперед. Напрягите корпус и поднимите гантель прямо над головой, полностью выпрямляя руку. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно на уровень плеч. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。 启动核心肌群，将哑铃垂直推过头顶，充分伸展手臂。 在顶部停顿片刻，然后慢慢将哑铃放回肩部水平。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में कंधे के स्तर पर डंबल पकड़ें, हथेली आगे की ओर हो। अपने कोर को संलग्न करें और अपनी बांह को पूरी तरह फैलाते हुए डंबल को सीधे ऊपर की ओर दबाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस कंधे के स्तर तक नीचे लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Stań w rozkroku na szerokość barków, trzymając hantlę w jednej ręce na wysokości barku, dłonią skierowaną do przodu. Napnij brzuch i wypchnij hantlę prosto do góry nad głowę, w pełni prostując rękę. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem na wysokość barku. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"발을 어깨 너비로 벌리고 서서 한쪽 팔에 덤벨을 어깨 높이에 잡고 손바닥이 앞을 향하도록 하세요. 코어를 단단히 하고 덤벨을 위로 일직선으로 누르며 팔을 완전히 펼치세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 어깨 높이로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère d''une main à hauteur d''épaule, paume tournée vers l''avant. Gaine ta sangle abdominale et pousse l''haltère droit au-dessus de ta tête, en étendant complètement ton bras. Marque une pause en haut, puis abaisse lentement l''haltère à hauteur des épaules. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/0360-1TkiAFK.jpg', 'videos/0360-1TkiAFK.gif', '© Gym visual — https://gymvisual.com/'),
(3888, 'dumbbell one arm snatch', 'upper legs', 'strength', 'upper legs', 'dumbbell', 'hamstrings', 'glutes', '["hamstrings","quadriceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Lower the dumbbell towards the ground, keeping it close to your body. Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line. As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm. Catch the dumbbell overhead with a slight bend in your knees and hips. Lower the dumbbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in una mano con una presa sopra la mano. Flette leggermente le ginocchia e piega in avanti sui fianchi, mantenendo la schiena dritta e il petto sollevato. Abbassa il manubrio verso terra, tenendolo vicino al corpo. Estendi esplosivamente anche fianchi, ginocchia e caviglie, spingendo il manubello verso l''alto in linea retta. Quando il manubrio raggiunge l''altezza delle spalle, ruota rapidamente la mano e colpiscilo sopra la testa, estendendo completamente il braccio. Afferra il manubrio sopra la testa con una leggera piega di ginocchia e fianchi. Abbassa il manubrio di nuovo alla posizione di partenza in modo controllato. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınızı omuz genişliğinde açın, bir elinizde bir dambılı üstten kavrayarak tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun. Dambılı vücudunuza yakın tutarak yere doğru indirin. Kalçalarınızı, dizlerinizi ve ayak bileklerinizi patlayıcı bir şekilde uzatarak dambılı düz bir çizgide yukarı doğru hareket ettirin. Dambıl omuz yüksekliğine ulaştığında elinizi hızla döndürün ve kolunuzu tamamen uzatarak başınızın üstüne yumruk atın. Dizlerinizi ve kalçalarınızı hafifçe bükerek dambılı başınızın üstünde tutun. Dambılı kontrollü bir şekilde başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo. Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta. Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo. Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Встаньте, ноги на ширине плеч, держите гантель в одной руке хватом сверху. Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх. Опустите гантель к земле, держа ее близко к телу. Взрывно выпрямите бедра, колени и лодыжки, поднимая гантель вверх по прямой линии. Когда гантель достигнет высоты плеч, быстро поверните руку и ударьте ею над головой, полностью выпрямляя руку. Возьмите гантель над головой, слегка согнув колени и бедра. Контролируемым образом опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"双脚分开与肩同宽站立，一只手握住哑铃，正握。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 将哑铃向地面放低，使其靠近身体。 爆发性伸展臀部、膝盖和脚踝，将哑铃沿直线向上推。 当哑铃到达肩膀高度时，快速旋转你的手并将其击打过头顶，充分伸展你的手臂。 将哑铃举过头顶，膝盖和臀部稍微弯曲。 以受控的方式将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें। डम्बल को अपने शरीर के पास रखते हुए जमीन की ओर नीचे करें। अपने कूल्हों, घुटनों और टखनों को तेजी से फैलाएँ, डम्बल को एक सीधी रेखा में ऊपर की ओर ले जाएँ। जैसे ही डम्बल कंधे की ऊंचाई तक पहुंचता है, तेजी से अपना हाथ घुमाएं और अपनी बांह को पूरी तरह फैलाते हुए इसे ऊपर की ओर मुक्का मारें। अपने घुटनों और कूल्हों को थोड़ा मोड़कर डम्बल को ऊपर की ओर पकड़ें। डम्बल को नियंत्रित तरीके से वापस प्रारंभिक स्थिति में लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Stań w rozkroku na szerokość barków, trzymając hantlę w jednej ręce chwytem nachwytem. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową. Opuść hantlę w stronę podłogi, trzymając ją blisko ciała. Gwałtownie wyprostuj biodra, kolana i kostki, wyrzucając hantlę w górę po prostej linii. Gdy hantla osiągnie wysokość barku, szybko obróć dłoń i wypchnij ją nad głowę, w pełni prostując rękę. Złap hantlę nad głową z lekkim ugięciem kolan i bioder. Opuść hantlę z powrotem do pozycji wyjściowej w kontrolowany sposób. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"발을 어깨 너비로 벌리고 서서 한쪽 팔에 덤벨을 오버핸드 그립으로 잡으세요. 무릎을 약간 구부리고 엉덩이에서 몸을 앞으로 기울이며 등을 펴고 가슴을 올린 상태를 유지하세요. 덤벨을 몸에 가깝게 유지하며 바닥 쪽으로 내리세요. 엉덩이, 무릎, 발목을 폭발적으로 펴며 덤벨을 위로 일직선으로 몸을 밀어올리세요. 덤벨이 어깨 높이에 도달하면 빠르게 손을 돌려 위로 누르며 팔을 완전히 펼치세요. 무릎과 엉덩이를 약간 구부린 상태로 덤벨을 위에서 잡으세요. 조절하며 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère d''une main en prise pronation. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et la poitrine relevée. Abaisse l''haltère vers le sol, en le gardant près de ton corps. Étends de manière explosive tes hanches, tes genoux et tes chevilles, en propulsant l''haltère vers le haut en ligne droite. Lorsque l''haltère atteint la hauteur des épaules, fais rapidement pivoter ta main et propulse-le au-dessus de la tête en étendant complètement ton bras. Réceptionne l''haltère au-dessus de ta tête avec une légère flexion des genoux et des hanches. Abaisse l''haltère jusqu''à la position de départ de manière contrôlée. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/3888-6pTkI99.jpg', 'videos/3888-6pTkI99.gif', '© Gym visual — https://gymvisual.com/'),
(1670, 'dumbbell one arm standing curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended. Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Alzati dritto con un manubrio in una mano, palmo rivolto in avanti e braccio completamente esteso. Mantenendo fermo la parte superiore del braccio, espira e arriccia il peso verso l''alto mentre contrai i bicipiti. Continua ad alzare il manubrio finché i bicipiti non sono completamente contratti e il manubrio non è all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e abbassa lentamente il manubrio alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Bir elinizde bir dambıl ile dik durun, avuç içi öne doğru baksın ve kol tamamen uzatılmış olsun. Üst kolunuzu sabit tutarak nefes verin ve bicepslerinizi kasarken ağırlığı yukarı doğru kıvırın. Bisepsleriniz tamamen kasılana ve dambıl omuz hizasına gelene kadar dambılı kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Встаньте прямо, возьмите гантель в одну руку, ладонь вперед и полностью выпрямите руку. Удерживая плечо неподвижно, выдохните и поднимите вес вверх, одновременно сокращая бицепсы. Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"站直，一手握哑铃，手掌朝前，手臂完全伸展。 保持上臂静止，呼气并向上弯曲重量，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"एक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेली आगे की ओर और हाथ पूरी तरह फैला हुआ हो। अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को ऊपर की ओर मोड़ें। डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Stań prosto, trzymając hantlę w jednej ręce, dłonią skierowaną do przodu, ramię w pełni wyprostowane. Utrzymując nieruchome ramię, wykonaj wydech i unieś ciężar, napinając biceps. Unoś hantlę, aż biceps będzie maksymalnie napięty, a hantla znajdzie się na wysokości barku. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"몸을 곧게 펴고 서서 한쪽 팔에 덤벨을 잡고 손바닥이 앞을 향하며 팔을 완전히 펼친 상태로 하세요. 팔 위쪽을 고정하고 숨을 내쉬며 이두근을 수축시키며 무게를 위로 말아올리세요. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 도달할 때까지 계속 올리세요. 이두근을 꽉 조이며 잠깐 수축된 상태를 유지하세요. 숨을 들이쉬며 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Tiens-toi bien droit avec un haltère dans une main, la paume tournée vers l''avant et le bras complètement tendu. En gardant le haut du bras immobile, expire et fléchis le poids vers le haut en contractant tes biceps. Continue à lever l''haltère jusqu''à ce que ton biceps soit complètement contracté et que l''haltère soit à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et abaisse lentement l''haltère jusqu''à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1670-ffQsyBj.jpg', 'videos/1670-ffQsyBj.gif', '© Gym visual — https://gymvisual.com/'),
(1671, 'dumbbell one arm standing hammer curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Stai dritto con un manubrio in ogni mano, i palmi rivolti verso il busto. Tieni i gomiti vicini al busto e le braccia superiori ferme. Espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i pesi finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Her iki elinizde de birer dambıl olacak şekilde dik durun, avuçlarınız gövdenize bakacak şekilde. Dirseklerinizi gövdenize yakın ve üst kollarınızı sabit tutun. Bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar ağırlıkları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу. Держите локти близко к туловищу, а плечи неподвижны. Выдохните и согните штангу, одновременно сокращая бицепсы. Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，上臂保持静止。 呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。","hi":"प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों। अपनी कोहनियों को अपने धड़ के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें। सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन मोड़ें। जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań prosto, trzymając w każdej dłoni hantlę, dłonie skierowane w stronę tułowia. Trzymaj łokcie blisko tułowia, a ramiona nieruchomo. Wykonaj wydech i unieś ciężarki, napinając biceps. Unoś ciężarki, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"몸을 곧게 펴고 서서 양쪽 팔에 덤벨을 잡고 손바닥이 몸통을 향하도록 하세요. 팔꿈치를 몸통에 가깝게 유지하고 팔 위쪽을 고정하세요. 숨을 내쉬며 이두근을 수축시키며 무게를 말아올리세요. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 도달할 때까지 계속 올리세요. 이두근을 꽉 조이며 잠깐 수축된 상태를 유지하세요. 숨을 들이쉬며 천천히 덤벨을 시작 위치로 내리기 시작하세요. 원하는 횟수만큼 반복하세요.","fr":"Tiens-toi bien droit avec un haltère dans chaque main, les paumes tournées vers ton torse. Garde tes coudes près de ton torse et le haut de tes bras immobile. Expire et remonte les poids en contractant tes biceps. Continue à lever les poids jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et commence lentement à abaisser les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1671-2sQGZ5b.jpg', 'videos/1671-2sQGZ5b.gif', '© Gym visual — https://gymvisual.com/'),
(362, 'dumbbell one arm triceps extension (on bench)', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'shoulders', 'triceps', '["shoulders"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in one hand and place your other hand on the bench for support. Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward. Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary. Extend your arm back up to the starting position, fully straightening your elbow. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una panchina con la schiena dritta e i piedi piatti a terra. Tieni un manubrio con una mano e appoggia l''altra mano sulla panca per sostenerti. Alza il manubrio sopra la testa, tenendo il braccio superiore vicino alla testa e il gomito puntato in avanti. Abbassa il manubrio dietro la testa piegando il gomito, mantenendo fermo il braccio superiore. Allunga il braccio fino alla posizione iniziale, raddrizzando completamente il gomito. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Bir elinizde dambıl tutun ve diğer elinizi destek için benchin üzerine koyun. Üst kolunuzu başınıza yakın ve dirseğiniz ileriyi gösterecek şekilde dambılı başınızın üzerine kaldırın. Dirseğinizi bükerek, üst kolunuzu sabit tutarak dambılı başınızın arkasına indirin. Dirseğinizi tamamen düzleştirerek kolunuzu başlangıç ​​pozisyonuna kadar uzatın. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Возьмите гантель в одну руку, а другую руку положите на скамью для поддержки. Поднимите гантель над головой, держа плечо близко к голове и локоть направленным вперед. Опустите гантель за голову, согнув локоть, сохраняя плечо неподвижным. Вытяните руку обратно в исходное положение, полностью выпрямляя локоть. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 一手握住哑铃，另一只手放在长凳上以获得支撑。 将哑铃举过头顶，保持上臂靠近头部，肘部向前。 弯曲肘部，将哑铃降低到头后，保持上臂静止。 将手臂向后伸展至起始位置，完全伸直肘部。 重复所需的重复次数，然后换臂。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। एक हाथ में डम्बल पकड़ें और समर्थन के लिए अपने दूसरे हाथ को बेंच पर रखें। डम्बल को ऊपर उठाएं, अपनी ऊपरी भुजा को अपने सिर के पास रखें और अपनी कोहनी को आगे की ओर रखें। अपनी ऊपरी भुजा को स्थिर रखते हुए, अपनी कोहनी को मोड़कर डम्बल को अपने सिर के पीछे नीचे लाएँ। अपनी कोहनी को पूरी तरह से सीधा करते हुए, अपनी भुजा को वापस प्रारंभिक स्थिति तक फैलाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na ławce, trzymając plecy proste i stopy płasko na podłodze. Trzymaj hantlę w jednej ręce, a drugą oprzyj na ławce dla stabilizacji. Unieś hantlę nad głowę, trzymając ramię blisko głowy, a łokieć skierowany do przodu. Opuszczaj hantlę za głowę, zginając łokieć i utrzymując nieruchome ramię. Wyprostuj rękę z powrotem do pozycji wyjściowej, w pełni prostując łokieć. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 앉아 등을 펴고 발을 바닥에 평평하게 놓으세요. 한쪽 팔에 덤벨을 잡고 다른 손을 벤치에 놓아 지지하세요. 덤벨을 위로 올려 팔 위쪽이 머리 가까이 있고 팔꿈치가 앞을 향하도록 하세요. 팔꿈치를 구부려 덤벨을 머리 뒤로 내리고 팔 위쪽은 고정된 상태로 유지하세요. 팔을 시작 위치로 완전히 펴세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un haltère dans une main et pose ton autre main sur le banc pour te soutenir. Lève l''haltère au-dessus de ta tête en gardant le haut de ton bras près de ta tête et ton coude pointé vers l''avant. Abaisse l''haltère derrière ta tête en fléchissant ton coude, en gardant le haut de ton bras immobile. Étends ton bras pour revenir vers le haut en position de départ, en redressant complètement ton coude. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/0362-nAuHPcD.jpg', 'videos/0362-nAuHPcD.gif', '© Gym visual — https://gymvisual.com/'),
(363, 'dumbbell one arm upright row', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'traps', 'delts', '["traps","biceps"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip. Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body. Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in una mano con una presa sopra la mano. Lascia che il manubrio penda a distanza di braccio davanti alle cosce, con il palmo rivolto verso il corpo. Tenendo la schiena dritta e il core attivo, espira e solleva il manubrio verso il mento, iniziando con il gomito. Fermati un attimo in cima, poi inspira e abbassa lentamente il manubrio fino alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınızı omuz genişliğinde açın, bir elinizde bir dambılı üstten kavrayarak tutun. Avucunuz vücudunuza bakacak şekilde dambılı kol boyu mesafede uyluklarınızın önünde asılı bırakın. Sırtınızı düz ve merkez bölgenizi meşgul tutarak nefes verin ve dambılı dirseğinizle birlikte çenenize doğru düz bir şekilde kaldırın. Tepe noktasında bir süre duraklayın, ardından nefes alın ve dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono. Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Встаньте, ноги на ширине плеч, держите гантель в одной руке хватом сверху. Пусть гантель висит на расстоянии вытянутой руки перед бедрами, ладонью к телу. Удерживая спину прямой и напрягая корпус, выдохните и поднимите гантель прямо вверх к подбородку, ведя локтем. Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"双脚分开与肩同宽站立，一只手握住哑铃，正握。 让哑铃悬挂在大腿前面，与手臂保持一定距离，手掌朝向身体。 保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ लें। डंबल को अपनी जांघों के सामने एक हाथ की दूरी पर लटकाएं, आपकी हथेली आपके शरीर की ओर हो। अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, सांस छोड़ें और डंबल को अपनी कोहनी की मदद से सीधे अपनी ठुड्डी की ओर उठाएं। शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Stań w rozkroku na szerokość barków, trzymając hantlę w jednej ręce chwytem nachwytem. Pozwól, aby hantla zwisała na wyprostowanej ręce przed udami, dłonią skierowaną do ciała. Utrzymując proste plecy i napięty brzuch, wykonaj wydech i unieś hantlę prosto w stronę podbródka, prowadząc ruch łokciem. Zatrzymaj się na chwilę na górze, a następnie wykonaj wdech i powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"발을 어깨 너비로 벌리고 서서 한쪽 팔에 덤벨을 오버핸드 그립으로 잡으세요. 덤벨을 팔 길이만큼 매달아 넓적다리 앞에 있고 손바닥이 몸을 향하도록 하세요. 등을 펴고 코어를 단단히 하며 숨을 내쉬고 덤벨을 턱 쪽으로 위로 들어올리고 팔꿈치를 앞으로 유도하세요. 위에서 잠깐 멈춘 후 숨을 들이쉬며 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère d''une main en prise pronation. Laisse l''haltère pendre à bout de bras devant tes cuisses, la paume tournée vers ton corps. En gardant le dos droit et ta sangle abdominale gainée, expire et soulève l''haltère droit vers ton menton, en menant avec ton coude. Marque une pause en haut, puis inspire et abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/0363-6cKQC5E.jpg', 'videos/0363-6cKQC5E.gif', '© Gym visual — https://gymvisual.com/'),
(364, 'dumbbell one arm wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","brachialis"]'::jsonb, '{"en":"Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh. Allow your wrist to extend, letting the dumbbell roll down towards your fingers. Slowly curl your wrist back up, bringing the dumbbell towards your forearm. Repeat for the desired number of repetitions, then switch to the other hand.","it":"Siediti su una panca o una sedia con i piedi piatti a terra. Tieni un manubrio in una mano con una presa sotto, appoggiando l''avambraccio sulla coscia. Lascia che il polso si estenda, lasciando che il manubrio rotoli verso le dita. Ripiega lentamente il polso verso l''alto, portando il manubrio verso l''avambraccio. Ripeti per il numero desiderato di ripetizioni, poi passa all''altra mano.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun. Bir elinizde bir dambılı alttan kavrayarak tutun, ön kolunuzu uyluğunuzun üzerine yaslayın. Bileğinizin uzamasına izin vererek dambılın parmaklarınıza doğru yuvarlanmasına izin verin. Bileğinizi yavaşça yukarı doğru kıvırın ve dambılı ön kolunuza doğru getirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer elinize geçin.","es":"Siéntate en un banco o silla con los pies apoyados en el suelo. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo. Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Repite el número de repeticiones deseado, luego cambia a la otra mano.","ru":"Сядьте на скамью или стул, поставив ноги на землю. Возьмите гантель в одну руку обратным хватом, положив предплечье на бедро. Позвольте запястью выпрямиться, позволяя гантеле скатиться вниз к вашим пальцам. Медленно согните запястье вверх, поднося гантель к предплечью. Повторите необходимое количество повторений, затем переключитесь на другую руку.","zh":"坐在长凳或椅子上，双脚平放在地面上。 一只手握住哑铃，反握，将前臂放在大腿上。 让你的手腕伸展，让哑铃向你的手指方向滚动。 慢慢地向后弯曲手腕，将哑铃拉向前臂。 重复所需的重复次数，然后换另一只手。","hi":"अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें। एक हाथ में डम्बल पकड़ें, अपने अग्रबाहु को अपनी जाँघ पर टिकाएँ। अपनी कलाई को फैलने दें, डम्बल को अपनी उंगलियों की ओर लुढ़कने दें। धीरे-धीरे अपनी कलाई को पीछे की ओर मोड़ें, डम्बल को अपनी बांह की ओर लाएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरी ओर स्विच करें।","pl":"Usiądź na ławce lub krześle, stopy oprzyj płasko na podłodze. Trzymaj hantlę w jednej ręce chwytem podchwytem, opierając przedramię na udzie. Pozwól nadgarstkowi się wyprostować, tak aby hantla toczyła się w stronę palców. Powoli zegnij nadgarstek z powrotem, przyciągając hantlę w stronę przedramienia. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"벤치나 의자에 앉아 발을 바닥에 평평하게 놓으세요. 한쪽 팔에 언더핸드 그립으로 덤벨을 잡고 전완을 넓적다리에 얹으세요. 손목을 펴서 덤벨을 손가락 쪽으로 천천히 굴리세요. 천천히 손목을 다시 말아올려 덤벨을 전완 쪽으로 가져오세요. 원하는 횟수만큼 반복한 후 다른 손으로 전환하세요.","fr":"Assieds-toi sur un banc ou une chaise, les pieds à plat sur le sol. Tiens un haltère dans une main avec une prise en supination, en posant ton avant-bras sur ta cuisse. Laisse ton poignet s''étendre en laissant l''haltère rouler vers tes doigts. Enroule lentement ton poignet vers le haut, en ramenant l''haltère vers ton avant-bras. Répète le nombre de répétitions souhaité, puis passe à l''autre main."}'::jsonb, 'images/0364-q8aHNoF.jpg', 'videos/0364-q8aHNoF.gif', '© Gym visual — https://gymvisual.com/'),
(1672, 'dumbbell one arm zottman preacher curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip. Rest your upper arm on the preacher bench pad, allowing your arm to fully extend. Curl the dumbbell up towards your shoulder, keeping your upper arm stationary. At the top of the curl, rotate your wrist so that your palm faces up. Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una panca da curl preacher e tieni un manubrio in una mano con una presa sotto. Appoggia il braccio superiore sul cuscinetto da panca predicatorio, permettendo al braccio di estendersi completamente. Arrotola il manubrio verso la spalla, tenendo fermo il braccio superiore. In cima al curl, ruota il polso in modo che il palmo sia rivolto verso l''alto. Abbassa lentamente il manubrio fino alla posizione di partenza, ruotando il polso di nuovo alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Bir vaiz kıvırma tezgahına oturun ve bir elinizde bir dambılı alttan kavrayarak tutun. Üst kolunuzu vaiz bankının yastığına dayayarak kolunuzun tamamen uzamasına izin verin. Üst kolunuzu sabit tutarak dambılı omzunuza doğru kıvırın. Kıvrımın üst noktasında, avucunuz yukarı bakacak şekilde bileğinizi döndürün. Bileğinizi başlangıç ​​pozisyonuna döndürerek dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino. Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente. Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto. En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba. Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на скамью для сгибаний рук и возьмите гантель в одну руку обратным хватом. Положите плечо на подушку скамьи проповедника, позволяя руке полностью выпрямиться. Поднимите гантель к плечу, сохраняя плечо неподвижным. В верхней части сгиба поверните запястье ладонью вверх. Медленно опустите гантель обратно в исходное положение, поворачивая запястье обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在牧师弯举凳上，单手握哑铃，反握。 将上臂放在牧师凳垫上，让手臂完全伸展。 将哑铃向上弯向肩膀，保持上臂静止。 在卷曲的顶部，旋转手腕，使手掌朝上。 慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。 重复所需的重复次数，然后换臂。","hi":"प्रीचर कर्ल बेंच पर बैठें और एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें। अपनी ऊपरी बांह को उपदेशक बेंच पैड पर रखें, जिससे आपकी बांह पूरी तरह से फैल सके। अपनी ऊपरी भुजा को स्थिर रखते हुए, डम्बल को अपने कंधे की ओर मोड़ें। कर्ल के शीर्ष पर, अपनी कलाई को घुमाएं ताकि आपकी हथेली ऊपर की ओर रहे। धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएं, अपनी कलाई को वापस प्रारंभिक स्थिति में घुमाएँ। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na ławce modlitewnej (Scotta) i trzymaj hantlę w jednej ręce chwytem podchwytem. Oprzyj ramię na podkładce ławki, pozwalając mu się w pełni wyprostować. Unieś hantlę w stronę barku, utrzymując nieruchome ramię. Na górze ruchu obróć nadgarstek tak, aby dłoń była skierowana do góry. Powoli opuść hantlę z powrotem do pozycji wyjściowej, obracając nadgarstek z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"프리처 컬 벤치에 앉아 한쪽 팔에 언더핸드 그립으로 덤벨을 잡으세요. 팔 위쪽을 프리처 벤치 패드에 얹고 팔을 완전히 펼친 상태로 하세요. 팔 위쪽을 고정하고 덤벨을 어깨 쪽으로 말아올리세요. 컬의 위쪽에서 손목을 돌려 손바닥이 위를 향하도록 하세요. 천천히 덤벨을 시작 위치로 내리며 손목을 시작 위치로 다시 돌리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un banc à prêcheur et tiens un haltère dans une main avec une prise en supination. Pose le haut de ton bras sur le coussin du banc à prêcher, en laissant ton bras s''étendre complètement. Enroule l''haltère vers ton épaule, en gardant ton bras immobile. En haut de la flexion, tourne ton poignet pour que ta paume soit tournée vers le haut. Abaisse lentement l''haltère vers la position de départ, en tournant ton poignet vers la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1672-sxY5Biu.jpg', 'videos/1672-sxY5Biu.gif', '© Gym visual — https://gymvisual.com/'),
(1292, 'dumbbell one leg fly on exercise ball', 'chest', 'strength', 'chest', 'dumbbell', 'shoulders', 'pectorals', '["shoulders","triceps"]'::jsonb, '{"en":"Sit on an exercise ball with a dumbbell in each hand, palms facing each other. Place one foot on the ground and extend the other leg straight out in front of you. Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows. Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest. Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.","it":"Siediti su una palla da ginnastica con un manubrio in ogni mano, i palmi rivolti uno verso l''altro. Metti un piede a terra e estendi l''altra gamba dritta davanti a te. Inclinati leggermente in avanti e porta le braccia ai lati, mantenendo una leggera piega dei gomiti. Abbassa lentamente i manubri e i tiri ai lati, sentendo uno stiramento al petto. Fermati un attimo in basso, poi stringi i muscoli del petto per riportare i manubri alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni, poi cambia gamba e ripeti.","tr":"Her iki elinizde birer dambıl olacak şekilde, avuçlarınız birbirine bakacak şekilde bir egzersiz topunun üzerine oturun. Bir ayağınızı yere koyun ve diğer bacağınızı düz bir şekilde önünüze doğru uzatın. Hafifçe öne doğru eğilin ve kollarınızı yanlara doğru açın, dirseklerinizi hafif bükülü tutun. Göğsünüzde bir gerginlik hissederek dambılları yavaşça aşağıya ve yanlara doğru indirin. Altta bir an duraklayın, ardından dambılları başlangıç ​​pozisyonuna geri getirmek için göğüs kaslarınızı sıkın. İstenilen tekrar sayısı kadar tekrarlayın, ardından bacak değiştirin ve tekrarlayın.","es":"Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante. Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho. Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.","ru":"Сядьте на гимнастический мяч, взяв в каждую руку по гантели, ладонями друг к другу. Поставьте одну ногу на землю и вытяните другую ногу прямо перед собой. Слегка наклонитесь вперед и разведите руки в стороны, сохраняя небольшой изгиб в локтях. Медленно опустите гантели вниз и в стороны, чувствуя растяжение в груди. Задержитесь на мгновение в нижней точке, затем сожмите мышцы груди, чтобы вернуть гантели в исходное положение. Повторите необходимое количество повторений, затем поменяйте ногу и повторите.","zh":"坐在健身球上，双手各握一个哑铃，手掌相对。 将一只脚放在地面上，并将另一条腿伸直到您面前。 稍微向前倾，将手臂向两侧伸出，保持肘部轻微弯曲。 慢慢地将哑铃向两侧放低，感觉胸部有拉伸感。 在底部暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。 重复所需的重复次数，然后换腿并重复。","hi":"प्रत्येक हाथ में डम्बल लेकर व्यायाम गेंद पर बैठें, हथेलियाँ एक-दूसरे के सामने हों। एक पैर को ज़मीन पर रखें और दूसरे पैर को अपने सामने सीधा फैला लें। थोड़ा आगे झुकें और अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर लाएँ। अपनी छाती में खिंचाव महसूस करते हुए धीरे-धीरे डम्बल को नीचे और बाहर की ओर नीचे करें। नीचे एक पल के लिए रुकें, फिर डम्बल को शुरुआती स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें। दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।","pl":"Usiądź na piłce gimnastycznej, trzymając w każdej dłoni hantlę, dłonie skierowane do siebie. Postaw jedną stopę na podłodze, a drugą nogę wyprostuj prosto przed sobą. Pochyl się lekko do przodu i wyprowadź ręce na boki, utrzymując lekkie ugięcie w łokciach. Powoli opuszczaj hantle w dół i na boki, czując rozciąganie w klatce piersiowej. Zatrzymaj się na chwilę na dole, a następnie napnij mięśnie klatki piersiowej, aby wrócić hantlami do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień nogę i powtórz.","ko":"운동 공에 앉아 양쪽 팔에 덤벨을 잡고 손바닥이 서로 향하도록 하세요. 한쪽 발을 바닥에 놓고 다른 쪽 다리를 앞으로 쭉 펴세요. 몸을 약간 앞으로 기울이고 팔을 옆으로 가져가며 팔꿈치를 약간 구부린 상태로 유지하세요. 덤벨을 천천히 옆으로 아래로 내리며 가슴의 스트레치를 느끼세요. 아래에서 잠깐 멈춘 후 가슴 근육을 조여 덤벨을 시작 위치로 올리세요. 원하는 횟수만큼 반복한 후 다리를 바꾸고 반복하세요.","fr":"Assieds-toi sur un ballon d''exercice avec un haltère dans chaque main, paumes tournées l''une vers l''autre. Place un pied au sol et étends l''autre jambe droit devant toi. Penche-toi légèrement en avant et écarte tes bras sur les côtés, en gardant une légère flexion dans les coudes. Abaisse lentement les haltères vers le bas et vers les côtés, en ressentant un étirement dans ta poitrine. Marque une pause en bas, puis contracte tes muscles pectoraux pour ramener les haltères vers le haut jusqu''à la position de départ. Répète le nombre de répétitions souhaité, puis change de jambe et recommence."}'::jsonb, 'images/1292-pH2x2jj.jpg', 'videos/1292-pH2x2jj.gif', '© Gym visual — https://gymvisual.com/'),
(365, 'dumbbell over bench neutral wrist curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panchina con i piedi piatti a terra e tieni un manubrio in ciascuna mano, palmi rivolti verso l''alto. Appoggia gli avambracci sulla panca, lasciando che i polsi penzolano dal bordo. Tieni ferme le braccia superiori, espira e arriccia i manubri verso le spalle. Fermati un attimo in cima, poi inspira e abbassa lentamente i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta oturun ve avuç içleriniz yukarı bakacak şekilde her iki elinizde birer dambıl tutun. Önkollarınızı bankın üzerine yaslayın, bileklerinizin kenardan sarkmasına izin verin. Üst kollarınızı sabit tutarak nefes verin ve dambılları omuzlarınıza doğru kıvırın. Tepe noktasında bir süre duraklayın, ardından nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вверх. Положите предплечья на скамью так, чтобы запястья свисали с края. Удерживая плечи неподвижно, выдохните и поднимите гантели к плечам. Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。 将前臂放在长凳上，让手腕悬在长凳边缘。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर हों। अपनी बांहों को बेंच पर टिकाएं, जिससे आपकी कलाइयां किनारे से लटक जाएं। अपनी ऊपरी भुजाओं को स्थिर रखते हुए सांस छोड़ें और डम्बल को अपने कंधों की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce, stopy oprzyj płasko na podłodze, i trzymaj w każdej dłoni hantlę, dłonie skierowane do góry. Oprzyj przedramiona na ławce, pozwalając nadgarstkom zwisać poza krawędzią. Utrzymując nieruchome ramiona, wykonaj wydech i unieś hantle w stronę barków. Zatrzymaj się na chwilę na górze, a następnie wykonaj wdech i powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 발을 바닥에 평평하게 놓고 양쪽 팔에 덤벨을 잡아 손바닥이 위를 향하도록 하세요. 전완을 벤치에 얹고 손목이 가장자리에서 튀어나오도록 하세요. 팔 위쪽을 고정하고 숨을 내쉬며 덤벨을 어깨 쪽으로 말아올리세요. 위에서 잠깐 멈춘 후 숨을 들이쉬며 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복하세요.","fr":"Assieds-toi sur un banc, les pieds à plat sur le sol, et tiens un haltère dans chaque main, paumes tournées vers le haut. Pose tes avant-bras sur le banc, en laissant tes poignets dépasser du bord. En gardant le haut des bras immobile, expire et fléchis les haltères vers tes épaules. Marque une pause en haut, puis inspire et abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0365-BKa8dmT.jpg', 'videos/0365-BKa8dmT.gif', '© Gym visual — https://gymvisual.com/'),
(366, 'dumbbell over bench one arm neutral wrist curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up. Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Seduta su una panchina con un manubrio in una mano e il braccio esteso sopra la panca, il palmo rivolto verso l''alto. Mantieni fermo il braccio superiore e piega il manubrio verso la spalla, mantenendo il polso in posizione neutra. Fermati un attimo in cima, poi abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Bir elinizde bir dambıl olacak şekilde bir bankta oturun ve kolunuz avuç içi yukarı bakacak şekilde bankın üzerine uzatın. Üst kolunuzu sabit tutun ve bileğinizi nötr pozisyonda tutarak dambılı omzunuza doğru kıvırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на скамью, взяв в одну руку гантель, вытянув руку над скамьей ладонью вверх. Держите плечо неподвижно и согните гантель к плечу, сохраняя запястье в нейтральном положении. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在长凳上，一只手拿着哑铃，手臂伸过长凳，手掌朝上。 保持上臂静止，将哑铃向肩膀弯曲，使手腕保持在中立位置。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"एक हाथ में डम्बल लेकर एक बेंच पर बैठें और अपना हाथ बेंच के ऊपर फैला हुआ रखें, हथेली ऊपर की ओर। अपनी ऊपरी बांह को स्थिर रखें और अपनी कलाई को तटस्थ स्थिति में रखते हुए डंबल को अपने कंधे की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na ławce, trzymając hantlę w jednej ręce, z ramieniem wyprostowanym nad ławką, dłonią skierowaną do góry. Utrzymuj nieruchome ramię i unieś hantlę w stronę barku, trzymając nadgarstek w pozycji neutralnej. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"벤치에 앉아 한쪽 팔에 덤벨을 잡고 팔을 벤치 위로 펼쳐 손바닥이 위를 향하도록 하세요. 팔 위쪽을 고정하고 덤벨을 어깨 쪽으로 말아올리며 손목을 중립 위치에 유지하세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 팔을 바꾸세요.","fr":"Assieds-toi sur un banc avec un haltère dans une main et ton bras tendu par-dessus le banc, paume tournée vers le haut. Garde le haut du bras immobile et fléchis l''haltère vers ton épaule, en gardant le poignet en position neutre. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/0366-IvV6C9M.jpg', 'videos/0366-IvV6C9M.gif', '© Gym visual — https://gymvisual.com/'),
(1441, 'dumbbell over bench one arm reverse wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","brachialis"]'::jsonb, '{"en":"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down. Rest your forearm on the bench with your wrist hanging off the edge. Slowly curl your wrist upwards, bringing the dumbbell towards your forearm. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Siediti su una panchina con i piedi piatti a terra e tieni un manubrio in una mano, con il palmo rivolto verso il basso. Appoggia l''avambraccio sulla panca con il polso che penzola dal bordo. Curva lentamente il polso verso l''alto, portando il manubrio verso l''avambraccio. Fermati un attimo in cima, poi abbassa lentamente il manubrio fino alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta oturun ve avuç içi aşağı bakacak şekilde bir elinizde bir dambıl tutun. Bileğiniz kenardan sarkacak şekilde ön kolunuzu bankın üzerine yaslayın. Bileğinizi yavaşça yukarı doğru kıvırın ve dambılı ön kolunuza doğru getirin. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Сядьте на скамью, поставьте ноги на землю и держите гантель в одной руке ладонью вниз. Положите предплечье на скамью так, чтобы запястье свисало с края. Медленно согните запястье вверх, поднося гантель к предплечью. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。 将前臂放在长凳上，手腕悬在长凳边缘。 慢慢向上弯曲手腕，将哑铃拉向前臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली नीचे की ओर हो। अपनी कलाई को किनारे से लटकाते हुए अपनी बांह को बेंच पर टिकाएं। धीरे-धीरे अपनी कलाई को ऊपर की ओर मोड़ें, डम्बल को अपनी बांह की ओर लाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Usiądź na ławce, stopy oprzyj płasko na podłodze, i trzymaj hantlę w jednej ręce, dłonią skierowaną w dół. Oprzyj przedramię na ławce, z nadgarstkiem zwisającym poza krawędzią. Powoli zegnij nadgarstek do góry, przyciągając hantlę w stronę przedramienia. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"벤치에 앉아 발을 바닥에 평평하게 놓고 한쪽 팔에 덤벨을 잡아 손바닥이 아래를 향하도록 하세요. 전완을 벤치에 얹고 손목이 가장자리에서 튀어나오도록 하세요. 천천히 손목을 위로 말아올려 덤벨을 전완 쪽으로 가져오세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Assieds-toi sur un banc, les pieds à plat sur le sol, et tiens un haltère dans une main, paume tournée vers le bas. Pose ton avant-bras sur le banc, le poignet dépassant du bord. Enroule lentement ton poignet vers le haut, en ramenant l''haltère vers ton avant-bras. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/1441-4Jc36XM.jpg', 'videos/1441-4Jc36XM.gif', '© Gym visual — https://gymvisual.com/'),
(367, 'dumbbell over bench one arm wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","shoulders"]'::jsonb, '{"en":"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down. Rest your forearm on the bench with your wrist hanging off the edge. Slowly curl your wrist upwards, bringing the dumbbell towards your forearm. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.","it":"Siediti su una panchina con i piedi piatti a terra e tieni un manubrio in una mano, con il palmo rivolto verso il basso. Appoggia l''avambraccio sulla panca con il polso che penzola dal bordo. Curva lentamente il polso verso l''alto, portando il manubrio verso l''avambraccio. Fermati un attimo in cima, poi abbassa lentamente il manubrio fino alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi passa all''altro braccio.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta oturun ve avuç içi aşağı bakacak şekilde bir elinizde bir dambıl tutun. Bileğiniz kenardan sarkacak şekilde ön kolunuzu bankın üzerine yaslayın. Bileğinizi yavaşça yukarı doğru kıvırın ve dambılı ön kolunuza doğru getirin. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin.","es":"Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo. Apoya el antebrazo en el banco con la muñeca colgando del borde. Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.","ru":"Сядьте на скамью, поставьте ноги на землю и держите гантель в одной руке ладонью вниз. Положите предплечье на скамью так, чтобы запястье свисало с края. Медленно согните запястье вверх, поднося гантель к предплечью. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем переключитесь на другую руку.","zh":"坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。 将前臂放在长凳上，手腕悬在长凳边缘。 慢慢向上弯曲手腕，将哑铃拉向前臂。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换到另一只手臂。","hi":"अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली नीचे की ओर हो। अपनी कलाई को किनारे से लटकाते हुए अपनी बांह को बेंच पर टिकाएं। धीरे-धीरे अपनी कलाई को ऊपर की ओर मोड़ें, डम्बल को अपनी बांह की ओर लाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।","pl":"Usiądź na ławce, stopy oprzyj płasko na podłodze, i trzymaj hantlę w jednej ręce, dłonią skierowaną w dół. Oprzyj przedramię na ławce, z nadgarstkiem zwisającym poza krawędzią. Powoli zegnij nadgarstek do góry, przyciągając hantlę w stronę przedramienia. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień na drugą rękę.","ko":"벤치에 앉아 발을 바닥에 평평하게 놓고 한쪽 팔에 덤벨을 잡아 손바닥이 아래를 향하도록 하세요. 전완을 벤치에 얹고 손목이 가장자리에서 튀어나오도록 하세요. 천천히 손목을 위로 말아올려 덤벨을 전완 쪽으로 가져오세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복한 후 다른 팔로 전환하세요.","fr":"Assieds-toi sur un banc, les pieds à plat sur le sol, et tiens un haltère dans une main, paume tournée vers le bas. Pose ton avant-bras sur le banc, le poignet dépassant du bord. Enroule lentement ton poignet vers le haut, en ramenant l''haltère vers ton avant-bras. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis passe à l''autre bras."}'::jsonb, 'images/0367-KI1DjNN.jpg', 'videos/0367-KI1DjNN.gif', '© Gym visual — https://gymvisual.com/'),
(368, 'dumbbell over bench revers wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","brachialis"]'::jsonb, '{"en":"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down. Rest your forearms on the bench, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the dumbbells towards your body. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panchina con i piedi piatti a terra e tieni un manubrio in ciascuna mano, con i palmi rivolti verso il basso. Appoggia gli avambracci sulla panca, lasciando che i polsi penzolano dal bordo. Piega lentamente i polsi verso l''alto, portando i manubri verso il corpo. Fermati un attimo in cima, poi abbassa lentamente i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta oturun ve avuçlarınız aşağıya bakacak şekilde her iki elinizde birer dambıl tutun. Önkollarınızı bankın üzerine yaslayın, bileklerinizin kenardan sarkmasına izin verin. Bileklerinizi yavaşça yukarı doğru kıvırarak dambılları vücudunuza doğru getirin. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, поставьте ноги на землю и возьмите в каждую руку по гантели ладонями вниз. Положите предплечья на скамью так, чтобы запястья свисали с края. Медленно поднимите запястья вверх, приближая гантели к телу. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝下。 将前臂放在长凳上，让手腕悬在长凳边缘。 慢慢向上弯曲手腕，将哑铃拉向身体。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ नीचे की ओर हों। अपनी बांहों को बेंच पर टिकाएं, जिससे आपकी कलाइयां किनारे से लटक जाएं। धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, डम्बल को अपने शरीर की ओर लाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce, stopy oprzyj płasko na podłodze, i trzymaj w każdej dłoni hantlę, dłonie skierowane w dół. Oprzyj przedramiona na ławce, pozwalając nadgarstkom zwisać poza krawędzią. Powoli zginaj nadgarstki do góry, przyciągając hantle w stronę ciała. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 발을 바닥에 평평하게 놓고 양쪽 팔에 덤벨을 잡아 손바닥이 아래를 향하도록 하세요. 전완을 벤치에 얹고 손목이 가장자리에서 튀어나오도록 하세요. 천천히 손목을 위로 말아올려 덤벨을 몸 쪽으로 가져오세요. 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내리세요. 원하는 횟수만큼 반복하세요.","fr":"Assieds-toi sur un banc, les pieds à plat sur le sol, et tiens un haltère dans chaque main, paumes tournées vers le bas. Pose tes avant-bras sur le banc, en laissant tes poignets dépasser du bord. Enroule lentement tes poignets vers le haut, en ramenant les haltères vers ton corps. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0368-3tAXPQ6.jpg', 'videos/0368-3tAXPQ6.gif', '© Gym visual — https://gymvisual.com/'),
(369, 'dumbbell over bench wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","brachialis"]'::jsonb, '{"en":"Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand. Allow your wrists to hang over the edge of the bench. Slowly curl your wrists upward, squeezing your forearms at the top of the movement. Pause for a moment, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panchina con gli avambracci appoggiati sulla panca e i palmi rivolti verso l''alto, tenendo un manubrio in ogni mano. Lascia che i polsi sporgano dal bordo della panca. Ripiega lentamente i polsi verso l''alto, stringendo gli avambracci nella parte alta del movimento. Fermati un attimo, poi abbassa lentamente i polsi fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Her iki elinizde birer dambıl tutarak, önkollarınız bankın üzerinde ve avuçlarınız yukarı bakacak şekilde bir bankta oturun. Bileklerinizin bankın kenarından sarkmasına izin verin. Hareketin üst noktasında ön kollarınızı sıkarak bileklerinizi yavaşça yukarı doğru kıvırın. Bir an duraklayın, ardından bileklerinizi yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano. Deja que tus muñecas cuelguen del borde del banco. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, положив предплечья на скамью ладонями вверх, держа в каждой руке по гантели. Пусть ваши запястья свисают с края скамьи. Медленно поднимите запястья вверх, сжимая предплечья в верхней точке движения. Сделайте паузу на мгновение, затем медленно опустите запястья обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳上，前臂放在长凳上，手掌朝上，每只手各握一个哑铃。 让手腕悬在长凳边缘。 慢慢向上弯曲手腕，在动作的最高点挤压前臂。 暂停片刻，然后慢慢将手腕放回起始位置。 重复所需的重复次数。","hi":"एक बेंच पर बैठें, अपने अग्रबाहुओं को बेंच पर टिकाएं और अपनी हथेलियों को ऊपर की ओर रखें, प्रत्येक हाथ में डम्बल पकड़ें। अपनी कलाइयों को बेंच के किनारे पर लटकने दें। धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को गति के शीर्ष पर निचोड़ें। एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce, opierając przedramiona na ławce, dłonie skierowane do góry, trzymając w każdej dłoni hantlę. Pozwól nadgarstkom zwisać poza krawędzią ławki. Powoli zginaj nadgarstki do góry, ściskając przedramiona na górze ruchu. Zatrzymaj się na chwilę, a następnie powoli opuść nadgarstki z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 전완을 벤치에 얹고 손바닥이 위를 향하며 양쪽 팔에 덤벨을 잡으세요. 손목이 벤치 가장자리에서 튀어나오도록 하세요. 천천히 손목을 위로 말아올려 동작의 위쪽에서 전완을 꽉 조이세요. 잠깐 멈춘 후 천천히 손목을 시작 위치로 내리세요. 원하는 횟수만큼 반복하세요.","fr":"Assieds-toi sur un banc, les avant-bras posés sur le banc et les paumes tournées vers le haut, en tenant un haltère dans chaque main. Laisse tes poignets dépasser du bord du banc. Enroule lentement tes poignets vers le haut, en contractant tes avant-bras en haut du mouvement. Marque une pause, puis abaisse lentement tes poignets jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0369-D1xYJAU.jpg', 'videos/0369-D1xYJAU.gif', '© Gym visual — https://gymvisual.com/'),
(1329, 'dumbbell palm rotational bent over row', 'back', 'strength', 'back', 'dumbbell', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Bend forward at the hips, keeping your back straight and your knees slightly bent. Let your arms hang straight down, palms facing your body. Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body. As you pull the dumbbells up, rotate your palms so they face away from your body. Squeeze your shoulder blades together at the top of the movement. Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in ogni mano con una presa sopra la testa. Piegati in avanti ai fianchi, tenendo la schiena dritta e le ginocchia leggermente piegate. Lascia che le braccia pendano dritte verso il basso, i palmi rivolti verso il corpo. Attiva il core e tira i manubri verso il petto, tenendo i gomiti vicini al corpo. Mentre tiri verso l''alto i manubri, ruota i palmi in modo che siano rivolti lontano dal corpo. Stringi le scapole insieme nella parte alta del movimento. Abbassa lentamente i manubri fino alla posizione iniziale, ruotando i palmi di nuovo alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın, her iki elinizde de birer dambıl tutun ve üstten kavrayın. Kalçalarınızı öne doğru eğin, sırtınızı düz tutun ve dizlerinizi hafifçe bükün. Kollarınızı düz bir şekilde aşağı sarkıtın, avuçlarınız vücudunuza baksın. Merkez bölgenizi devreye sokun ve dirseklerinizi vücudunuza yakın tutarak dambılları göğsünüze doğru çekin. Dambılları yukarı çekerken avuç içlerinizi vücudunuzdan uzağa bakacak şekilde çevirin. Hareketin üst noktasında kürek kemiklerinizi birbirine doğru sıkın. Avuç içlerinizi başlangıç ​​pozisyonuna döndürerek dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo. Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo. Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху. Наклонитесь вперед в бедрах, сохраняя спину прямой и слегка согнутыми в коленях. Пусть ваши руки свисают прямо вниз, ладони обращены к телу. Напрягите корпус и подтяните гантели к груди, держа локти близко к телу. Подтягивая гантели вверх, поверните ладони так, чтобы они были направлены от тела. В верхней точке движения сведите лопатки вместе. Медленно опустите гантели обратно в исходное положение, поворачивая ладони обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 臀部向前弯曲，保持背部挺直，膝盖稍微弯曲。 让你的手臂笔直下垂，手掌朝向身体。 收紧核心肌群，将哑铃拉向胸部，保持肘部靠近身体。 当你向上拉哑铃时，旋转手掌，使其背向身体。 在动作的最高点将肩胛骨挤压在一起。 慢慢地将哑铃放回起始位置，将手掌旋转回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें। अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़ते हुए, कूल्हों के बल आगे की ओर झुकें। अपनी भुजाओं को सीधा नीचे लटका दें, हथेलियाँ आपके शरीर की ओर हों। अपने कोर को संलग्न करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए डम्बल को अपनी छाती की ओर खींचें। जैसे ही आप डम्बल को ऊपर खींचते हैं, अपनी हथेलियों को घुमाएँ ताकि वे आपके शरीर से दूर रहें। आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें। अपनी हथेलियों को घुमाते हुए धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę chwytem nachwytem. Pochyl tułów w biodrach, utrzymując proste plecy i lekko ugięte kolana. Pozwól rękom zwisać prosto w dół, dłońmi skierowanymi w stronę ciała. Napnij brzuch i podciągnij hantle w stronę klatki piersiowej, trzymając łokcie blisko ciała. Podczas podciągania hantli obróć dłonie tak, aby były skierowane w przeciwną stronę od ciała. Ściśnij łopatki na górze ruchu. Powoli opuść hantle z powrotem do pozycji wyjściowej, obracając dłonie z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 너비로 벌리고 서서 양쪽 팔에 덤벨을 오버핸드 그립으로 잡으세요. 엉덩이에서 몸을 앞으로 기울이고 등을 펴며 무릎을 약간 구부리세요. 팔을 일직선으로 내리고 손바닥이 몸을 향하도록 하세요. 코어를 단단히 하고 덤벨을 가슴 쪽으로 위로 당기며 팔꿈치를 몸에 가깝게 유지하세요. 덤벨을 위로 당기면서 손바닥이 몸을 향하게 회전시키세요. 동작의 위쪽에서 어깨 뼈를 함께 조이세요. 천천히 덤벨을 시작 위치로 내리며 손바닥을 시작 위치로 다시 회전시키세요. 원하는 횟수만큼 반복하세요.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère dans chaque main en prise pronation. Penche-toi vers l''avant au niveau des hanches en gardant ton dos droit et tes genoux légèrement fléchis. Laisse tes bras pendre droit vers le bas, les paumes tournées vers ton corps. Gaine ta sangle abdominale et tire les haltères vers ta poitrine, en gardant tes coudes près de ton corps. En tirant les haltères vers le haut, tourne tes paumes pour qu''elles soient tournées vers l''extérieur de ton corps. Contracte tes omoplates l''une vers l''autre en haut du mouvement. Abaisse lentement les haltères vers la position de départ, en tournant tes paumes vers la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1329-wt6rwjk.jpg', 'videos/1329-wt6rwjk.gif', '© Gym visual — https://gymvisual.com/'),
(1623, 'dumbbell palms in incline bench press', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'chest', 'triceps', '["chest","shoulders"]'::jsonb, '{"en":"Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the backrest and feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing inwards. Extend your arms straight up above your chest, keeping a slight bend in your elbows. Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body. Pause for a moment at the bottom, then press the dumbbells back up to the starting position. Repeat for the desired number of repetitions.","it":"Installa una panca inclinata con un angolo di 45 gradi. Siediti sulla panca con la schiena appoggiata allo schienale e i piedi appoggiati a terra. Tieni un manubrio in ogni mano con una presa sopra la mano, palmi rivolti verso l''interno. Allunga le braccia dritte sopra il petto, mantenendo una leggera piega dei gomiti. Abbassa lentamente i manubri verso le spalle, tenendo i gomiti vicini al corpo. Fermati un attimo in fondo, poi riporta i manubri alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni.","tr":"45 derecelik bir açıyla eğimli bir tezgah kurun. Sırtınız sırtlığa dayalı ve ayaklarınız yere düz basacak şekilde bankta oturun. Her iki elinizde de birer dambıl tutun ve avuç içleriniz içe bakacak şekilde üstten tutun. Kollarınızı göğsünüzün üzerine doğru uzatın, dirseklerinizi hafif bir şekilde bükün. Dirseklerinizi vücudunuza yakın tutarak dambılları yavaşça omuzlarınıza doğru indirin. Altta bir an duraklayın, ardından dambılları başlangıç ​​pozisyonuna doğru yukarı doğru bastırın. İstenilen sayıda tekrar için tekrarlayın.","es":"Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro. Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos. Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.","ru":"Установите наклонную скамью под углом 45 градусов. Сядьте на скамью, прислонившись спиной к спинке и поставив ступни на землю. Возьмите по гантели в каждую руку хватом сверху, ладонями внутрь. Вытяните руки прямо над грудью, сохраняя небольшой изгиб в локтях. Медленно опустите гантели к плечам, держа локти близко к телу. Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение. Повторите необходимое количество повторений.","zh":"设置一个 45 度角的上斜凳。 坐在长凳上，背部靠在靠背上，双脚平放在地上。 双手各握一个哑铃，正手握握，手掌朝内。 将手臂伸直至胸部上方，保持肘部轻微弯曲。 将哑铃慢慢向肩膀方向降低，保持肘部靠近身体。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数。","hi":"45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें। बेंच पर अपनी पीठ बैकरेस्ट से सटाकर और पैरों को ज़मीन पर सपाट करके बैठें। प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ अंदर की ओर हों। अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ। अपनी कोहनियों को अपने शरीर के करीब रखते हुए, डम्बल को धीरे-धीरे अपने कंधों की ओर नीचे लाएँ। नीचे एक क्षण के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में दबाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Ustaw ławkę skośną pod kątem 45 stopni. Usiądź na ławce, opierając plecy o zagłówek, stopy płasko na podłodze. Trzymaj w każdej dłoni hantlę chwytem nachwytem, dłonie skierowane do wewnątrz. Wyprostuj ręce prosto nad klatką piersiową, utrzymując lekkie ugięcie w łokciach. Powoli opuszczaj hantle w stronę barków, trzymając łokcie blisko ciała. Zatrzymaj się na chwilę na dole, a następnie wypchnij hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"인클라인 벤치를 45도 각도로 설정합니다. 벤치에 앉아 등을 등받이에 대고 발을 바닥에 평평하게 놓습니다. 각 손에 덤벨을 잡고 손바닥이 안쪽을 향하도록 오버핸드 그립으로 잡습니다. 팔을 가슴 위로 곧게 펼쳐 팔꿈치에 약간의 굽힘을 유지합니다. 덤벨을 천천히 어깨 쪽으로 내리면서 팔꿈치를 몸에 가깝게 유지합니다. 바닥에서 잠시 멈춘 후 덤벨을 시작 위치로 다시 밀어 올립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Installe un banc incliné à un angle de 45 degrés. Assieds-toi sur le banc, le dos contre le dossier et les pieds à plat sur le sol. Tiens un haltère dans chaque main avec une prise en pronation, les paumes tournées vers l''intérieur. Étends les bras droit au-dessus de la poitrine, en gardant une légère flexion dans les coudes. Abaisse lentement les haltères vers tes épaules, en gardant tes coudes près de ton corps. Marque une pause en bas, puis presse les haltères vers le haut jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1623-8eqjhOl.jpg', 'videos/1623-8eqjhOl.gif', '© Gym visual — https://gymvisual.com/'),
(370, 'dumbbell peacher hammer curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.","it":"Stai dritto con un manubrio in ogni mano, i palmi rivolti verso il busto. Tieni i gomiti vicini al busto e ruota i palmi delle mani finché non sono rivolti in avanti. Questa sarà la tua posizione di partenza. Ora, mantenendo ferme le braccia superiori, espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i pesi finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Poi, inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero consigliato di ripetizioni.","tr":"Her iki elinizde de birer dambıl olacak şekilde dik durun, avuçlarınız gövdenize bakacak şekilde. Dirseklerinizi gövdenize yakın tutun ve avuçlarınızı öne bakana kadar döndürün. Bu sizin başlangıç ​​pozisyonunuz olacaktır. Şimdi üst kolları sabit tutarak nefes verin ve bicepslerinizi kasarken ağırlıkları kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar ağırlıkları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Daha sonra nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. Önerilen tekrar sayısı kadar tekrarlayın.","es":"Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.","ru":"Встаньте прямо, возьмите в каждую руку по гантели, ладони обращены к туловищу. Держите локти близко к туловищу и поворачивайте ладони рук так, чтобы они смотрели вперед. Это будет ваша исходная позиция. Теперь, удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Затем вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите рекомендованное количество повторений.","zh":"站直，双手各持一个哑铃，手掌朝向躯干。 保持肘部靠近躯干，并旋转手掌，直到手掌朝前。 这将是您的起始位置。 现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 然后，吸气并慢慢开始将哑铃放回起始位置。 重复建议的重复次数。","hi":"प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों। अपनी कोहनियों को अपने धड़ के पास रखें और अपने हाथों की हथेलियों को तब तक घुमाएँ जब तक वे आगे की ओर न आ जाएँ। यह आपकी प्रारंभिक स्थिति होगी. अब, ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। फिर, सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।","pl":"Stań prosto, trzymając w każdej dłoni hantlę, dłonie skierowane w stronę tułowia. Trzymaj łokcie blisko tułowia i obróć dłonie tak, aby były skierowane do przodu. Będzie to pozycja wyjściowa. Teraz, utrzymując nieruchome ramiona, wykonaj wydech i unieś ciężarki, napinając biceps. Unoś ciężarki, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Następnie wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"양손에 덤벨을 잡고 몸통 쪽으로 손바닥을 향하게 하여 곧게 서 있습니다. 팔꿈치를 몸통에 가깝게 유지하고 손바닥이 앞을 향할 때까지 손의 위치를 회전시킵니다. 이것이 시작 위치입니다. 이제 상체는 고정한 채로 숨을 내쉬면서 이두근을 수축시키면서 무게를 커핑합니다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 무게를 계속 올립니다. 이두근을 꽉 쥐면서 수축된 위치에서 잠시 멈춥니다. 그런 다음 숨을 들이쉬고 천천히 덤벨을 시작 위치로 내립니다. 권장 반복 횟수만큼 반복합니다.","fr":"Tiens-toi bien droit avec un haltère dans chaque main, les paumes tournées vers ton torse. Garde tes coudes près de ton torse et tourne les paumes de tes mains jusqu''à ce qu''elles soient tournées vers l''avant. Ce sera ta position de départ. Maintenant, en gardant le haut des bras immobile, expire et enroule les poids en contractant tes biceps. Continue à lever les poids jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Ensuite, inspire et commence lentement à abaisser les haltères vers la position de départ. Répète le nombre de répétitions recommandé."}'::jsonb, 'images/0370-F1KxjBa.jpg', 'videos/0370-F1KxjBa.gif', '© Gym visual — https://gymvisual.com/'),
(371, 'dumbbell plyo squat', 'upper legs', 'strength', 'upper legs', 'dumbbell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Lower your body into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explode upward, jumping off the ground. While in the air, quickly switch the position of your feet, landing with your opposite foot forward. Immediately lower your body back into a squat position and repeat the jump, switching your feet again. Continue alternating the position of your feet with each jump for the desired number of repetitions.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in ogni mano ai lati. Abbassa il corpo in posizione accovacciata piegando le ginocchia e spingendo i fianchi all''indietro. Quando arrivi in fondo allo squat, esplodi verso l''alto, saltando da terra. Mentre sei in aria, cambia rapidamente la posizione dei piedi, atterrando con il piede opposto in avanti. Abbassa subito il corpo in posizione accovacciata e ripeti il salto, cambiando di nuovo i piedi. Continua ad alternare la posizione dei piedi ad ogni salto per il numero desiderato di ripetizioni.","tr":"Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun, her iki elinizde de birer dambıl tutun. Dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek vücudunuzu çömelme pozisyonuna indirin. Squat''ın dibine ulaştığınızda yerden atlayarak yukarıya doğru patlayın. Havadayken ayaklarınızın konumunu hızla değiştirin ve karşı ayağınız öne doğru inin. Hemen vücudunuzu tekrar çömelme pozisyonuna indirin ve ayaklarınızı tekrar değiştirerek atlamayı tekrarlayın. İstediğiniz tekrar sayısı için her atlamada ayaklarınızın konumunu değiştirmeye devam edin.","es":"Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo. Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante. Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies. Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа по гантели в каждой руке по бокам. Опустите тело в присед, согнув колени и отведя бедра назад. Достигнув нижней точки приседа, резко взлетайте вверх, отпрыгивая от земли. Находясь в воздухе, быстро поменяйте положение ног, приземлившись противоположной ногой вперед. Немедленно опустите тело обратно в положение приседа и повторите прыжок, снова поменяв ноги. Продолжайте менять положение ног при каждом прыжке желаемое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。 弯曲膝盖并将臀部向后推，将身体降低至蹲姿。 当你到达深蹲底部时，向上爆发，跳离地面。 在空中时，快速改变双脚的位置，落地时另一只脚向前。 立即将身体放回蹲姿，然后重复跳跃，再次换脚。 每次跳跃时继续交替双脚的位置，达到所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों में एक-एक डंबल पकड़ लें। अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ। जैसे ही आप स्क्वाट के निचले भाग तक पहुँचते हैं, जमीन से कूदते हुए ऊपर की ओर विस्फोट करें। हवा में रहते हुए, अपने विपरीत पैर को आगे की ओर रखते हुए, जल्दी से अपने पैरों की स्थिति बदलें। तुरंत अपने शरीर को वापस स्क्वाट स्थिति में ले आएं और अपने पैरों को फिर से बदलते हुए छलांग दोहराएं। दोहराव की वांछित संख्या के लिए प्रत्येक छलांग के साथ अपने पैरों की स्थिति को बदलते रहें।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę wzdłuż ciała. Opuść ciało do pozycji przysiadu, uginając kolana i cofając biodra. Gdy osiągniesz najniższy punkt przysiadu, gwałtownie wybij się w górę, odrywając stopy od podłoża. W trakcie skoku szybko zamień ułożenie stóp, lądując z przeciwną nogą do przodu. Natychmiast opuść ciało z powrotem do przysiadu i powtórz skok, ponownie zamieniając nogi. Kontynuuj naprzemienne ustawianie stóp przy każdym skoku przez zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡고 옆에 놓습니다. 무릎을 구부리고 엉덩이를 뒤로 밀면서 스쿼트 자세로 몸을 낮춥니다. 스쿼트의 최하점에 도달하면 폭발적으로 위로 솟아올라 바닥에서 뛰어올립니다. 공중에서 빠르게 발의 위치를 바꾸고 반대쪽 발이 앞으로 향하게 착지합니다. 즉시 몸을 다시 스쿼트 자세로 낮추고 뛰어올리면서 발을 다시 바꿉니다. 원하는 반복 횟수만큼 매 점프마다 발의 위치를 계속 번갈아 변경합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère dans chaque main le long du corps. Abaisse ton corps en position de squat en fléchissant tes genoux et en poussant tes hanches vers l''arrière. Une fois au bas du squat, explose vers le haut en sautant du sol. En l''air, change rapidement la position de tes pieds pour atterrir avec le pied opposé devant. Abaisse immédiatement ton corps en position de squat et répète le saut, en changeant de nouveau de pieds. Continue à alterner la position de tes pieds à chaque saut pour le nombre de répétitions souhaité."}'::jsonb, 'images/0371-S4pwGlc.jpg', 'videos/0371-S4pwGlc.gif', '© Gym visual — https://gymvisual.com/'),
(372, 'dumbbell preacher curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panca da curl preacher con le braccia superiori appoggiate sul cuscinetto e il petto contro di esso. Tieni un manubrio in ogni mano con i palmi rivolti verso l''alto e le braccia completamente distese. Mantenendo ferme le braccia superiori, espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i manubri finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Üst kollarınız yastığa ve göğsünüz ona yaslanacak şekilde bir vaiz kıvırma bankına oturun. Avuç içleriniz yukarı bakacak ve kollarınız tamamen uzatılmış şekilde her iki elinizde birer dambıl tutun. Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar dambılları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью для сгибаний рук для проповедника, положив плечи на подушечку и прижавшись к ней грудью. Возьмите по гантели в каждую руку ладонями вверх и полностью выпрямите руки. Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在牧师弯举凳上，上臂放在垫子上，胸部靠在垫子上。 每只手握住一个哑铃，手掌朝上，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपनी ऊपरी बांहों को पैड पर और अपनी छाती को पैड पर टिकाकर प्रीचर कर्ल बेंच पर बैठें। अपनी हथेलियों को ऊपर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें। अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce modlitewnej (Scotta), opierając ramiona na podkładce i klatkę piersiową o oparcie. Trzymaj w każdej dłoni hantlę, dłonie skierowane do góry, ręce w pełni wyprostowane. Utrzymując nieruchome ramiona, wykonaj wydech i unieś ciężarki, napinając biceps. Unoś hantle, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"프리처 컬 벤치에 앉아 팔을 패드에 올리고 가슴을 패드에 대십시오. 양손에 덤벨을 잡고 손바닥이 위를 향하고 팔이 완전히 펼쳐져 있습니다. 상체는 고정한 채로 숨을 내쉬면서 이두근을 수축시키면서 무게를 커핑합니다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 덤벨을 계속 올립니다. 이두근을 꽉 쥐면서 수축된 위치에서 잠시 멈춥니다. 숨을 들이쉬고 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc à prêcheur, le haut de tes bras posé sur le coussin et ta poitrine contre celui-ci. Tiens un haltère dans chaque main, les paumes tournées vers le haut et les bras complètement étendus. En gardant le haut des bras immobile, expire et fléchis les poids en contractant tes biceps. Continue à lever les haltères jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et commence lentement à abaisser les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0372-jivWf8n.jpg', 'videos/0372-jivWf8n.gif', '© Gym visual — https://gymvisual.com/'),
(1673, 'dumbbell preacher curl over exercise ball', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.","it":"Siediti su una palla da ginnastica con i piedi piatti a terra e la schiena dritta. Tieni un manubrio in una mano con una presa sottomano, appoggiando il gomito sulla palla da esercizio. Mantenendo fermo il braccio superiore, espira e arrotola il manubrio verso la spalla. Fermati un attimo in cima, poi inspira e abbassa lentamente il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni, poi cambia braccio.","tr":"Ayaklarınız yere düz basacak ve sırtınız düz olacak şekilde bir egzersiz topunun üzerine oturun. Bir elinizde bir dambılı alttan kavrayarak tutun, dirseğinizi egzersiz topunun üzerine koyun. Üst kolunuzu sabit tutarak nefes verin ve dambılı omzunuza doğru kıvırın. Tepe noktasında bir an duraklayın, ardından nefes alın ve dambılı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin.","es":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.","ru":"Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину. Возьмите гантель в одну руку обратным хватом, положив локоть на мяч для упражнений. Удерживая плечо неподвижно, выдохните и поднимите гантель к плечу. Задержитесь на мгновение в верхней точке, затем вдохните и медленно опустите гантель обратно в исходное положение. Повторите желаемое количество повторений, затем поменяйте руки.","zh":"坐在健身球上，双脚平放在地上，背部挺直。 一只手握住哑铃，反握，将肘部放在健身球上。 保持上臂静止，呼气并将哑铃向上弯向肩膀。 在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。 重复所需的重复次数，然后换臂。","hi":"अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें। एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें, अपनी कोहनी को एक्सरसाइज बॉल पर टिकाएं। अपनी ऊपरी भुजा को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें। शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।","pl":"Usiądź na piłce gimnastycznej, stopy oprzyj płasko na podłodze, a plecy trzymaj proste. Trzymaj hantlę w jednej ręce chwytem podchwytem, opierając łokieć na piłce gimnastycznej. Utrzymując nieruchome ramię, wykonaj wydech i unieś hantlę w stronę barku. Zatrzymaj się na chwilę na górze, a następnie wykonaj wdech i powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń, a następnie zmień rękę.","ko":"발을 바닥에 평평하게 놓고 등을 곧게 펼친 상태로 운동공 위에 앉습니다. 한 손에 덤벨을 잡고 언더핸드 그립으로 팔꿈치를 운동공에 올립니다. 상체는 고정한 채로 숨을 내쉬면서 덤벨을 어깨 쪽으로 커핑합니다. 맨 위에서 잠시 멈춘 후 숨을 들이쉬고 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복한 후 팔을 바꿉니다.","fr":"Assieds-toi sur un ballon d''exercice, les pieds à plat sur le sol et le dos droit. Tiens un haltère dans une main avec une prise en supination, en posant ton coude sur le ballon d''exercice. En gardant le haut du bras immobile, expire et fléchis l''haltère vers ton épaule. Marque une pause en haut, puis inspire et abaisse lentement l''haltère pour revenir à la position de départ. Répète le nombre de répétitions souhaité, puis change de bras."}'::jsonb, 'images/1673-hwygydB.jpg', 'videos/1673-hwygydB.gif', '© Gym visual — https://gymvisual.com/'),
(1293, 'dumbbell press on exercise ball', 'chest', 'strength', 'chest', 'dumbbell', 'shoulders', 'pectorals', '["shoulders","triceps"]'::jsonb, '{"en":"Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs. Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle. Raise the dumbbells to shoulder height, palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una palla da ginnastica con i piedi piatti a terra e manubri in ciascuna mano, appoggiati sulle cosce. Muovi lentamente i piedi in avanti, facendo rotolare la palla da esercizio finché la parte bassa della schiena non è sostenuta e le ginocchia sono a un angolo di 90 gradi. Alza i manubri all''altezza delle spalle, palmi rivolti in avanti. Premi i manubri verso l''alto finché le braccia non sono completamente estese. Fermati un attimo in cima, poi abbassa lentamente i manubri alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak şekilde ve her iki elinize de dambıl alarak, uyluklarınıza yaslanarak bir egzersiz topunun üzerine oturun. Ayaklarınızı yavaşça ileri doğru yürütün, alt sırtınız top üzerinde desteklenene ve dizleriniz 90 derecelik bir açıya gelene kadar egzersiz topunu yuvarlayın. Dambılları omuz hizasına kadar kaldırın, avuç içleriniz öne baksın. Kollarınız tamamen uzayıncaya kadar dambılları yukarı doğru bastırın. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на гимнастический мяч, поставьте ноги на землю и возьмите в каждую руку по гантели, положив их на бедра. Медленно пройдите ногами вперед, перекатывая мяч для упражнений до тех пор, пока нижняя часть спины не окажется на мяче, а колени не окажутся под углом 90 градусов. Поднимите гантели на высоту плеч, ладони смотрят вперед. Выжмите гантели вверх, пока руки полностью не выпрямятся. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在健身球上，双脚平放在地上，双手各握哑铃，放在大腿上。 慢慢地向前移动双脚，滚动健身球，直到下背部受到球的支撑并且膝盖呈 90 度角。 将哑铃举至肩高，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके और प्रत्येक हाथ में डम्बल लेकर, अपनी जाँघों पर आराम करते हुए एक व्यायाम गेंद पर बैठें। व्यायाम गेंद को घुमाते हुए धीरे-धीरे अपने पैरों को आगे बढ़ाएं जब तक कि आपकी पीठ के निचले हिस्से को गेंद पर सहारा न मिल जाए और आपके घुटने 90 डिग्री के कोण पर न आ जाएं। डम्बल को कंधे की ऊँचाई तक उठाएँ, हथेलियाँ आगे की ओर हों। डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na piłce gimnastycznej, stopy oprzyj płasko na podłodze, trzymając hantle w obu dłoniach, oparte na udach. Powoli przejdź stopami do przodu, przetaczając piłkę, aż dolna część pleców będzie na niej oparta, a kolana zgięte pod kątem 90 stopni. Unieś hantle na wysokość barków, dłonie skierowane do przodu. Wypchnij hantle do góry, aż ramiona będą w pełni wyprostowane. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 바닥에 평평하게 놓고 양손에 덤벨을 잡은 상태로 운동공 위에 앉습니다. 발을 천천히 앞으로 옮기고 운동공을 등 아래로 굴려서 허리가 운동공으로 지지되고 무릎이 90도 각도가 될 때까지 구릅니다. 덤벨을 어깨 높이까지 올려 손바닥이 앞을 향하게 합니다. 팔이 완전히 펼쳐질 때까지 덤벨을 위로 밉니다. 맨 위에서 잠시 멈춘 후 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un ballon d''exercice, les pieds à plat sur le sol et un haltère dans chaque main, posés sur tes cuisses. Avance lentement les pieds, en faisant rouler le ballon d''exercice jusqu''à ce que le bas de ton dos soit soutenu par le ballon et que tes genoux forment un angle de 90 degrés. Lève les haltères à hauteur des épaules, paumes tournées vers l''avant. Pousse les haltères vers le haut jusqu''à ce que tes bras soient complètement tendus. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1293-O8o7q4d.jpg', 'videos/1293-O8o7q4d.gif', '© Gym visual — https://gymvisual.com/'),
(373, 'dumbbell pronate-grip triceps extension', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'triceps', '["forearms"]'::jsonb, '{"en":"Sit on a bench or chair with your back straight and feet flat on the ground. Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead. Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panca o una sedia con la schiena dritta e i piedi piatti a terra. Tieni un manubrio con entrambe le mani, palmi rivolti verso il basso, e allunga le braccia dritte sopra la testa. Tenendo le braccia superiori vicine alla testa e i gomiti rivolti in avanti, abbassa lentamente il manubrio dietro la testa piegando i gomiti. Fermati un attimo, poi rialza le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Sırtınız düz ve ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun. Her iki elinizle bir dambılı tutun, avuçlarınız aşağıya bakacak şekilde ve kollarınızı yukarı doğru uzatın. Üst kollarınızı başınıza yakın ve dirsekleriniz ileriyi gösterecek şekilde tutarak, dirseklerinizi bükerek dambılı yavaşça başınızın arkasına indirin. Bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza. Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью или стул, выпрямив спину и поставив ступни на землю. Возьмите гантель обеими руками ладонями вниз и вытяните руки вверх. Держа плечи близко к голове и локти направленными вперед, медленно опустите гантель за голову, сгибая локти. Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳或椅子上，背部挺直，双脚平放在地面上。 双手握住哑铃，掌心朝下，双臂伸直举过头顶。 保持上臂靠近头部，肘部向前，弯曲肘部，慢慢将哑铃降低到脑后。 暂停片刻，然后将手臂伸回到起始位置。 重复所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें। दोनों हाथों से डम्बल पकड़ें, हथेलियाँ नीचे की ओर हों और अपनी भुजाओं को सीधा ऊपर की ओर फैलाएँ। अपनी ऊपरी भुजाओं को अपने सिर के पास और कोहनियों को आगे की ओर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे अपने सिर के पीछे डम्बल को नीचे लाएँ। एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce lub krześle, trzymając proste plecy i stopy płasko na podłodze. Trzymaj hantlę obiema rękami, dłonie skierowane w dół, i wyprostuj ręce prosto nad głową. Utrzymując ramiona blisko głowy, a łokcie skierowane do przodu, powoli opuszczaj hantlę za głowę, zginając łokcie. Zatrzymaj się na chwilę, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"등을 곧게 펼치고 발을 바닥에 평평하게 놓고 벤치나 의자에 앉습니다. 양손으로 덤벨을 잡고 손바닥이 아래를 향하게 하고 팔을 머리 위로 곧게 펼칩니다. 상체는 고정한 채로 머리 근처에서 팔꿈치를 향하게 하고 천천히 덤벨을 머리 뒤로 내리면서 팔꿈치를 구부립니다. 잠시 멈춘 후 팔을 시작 위치로 다시 펼칩니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc ou une chaise, le dos droit et les pieds à plat sur le sol. Tiens un haltère des deux mains, les paumes tournées vers le bas, et étends les bras droit au-dessus de ta tête. En gardant le haut des bras près de la tête et les coudes pointés vers l''avant, abaisse lentement l''haltère derrière ta tête en fléchissant tes coudes. Marque une pause, puis étends tes bras vers le haut pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0373-bpJL2Qs.jpg', 'videos/0373-bpJL2Qs.gif', '© Gym visual — https://gymvisual.com/'),
(374, 'dumbbell prone incline curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Adjust the bench to a 45-degree incline. Lie face down on the bench with your chest and stomach resting against it. Hold a dumbbell in each hand with your palms facing down and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Regola la panca con un''inclinazione di 45 gradi. Sdraiati a faccia in giù sulla panchina con petto e pancia appoggiati contro di essa. Tieni un manubrio in ogni mano con i palmi rivolti verso il basso e le braccia completamente distese. Mantenendo ferme le braccia superiori, espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i pesi finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Tezgahı 45 derecelik bir eğime ayarlayın. Göğsünüz ve karnınız ona yaslanacak şekilde bankta yüzüstü uzanın. Avuçlarınız aşağıya bakacak ve kollarınız tamamen uzatılmış halde her iki elinizde birer dambıl tutun. Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar ağırlıkları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. İstenilen sayıda tekrar için tekrarlayın.","es":"Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Отрегулируйте скамью под углом 45 градусов. Лягте лицом вниз на скамью, прижавшись к ней грудью и животом. Возьмите по гантели в каждую руку ладонями вниз и полностью выпрямите руки. Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"将长凳调整至 45 度倾斜。 脸朝下躺在长凳上，胸部和腹部靠在长凳上。 每只手握住一个哑铃，手掌朝下，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。","hi":"बेंच को 45 डिग्री के झुकाव पर समायोजित करें। अपनी छाती और पेट को बेंच पर टिकाकर चेहरे के बल लेट जाएँ। अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें। अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Ustaw ławkę pod kątem 45 stopni. Połóż się twarzą w dół na ławce, opierając klatkę piersiową i brzuch o nią. Trzymaj w każdej dłoni hantlę, dłonie skierowane w dół, ręce w pełni wyprostowane. Utrzymując nieruchome ramiona, wykonaj wydech i unieś ciężarki, napinając biceps. Unoś ciężarki, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치를 45도 인클라인으로 설정합니다. 가슴과 배를 벤치에 올려 엎드립니다. 양손에 덤벨을 잡고 손바닥이 아래를 향하고 팔이 완전히 펼쳐져 있습니다. 상체는 고정한 채로 숨을 내쉬면서 이두근을 수축시키면서 무게를 커핑합니다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 무게를 계속 올립니다. 이두근을 꽉 쥐면서 수축된 위치에서 잠시 멈춥니다. 숨을 들이쉬고 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Règle le banc sur une inclinaison de 45 degrés. Allonge-toi face vers le bas sur le banc, la poitrine et le ventre reposant contre lui. Tiens un haltère dans chaque main, les paumes tournées vers le bas et les bras complètement étendus. En gardant le haut des bras immobile, expire et fléchis les poids en contractant tes biceps. Continue à lever les poids jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et commence lentement à abaisser les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0374-mwpPcr1.jpg', 'videos/0374-mwpPcr1.gif', '© Gym visual — https://gymvisual.com/'),
(1674, 'dumbbell prone incline hammer curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Adjust the bench to a 45-degree incline. Lie face down on the bench with a dumbbell in each hand, palms facing each other. Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Regola la panca con un''inclinazione di 45 gradi. Sdraiati a faccia in giù sulla panchina con un manubrio in ciascuna mano, i palmi rivolti uno verso l''altro. Lascia che le braccia pendano dritte verso il pavimento, tenendo i gomiti leggermente piegati. Mantenendo ferme le braccia superiori, espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i manubri finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Tezgahı 45 derecelik bir eğime ayarlayın. Her iki elinizde birer dambıl, avuçlarınız birbirine bakacak şekilde bankın üzerine yüz üstü uzanın. Dirseklerinizi hafifçe bükerek kollarınızın yere doğru düz bir şekilde sarkmasına izin verin. Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar dambılları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. İstenilen sayıda tekrar için tekrarlayın.","es":"Ajusta el banco a una inclinación de 45 grados. Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí. Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Отрегулируйте скамью под углом 45 градусов. Лягте лицом вниз на скамью, взяв в каждую руку по гантели, ладони обращены друг к другу. Позвольте рукам свисать прямо к полу, слегка согнутыми в локтях. Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"将长凳调整至 45 度倾斜。 脸朝下躺在长凳上，双手各握一个哑铃，手掌相对。 让你的手臂垂直垂向地板，保持肘部稍微弯曲。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。","hi":"बेंच को 45 डिग्री के झुकाव पर समायोजित करें। प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, बेंच पर मुँह करके लेट जाएँ। अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी भुजाओं को फर्श की ओर सीधा लटकने दें। अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Ustaw ławkę pod kątem 45 stopni. Połóż się twarzą w dół na ławce, trzymając w każdej dłoni hantlę, dłonie skierowane do siebie. Pozwól rękom zwisać prosto w dół w stronę podłogi, trzymając łokcie lekko ugięte. Utrzymując nieruchome ramiona, wykonaj wydech i unieś ciężarki, napinając biceps. Unoś hantle, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치를 45도 인클라인으로 설정합니다. 양손에 덤벨을 잡고 손바닥이 서로 마주보게 하고 벤치에 엎드립니다. 팔을 바닥 방향으로 곧게 내리면서 팔꿈치를 약간 구부린 상태로 유지합니다. 상체는 고정한 채로 숨을 내쉬면서 이두근을 수축시키면서 무게를 커핑합니다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 덤벨을 계속 올립니다. 이두근을 꽉 쥐면서 수축된 위치에서 잠시 멈춥니다. 숨을 들이쉬고 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Règle le banc sur une inclinaison de 45 degrés. Allonge-toi face vers le bas sur le banc avec un haltère dans chaque main, les paumes se faisant face. Laisse tes bras pendre bien droit vers le sol en gardant tes coudes légèrement fléchis. En gardant le haut des bras immobile, expire et fléchis les poids en contractant tes biceps. Continue à lever les haltères jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et commence lentement à abaisser les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1674-cWemPG8.jpg', 'videos/1674-cWemPG8.gif', '© Gym visual — https://gymvisual.com/'),
(375, 'dumbbell pullover', 'chest', 'strength', 'chest', 'dumbbell', 'latissimus dorsi', 'pectorals', '["latissimus dorsi","triceps"]'::jsonb, '{"en":"Lie flat on a bench with your head at one end and your feet on the floor. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.","it":"Sdraiati su una panchina con la testa a un''estremità e i piedi a terra. Tieni un manubrio con entrambe le mani e estendi le braccia dritte sopra il petto. Mantenendo una leggera piega dei gomiti, abbassa lentamente il manubrio dietro la testa finché non senti uno stiramento al petto e alle spalle. Fermati un attimo, poi solleva il manubrio di nuovo alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni.","tr":"Başınız bir ucunda ve ayaklarınız yerde olacak şekilde bir bankın üzerine düz bir şekilde uzanın. İki elinizle bir dambılı tutun ve kollarınızı göğsünüzün üzerine düz bir şekilde uzatın. Dirseklerinizi hafif bükerek, göğsünüzde ve omuzlarınızda bir gerginlik hissedene kadar dambılı başınızın arkasına yavaşça indirin. Bir an duraklayın ve dambılı tekrar başlangıç ​​pozisyonuna kaldırın. İstenilen sayıda tekrar için tekrarlayın.","es":"Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Лягте на скамью, положив голову на один конец и поставив ноги на пол. Возьмите гантель обеими руками и вытяните руки прямо над грудью. Сохраняя небольшой изгиб в локтях, медленно опускайте гантель за голову, пока не почувствуете растяжение в груди и плечах. Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение. Повторите необходимое количество повторений.","zh":"平躺在长凳上，头放在一端，双脚放在地板上。 双手握住哑铃，将手臂伸直至胸部上方。 保持肘部轻微弯曲，慢慢地将哑铃放到脑后，直到感觉胸部和肩膀有拉伸感。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。","hi":"एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं। दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ। अपनी कोहनियों को हल्का सा मोड़ते हुए धीरे-धीरे डंबल को अपने सिर के पीछे तब तक नीचे लाएं जब तक आपको अपनी छाती और कंधों में खिंचाव महसूस न हो। एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Połóż się na ławce, głową na jednym końcu, a stopy oprzyj na podłodze. Trzymaj hantlę obiema rękami i wyprostuj ręce prosto nad klatką piersiową. Utrzymując lekkie ugięcie w łokciach, powoli opuszczaj hantlę za głowę, aż poczujesz rozciąganie w klatce piersiowej i barkach. Zatrzymaj się na chwilę, a następnie unieś hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 누워 한쪽 끝에 머리를 놓고 발을 바닥에 놓습니다. 양손으로 덤벨을 잡고 팔을 가슴 위로 곧게 펼칩니다. 팔꿈치에 약간의 굽힘을 유지하면서 천천히 덤벨을 머리 뒤로 내려 가슴과 어깨에 스트레칭을 느낍니다. 잠시 멈춘 후 덤벨을 시작 위치로 올립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Allonge-toi à plat sur un banc, la tête à une extrémité et les pieds au sol. Tiens un haltère des deux mains et étends les bras droit au-dessus de ta poitrine. En gardant une légère flexion des coudes, abaisse lentement l''haltère derrière ta tête jusqu''à ressentir un étirement dans la poitrine et les épaules. Marque une pause, puis ramène l''haltère à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0375-9XjtHvS.jpg', 'videos/0375-9XjtHvS.gif', '© Gym visual — https://gymvisual.com/'),
(1294, 'dumbbell pullover hip extension on exercise ball', 'chest', 'strength', 'chest', 'dumbbell', 'triceps', 'pectorals', '["triceps","shoulders","core"]'::jsonb, '{"en":"Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs. Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball. Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower the dumbbell behind your head, keeping your arms straight and maintaining control. Pause for a moment, then raise the dumbbell back to the starting position. While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core. Lower your hips back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una palla da ginnastica con i piedi piatti a terra e il manubrio appoggiato sulle cosce. Muovi lentamente i piedi in avanti, facendo rotolare la palla da esercizio lungo la schiena finché testa, collo e parte superiore della schiena non sono sostenuti sulla palla. Tieni il manubrio con entrambe le mani e allunga le braccia dritte sopra il petto, mantenendo una leggera piega dei gomiti. Abbassa il manubrio dietro la testa, mantenendo le braccia dritte e mantenendo il controllo. Fermati un attimo, poi solleva il manubrio di nuovo alla posizione di partenza. Mantenendo le braccia distese, solleva i fianchi da terra, stringendo i glutei e attivando il core. Abbassa i fianchi fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak ve dambıl uyluklarınızın üzerinde olacak şekilde bir egzersiz topunun üzerine oturun. Ayaklarınızı yavaşça ileri doğru yürütün, egzersiz topunu başınız, boynunuz ve sırtınızın üst kısmı top üzerinde desteklenene kadar sırtınızdan aşağı doğru yuvarlayın. Dambılı iki elinizle tutun ve dirseklerinizi hafif bükerek kollarınızı göğsünüzün üzerine doğru uzatın. Dambılı başınızın arkasına indirin, kollarınızı düz tutun ve kontrolü koruyun. Bir an duraklayın ve dambılı tekrar başlangıç ​​pozisyonuna kaldırın. Kollarınızı uzatılmış halde tutarken kalçalarınızı yerden kaldırın, kalça kaslarınızı sıkın ve merkez bölgenizi harekete geçirin. Kalçalarınızı tekrar başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core. Baja las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на мяч для упражнений, поставьте ноги на землю, а гантель положите на бедра. Медленно пройдите ногами вперед, катя мяч для упражнений вниз по спине, пока ваша голова, шея и верхняя часть спины не окажутся на мяче. Возьмите гантель обеими руками и вытяните руки прямо вверх над грудью, сохраняя небольшой изгиб в локтях. Опустите гантель за голову, держа руки прямыми и сохраняя контроль. Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение. Держа руки вытянутыми, поднимите бедра от земли, сжимая ягодицы и задействуя корпус. Опустите бедра обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在健身球上，双脚平放在地面上，哑铃放在大腿上。 慢慢地向前移动你的脚，将健身球沿着你的背部滚动，直到你的头部、颈部和上背部得到球的支撑。 双手握住哑铃，将手臂伸直至胸部上方，肘部保持轻微弯曲。 将哑铃放在脑后，保持手臂伸直并保持控制。 暂停片刻，然后将哑铃举回到起始位置。 在保持双臂伸展的同时，将臀部抬离地面，挤压臀肌并启动核心肌群。 将臀部放低至起始位置。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके और डम्बल को अपनी जाँघों पर टिकाकर एक व्यायाम बॉल पर बैठें। धीरे-धीरे अपने पैरों को आगे बढ़ाएं, व्यायाम गेंद को अपनी पीठ के नीचे तब तक घुमाएं जब तक कि आपका सिर, गर्दन और ऊपरी पीठ गेंद पर समर्थित न हो जाए। दोनों हाथों से डम्बल पकड़ें और अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ। अपनी बाहों को सीधा रखते हुए और नियंत्रण बनाए रखते हुए डम्बल को अपने सिर के पीछे नीचे करें। एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं। अपनी बाहों को फैलाए रखते हुए, अपने कूल्हों को ज़मीन से ऊपर उठाएं, अपने ग्लूट्स को निचोड़ें और अपने कोर को संलग्न करें। अपने कूल्हों को वापस प्रारंभिक स्थिति में लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na piłce gimnastycznej, stopy oprzyj płasko na podłodze, a hantlę oprzyj na udach. Powoli przejdź stopami do przodu, przetaczając piłkę wzdłuż pleców, aż głowa, szyja i górna część pleców będą na niej oparte. Trzymaj hantlę obiema rękami i wyprostuj ręce prosto nad klatką piersiową, utrzymując lekkie ugięcie w łokciach. Opuszczaj hantlę za głowę, trzymając ręce proste i zachowując kontrolę nad ruchem. Zatrzymaj się na chwilę, a następnie unieś hantlę z powrotem do pozycji wyjściowej. Utrzymując wyprostowane ręce, unieś biodra nad podłogę, ściskając pośladki i napinając brzuch. Opuść biodra z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 바닥에 평평하게 놓고 덤벨을 허벅지에 올려 운동공 위에 앉습니다. 발을 천천히 앞으로 옮기고 운동공을 등 아래로 굴려서 머리, 목, 상부 등이 운동공으로 지지될 때까지 구릅니다. 양손으로 덤벨을 잡고 팔을 가슴 위로 곧게 펼쳐 팔꿈치에 약간의 굽힘을 유지합니다. 덤벨을 머리 뒤로 내리면서 팔을 곧게 유지하고 제어를 유지합니다. 잠시 멈춘 후 덤벨을 시작 위치로 올립니다. 팔을 펼친 상태로 유지하면서 엉덩이를 바닥에서 들어올려 글루트를 수축시키고 코어를 발동합니다. 엉덩이를 시작 위치로 다시 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un ballon d''exercice, les pieds à plat sur le sol et l''haltère posé sur tes cuisses. Avance lentement les pieds, en faisant rouler le ballon d''exercice le long de ton dos jusqu''à ce que ta tête, ta nuque et le haut de ton dos soient soutenus par le ballon. Tiens l''haltère des deux mains et étends tes bras droit au-dessus de ta poitrine, en gardant une légère flexion dans tes coudes. Abaisse l''haltère derrière ta tête, en gardant tes bras tendus et en maintenant le contrôle. Marque une pause, puis ramène l''haltère à la position de départ. Tout en gardant les bras tendus, soulève tes hanches du sol en contractant tes fessiers et en gainant ta sangle abdominale. Redescends tes hanches jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1294-lI7easp.jpg', 'videos/1294-lI7easp.gif', '© Gym visual — https://gymvisual.com/'),
(1295, 'dumbbell pullover on exercise ball', 'chest', 'strength', 'chest', 'dumbbell', 'triceps', 'pectorals', '["triceps","latissimus dorsi"]'::jsonb, '{"en":"Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended. Slowly lower the dumbbell behind your head while keeping your arms straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una palla da ginnastica e tieni un manubrio con entrambe le mani sopra il petto, le braccia distese. Abbassa lentamente il manubrio dietro la testa mantenendo le braccia dritte. Fermati un attimo, poi solleva il manubrio di nuovo alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni.","tr":"Bir egzersiz topunun üzerine oturun ve iki elinizle dambılı göğsünüzün üzerinde, kollarınız uzatılmış şekilde tutun. Kollarınızı düz tutarak dambılı başınızın arkasına yavaşça indirin. Bir an duraklayın ve dambılı tekrar başlangıç ​​pozisyonuna kaldırın. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на гимнастический мяч и держите гантель обеими руками над грудью, вытянув руки. Медленно опустите гантель за голову, сохраняя руки прямыми. Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在健身球上，双手握住哑铃，置于胸前，双臂伸展。 慢慢地将哑铃放到脑后，同时保持手臂伸直。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。","hi":"एक व्यायाम बॉल पर बैठें और दोनों हाथों को अपनी छाती के ऊपर, बाहें फैलाकर डम्बल पकड़ें। अपनी भुजाओं को सीधा रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ। एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na piłce gimnastycznej i trzymaj hantlę obiema rękami nad klatką piersiową, ręce wyprostowane. Powoli opuszczaj hantlę za głowę, utrzymując wyprostowane ręce. Zatrzymaj się na chwilę, a następnie unieś hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"운동공 위에 앉아 가슴 위에 양손으로 덤벨을 잡고 팔을 펼칩니다. 천천히 덤벨을 머리 뒤로 내리면서 팔을 곧게 유지합니다. 잠시 멈춘 후 덤벨을 시작 위치로 올립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un ballon d''exercice et tiens un haltère à deux mains au-dessus de ta poitrine, bras tendus. Abaisse lentement l''haltère derrière ta tête tout en gardant tes bras tendus. Marque une pause, puis ramène l''haltère à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1295-FSD6PGL.jpg', 'videos/1295-FSD6PGL.gif', '© Gym visual — https://gymvisual.com/'),
(1700, 'dumbbell push press', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'triceps', 'delts', '["triceps","core"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level. Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead. Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level. Repeat for the desired number of repetitions.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in ogni mano all''altezza delle spalle. Flette leggermente le ginocchia e abbassa il corpo, poi allunga esplosivamente le gambe e spingi i manubri sopra la testa. Blocca le braccia all''inizio del movimento, poi abbassa i manubri all''altezza delle spalle. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız omuz genişliğinde açık, her iki elinizde de omuz hizasında birer dambıl tutarak ayakta durun. Dizlerinizi hafifçe bükün ve vücudunuzu aşağıya doğru indirin, ardından bacaklarınızı patlayıcı bir şekilde uzatın ve dambılları başınızın üzerine doğru bastırın. Hareketin üst noktasında kollarınızı kilitleyin, ardından dambılları tekrar omuz hizasına indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza. Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держа в каждой руке по гантели на уровне плеч. Слегка согните ноги в коленях и опустите тело вниз, затем резко выпрямите ноги и выжмите гантели над головой. Зафиксируйте руки в верхней точке движения, затем опустите гантели обратно на уровень плеч. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。 稍微弯曲膝盖，身体下沉，然后爆发性伸展双腿，将哑铃压过头顶。 在动作的最高点锁定手臂，然后将哑铃放回肩部水平。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे के स्तर पर डम्बल पकड़ें। अपने घुटनों को थोड़ा मोड़ें और अपने शरीर को नीचे झुकाएं, फिर अपने पैरों को तेजी से फैलाएं और डम्बल को ऊपर की ओर दबाएं। अपनी भुजाओं को गति के शीर्ष पर लॉक कर लें, फिर डम्बल को वापस कंधे के स्तर पर नीचे लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę na wysokości barków. Ugnij lekko kolana i opuść ciało, a następnie gwałtownie wyprostuj nogi i wypchnij hantle nad głowę. Zablokuj ręce na górze ruchu, a następnie opuść hantle z powrotem na wysokość barków. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡아 어깨 높이에 올립니다. 무릎을 약간 구부리고 몸을 살짝 내린 후 발을 폭발적으로 펼치면서 덤벨을 머리 위로 밉니다. 맨 위에서 팔을 완전히 펼친 후 덤벨을 어깨 높이로 다시 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère dans chaque main à hauteur d''épaule. Fléchis légèrement les genoux et descends ton corps, puis étends tes jambes de façon explosive et pousse les haltères au-dessus de ta tête. Verrouille tes bras en haut du mouvement, puis abaisse les haltères à hauteur des épaules. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1700-FS63wTN.jpg', 'videos/1700-FS63wTN.gif', '© Gym visual — https://gymvisual.com/'),
(376, 'dumbbell raise', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'traps', 'delts', '["traps","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai in piedi con i piedi alla larghezza delle spalle e tieni un manubrio in ogni mano, palmi rivolti verso il corpo. Tieni la schiena dritta e attiva il core. Alza le braccia ai lati finché non sono parallele al pavimento, mantenendo una leggera piega dei gomiti. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve avuçlarınız vücudunuza bakacak şekilde her iki elinizde bir dambıl tutun. Sırtınızı düz tutun ve çekirdeğinizi meşgul edin. Kollarınızı yere paralel olana kadar yanlara doğru kaldırın, dirseklerinizi hafif bir şekilde bükün. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу. Держите спину прямо и задействуйте корпус. Поднимите руки в стороны до тех пор, пока они не станут параллельны полу, сохраняя небольшой изгиб в локтях. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持背部挺直并启动核心肌群。 将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों। अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें। अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर तब तक उठाएं जब तक कि वे फर्श के समानांतर न हो जाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę, dłonie skierowane w stronę ciała. Trzymaj proste plecy i napnij brzuch. Unieś ręce na boki, aż będą równoległe do podłogi, utrzymując lekkie ugięcie w łokciach. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡아 몸통 쪽으로 손바닥을 향하게 합니다. 등을 곧게 펼치고 코어를 발동합니다. 팔꿈치에 약간의 굽힘을 유지하면서 팔을 옆으로 들어올려 바닥과 평행하게 합니다. 맨 위에서 잠시 멈춘 후 천천히 팔을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main, paumes tournées vers ton corps. Garde le dos droit et gaine ta sangle abdominale. Lève tes bras sur les côtés jusqu''à ce qu''ils soient parallèles au sol, en gardant une légère flexion dans tes coudes. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0376-c9MnDRp.jpg', 'videos/0376-c9MnDRp.gif', '© Gym visual — https://gymvisual.com/'),
(2292, 'dumbbell rear delt raise', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai in piedi con i piedi alla larghezza delle spalle e tieni un manubrio in ogni mano, palmi rivolti verso il corpo. Piega leggermente le ginocchia e piega in avanti ai fianchi, mantenendo la schiena dritta. Alza le braccia ai lati, mantenendo una leggera piega dei gomiti, finché non sono paralleli al pavimento. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve avuçlarınız vücudunuza bakacak şekilde her iki elinizde bir dambıl tutun. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Kollarınızı yanlara doğru kaldırın, dirseklerinizi hafifçe bükerek yere paralel olana kadar kaldırın. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны полу. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे फर्श के समानांतर न हो जाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę, dłonie skierowane w stronę ciała. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy. Unieś ręce na boki, utrzymując lekkie ugięcie w łokciach, aż będą równoległe do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡아 몸통 쪽으로 손바닥을 향하게 합니다. 무릎을 약간 구부리고 엉덩이에서 구부리면서 등을 곧게 펼칩니다. 팔꿈치에 약간의 굽힘을 유지하면서 팔을 옆으로 들어올려 바닥과 평행하게 합니다. 맨 위에서 잠시 멈춘 후 천천히 팔을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main, paumes tournées vers ton corps. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Lève tes bras sur les côtés en gardant une légère flexion dans tes coudes, jusqu''à ce qu''ils soient parallèles au sol. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/2292-mu5Guxt.jpg', 'videos/2292-mu5Guxt.gif', '© Gym visual — https://gymvisual.com/'),
(377, 'dumbbell rear delt row_shoulder', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with your palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight down towards the floor, with a slight bend in your elbows. Raise the dumbbells out to the sides, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Stai in piedi con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate. Tieni un manubrio in ciascuna mano con i palmi rivolti verso il corpo. Piegati in avanti in vita, mantenendo la schiena dritta e il core attivo. Allunga le braccia dritte verso il pavimento, con una leggera piega dei gomiti. Alza i manubri ai lati, stringendo le scapole insieme. Fermati un attimo in cima, poi abbassa lentamente i manubri alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun. Avuç içleriniz vücudunuza bakacak şekilde her elinizde birer dambıl tutun. Belinizi öne doğru eğin, sırtınızı düz tutun ve merkez bölgenizi meşgul edin. Kollarınızı dirseklerinizi hafif bükerek yere doğru düz bir şekilde uzatın. Omuz bıçaklarınızı birbirine doğru sıkıştırarak dambılları yanlara doğru kaldırın. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos. Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч и слегка согнуты в коленях. Возьмите по гантели в каждую руку ладонями к телу. Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус. Вытяните руки прямо вниз к полу, слегка согнув их в локтях. Поднимите гантели в стороны, сведя лопатки вместе. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 每只手握住一个哑铃，手掌朝向身体。 腰部向前弯曲，保持背部挺直，核心肌群参与。 将手臂伸直向下伸向地板，肘部稍微弯曲。 将哑铃向两侧举起，将肩胛骨挤压在一起。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं। अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें। अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें। अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को फर्श की ओर सीधा फैलाएँ। अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, डम्बल को किनारे की ओर उठाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, kolana lekko ugięte. Trzymaj w każdej dłoni hantlę, dłonie skierowane w stronę ciała. Pochyl się do przodu w talii, utrzymując proste plecy i napięty brzuch. Wyprostuj ręce w dół w stronę podłogi, z lekkim ugięciem w łokciach. Unieś hantle na boki, ściskając łopatki. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 무릎을 약간 구부립니다. 양손에 덤벨을 잡고 손바닥이 몸통을 향하도록 합니다. 허리에서 구부리고 등을 곧게 펼친 채 코어를 발동합니다. 팔을 바닥을 향해 곧게 내리되 팔꿈치는 약간 구부린 상태를 유지합니다. 덤벨을 옆으로 들어올려 어깨 뼈를 함께 모으면서 스쿠즈합니다. 맨 위에서 잠시 멈춘 후 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et les genoux légèrement fléchis. Tiens un haltère dans chaque main, les paumes tournées vers ton corps. Penche-toi vers l''avant au niveau de la taille en gardant ton dos droit et ta sangle abdominale gainée. Étends les bras droit vers le sol, avec une légère flexion dans les coudes. Lève les haltères sur les côtés en contractant tes omoplates l''une vers l''autre. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0377-EKXOMEh.jpg', 'videos/0377-EKXOMEh.gif', '© Gym visual — https://gymvisual.com/'),
(378, 'dumbbell rear fly', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight down towards the ground, palms facing each other. Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi distanti alla larghezza delle spalle e tieni un manubrio in ciascuna mano. Piega leggermente le ginocchia e piega in avanti ai fianchi, mantenendo la schiena dritta. Allunga le braccia dritte verso terra, palmi rivolti l''uno verso l''altro. Mantenendo una leggera piega dei gomiti, alza le braccia ai lati e stringi le scapole insieme. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinize de birer dambıl alın. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Kollarınızı düz bir şekilde yere doğru uzatın, avuçlarınız birbirine baksın. Dirseklerinizi hafif bükerek kollarınızı yanlara doğru kaldırın ve kürek kemiklerinizi birbirine doğru sıkın. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Вытяните руки прямо вниз к земле, ладони обращены друг к другу. Сохраняя небольшой изгиб в локтях, поднимите руки в стороны и сведите лопатки вместе. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将双臂笔直向下伸向地面，手掌相对。 保持肘部轻微弯曲，将手臂向两侧抬起，并将肩胛骨挤压在一起。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। अपनी भुजाओं को ज़मीन की ओर सीधा फैलाएँ, हथेलियाँ एक-दूसरे के सामने हों। अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को बगल की ओर उठाएं और अपने कंधे के ब्लेड को एक साथ दबाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy. Wyprostuj ręce w dół w stronę podłogi, dłonie skierowane do siebie. Utrzymując lekkie ugięcie w łokciach, unieś ręce na boki i ściśnij łopatki. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡습니다. 무릎을 약간 구부리고 엉덩이에서 구부리면서 등을 곧게 펼칩니다. 팔을 바닥을 향해 곧게 내리되 손바닥이 서로 마주보게 합니다. 팔꿈치에 약간의 굽힘을 유지하면서 팔을 옆으로 들어올려 어깨 뼈를 함께 모으면서 스쿠즈합니다. 맨 위에서 잠시 멈춘 후 천천히 팔을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Étends les bras droit vers le sol, les paumes tournées l''une vers l''autre. En gardant une légère flexion des coudes, lève les bras sur les côtés et resserre tes omoplates. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0378-8DiFDVA.jpg', 'videos/0378-8DiFDVA.gif', '© Gym visual — https://gymvisual.com/'),
(380, 'dumbbell rear lateral raise', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'traps', 'delts', '["traps","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai in piedi con i piedi alla larghezza delle spalle e tieni un manubrio in ogni mano, palmi rivolti verso il corpo. Flette leggermente le ginocchia e piega in avanti i fianchi, mantenendo la schiena dritta e il core impegnato. Alza le braccia ai lati, mantenendo una leggera piega dei gomiti, finché non sono paralleli al pavimento. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve avuçlarınız vücudunuza bakacak şekilde her iki elinizde bir dambıl tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göbek bölgenizi meşgul tutun. Kollarınızı yanlara doğru kaldırın, dirseklerinizi hafifçe bükerek yere paralel olana kadar kaldırın. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой и напряженным корпусом. Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны полу. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心参与。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ को सीधा रखें और कोर को व्यस्त रखें। अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे फर्श के समानांतर न हो जाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę, dłonie skierowane w stronę ciała. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy i napięty brzuch. Unieś ręce na boki, utrzymując lekkie ugięcie w łokciach, aż będą równoległe do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡아 몸통 쪽으로 손바닥을 향하게 합니다. 무릎을 약간 구부리고 엉덩이에서 구부리면서 등을 곧게 펼치고 코어를 발동합니다. 팔꿈치에 약간의 굽힘을 유지하면서 팔을 옆으로 들어올려 바닥과 평행하게 합니다. 맨 위에서 잠시 멈춘 후 천천히 팔을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main, paumes tournées vers ton corps. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et ta sangle abdominale gainée. Lève tes bras sur les côtés en gardant une légère flexion dans tes coudes, jusqu''à ce qu''ils soient parallèles au sol. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0380-v1qBec9.jpg', 'videos/0380-v1qBec9.gif', '© Gym visual — https://gymvisual.com/'),
(379, 'dumbbell rear lateral raise (support head)', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'traps', 'delts', '["traps","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi distanti alla larghezza delle spalle e tieni un manubrio in ciascuna mano. Piega leggermente le ginocchia e piega in avanti ai fianchi, mantenendo la schiena dritta. Alza le braccia ai lati, mantenendo una leggera piega dei gomiti, finché non sono paralleli al suolo. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinize de birer dambıl alın. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Kollarınızı yanlara doğru kaldırın, dirseklerinizi hafifçe bükerek yere paralel olana kadar kaldırın. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны земле. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे जमीन के समानांतर न हो जाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy. Unieś ręce na boki, utrzymując lekkie ugięcie w łokciach, aż będą równoległe do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡습니다. 무릎을 약간 구부리고 엉덩이에서 구부리면서 등을 곧게 펼칩니다. 팔꿈치에 약간의 굽힘을 유지하면서 팔을 옆으로 들어올려 바닥과 평행하게 합니다. 맨 위에서 잠시 멈춘 후 천천히 팔을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Lève tes bras sur les côtés en gardant une légère flexion dans tes coudes, jusqu''à ce qu''ils soient parallèles au sol. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0379-UzkLrem.jpg', 'videos/0379-UzkLrem.gif', '© Gym visual — https://gymvisual.com/'),
(381, 'dumbbell rear lunge', 'upper legs', 'strength', 'upper legs', 'dumbbell', 'quadriceps', 'glutes', '["quadriceps","hamstrings","calves"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step backward with your right foot, lowering your body into a lunge position. Bend your left knee and lower your body until your left thigh is parallel to the ground. Pause for a moment, then push through your left heel to return to the starting position. Repeat on the other side, stepping back with your left foot.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in ciascuna mano. Fai un passo indietro con il piede destro, abbassando il corpo in posizione di affondamento. Piega il ginocchio sinistro e abbassa il corpo finché la coscia sinistra non è parallela al suolo. Fermati un attimo, poi spingi attraverso il tallone sinistro per tornare alla posizione di partenza. Ripeti dall''altro lato, facendo un passo indietro con il piede sinistro.","tr":"Ayaklarınız omuz genişliğinde açık, her iki elinizde de birer dambıl tutarak ayakta durun. Sağ ayağınızla geriye doğru bir adım atın ve vücudunuzu hamle pozisyonuna indirin. Sol dizinizi bükün ve sol uyluğunuz yere paralel oluncaya kadar vücudunuzu indirin. Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için sol topuğunuzu itin. Sol ayağınızla geriye adım atarak diğer tarafta tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada. Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial. Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.","ru":"Встаньте, ноги на ширине плеч, держа в каждой руке по гантели. Сделайте шаг назад правой ногой, опуская тело в положение выпада. Согните левое колено и опустите тело до тех пор, пока левое бедро не станет параллельно земле. Сделайте паузу на мгновение, затем оттолкнитесь левой пяткой, чтобы вернуться в исходное положение. Повторите то же самое в другую сторону, отступив левой ногой назад.","zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 右脚向后退一步，将身体降低至弓步位置。 弯曲左膝并降低身体，直到左大腿与地面平行。 暂停片刻，然后推动左脚跟回到起始位置。 在另一侧重复，左脚向后退一步。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें। अपने दाहिने पैर से एक कदम पीछे ले जाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं। अपने बाएं घुटने को मोड़ें और अपने शरीर को तब तक नीचे करें जब तक कि आपकी बाईं जांघ जमीन के समानांतर न हो जाए। एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी से धक्का दें। अपने बाएं पैर से पीछे हटते हुए दूसरी तरफ भी दोहराएं।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę. Zrób krok do tyłu prawą stopą, opuszczając ciało do pozycji wykroku. Ugnij lewe kolano i opuść ciało, aż lewe udo będzie równoległe do podłogi. Zatrzymaj się na chwilę, a następnie odepchnij się od lewej pięty, aby wrócić do pozycji wyjściowej. Powtórz po drugiej stronie, cofając lewą stopę.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡습니다. 오른쪽 발로 뒤로 물러나면서 런지 자세로 몸을 내립니다. 왼쪽 무릎을 구부리고 왼쪽 넓적다리가 바닥과 평행할 때까지 몸을 내립니다. 잠시 멈춘 후 왼쪽 발꿈치를 밀어 시작 위치로 돌아옵니다. 왼쪽 발로 뒤로 물러나면서 반대쪽을 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère dans chaque main. Fais un pas en arrière avec le pied droit, en abaissant ton corps en position de fente. Fléchis ton genou gauche et abaisse ton corps jusqu''à ce que ta cuisse gauche soit parallèle au sol. Marque une pause, puis pousse sur ton talon gauche pour revenir à la position de départ. Répète de l''autre côté en reculant ton pied gauche."}'::jsonb, 'images/0381-SSsBDwB.jpg', 'videos/0381-SSsBDwB.gif', '© Gym visual — https://gymvisual.com/'),
(382, 'dumbbell revers grip biceps curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Stai dritto con un manubrio in ogni mano, palmi rivolti verso il basso e braccia completamente distese. Mantenendo ferme le braccia superiori, espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i pesi finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Her iki elinizde de birer dambıl olacak şekilde dik durun, avuçlarınız aşağıya bakacak ve kollarınız tamamen uzatılmış durumda. Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar ağırlıkları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте прямо, взяв в каждую руку по гантели, ладонями вниз и полностью выпрямленными руками. Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。","hi":"प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ नीचे की ओर हों और बाहें पूरी तरह फैली हुई हों। अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań prosto, trzymając w każdej dłoni hantlę, dłonie skierowane w dół, ręce w pełni wyprostowane. Utrzymując nieruchome ramiona, wykonaj wydech i unieś ciężarki, napinając biceps. Unoś ciężarki, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"양손에 덤벨을 잡고 손바닥이 아래를 향하며 팔이 완전히 펼쳐진 상태로 곧게 섭니다. 상체는 고정한 채로 숨을 내쉬면서 이두근을 수축시키면서 무게를 커핑합니다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 무게를 계속 올립니다. 이두근을 꽉 쥐면서 수축된 위치에서 잠시 멈춥니다. 숨을 들이쉬고 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi bien droit avec un haltère dans chaque main, les paumes tournées vers le bas et les bras complètement tendus. En gardant le haut des bras immobile, expire et fléchis les poids en contractant tes biceps. Continue à lever les poids jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et commence lentement à abaisser les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0382-e4ojVhP.jpg', 'videos/0382-e4ojVhP.gif', '© Gym visual — https://gymvisual.com/'),
(1624, 'dumbbell reverse bench press', 'chest', 'strength', 'chest', 'dumbbell', 'triceps', 'pectorals', '["triceps","shoulders"]'::jsonb, '{"en":"Lie flat on a bench with your feet flat on the ground and your knees bent. Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet. Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows. Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides. Pause for a moment at the bottom, then push the dumbbells back up to the starting position. Repeat for the desired number of repetitions.","it":"Sdraiati disteso su una panchina con i piedi appoggiati a terra e le ginocchia piegate. Tieni un manubrio in ogni mano con una presa sopra la mano, i palmi rivolti verso i piedi. Allunga le braccia dritte verso il soffitto, mantenendo una leggera piega dei gomiti. Abbassa lentamente i manubri verso il petto, permettendo ai gomiti di allargarsi ai lati. Fermati un attimo in fondo, poi spingi di nuovo i manubri fino alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak ve dizleriniz bükülü olacak şekilde bir bankın üzerine düz bir şekilde uzanın. Her iki elinizde de birer dambıl tutun ve avuç içleriniz ayaklarınıza doğru bakacak şekilde tutun. Kollarınızı düz bir şekilde tavana doğru uzatın, dirseklerinizi hafif bir şekilde bükün. Dirseklerinizin yanlara doğru açılmasına izin vererek dambılları yavaşça göğsünüze doğru indirin. Altta bir an duraklayın, ardından dambılları başlangıç ​​pozisyonuna geri itin. İstenilen sayıda tekrar için tekrarlayın.","es":"Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies. Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos. Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.","ru":"Лягте на скамью, поставьте ступни на землю и согните колени. Возьмите по гантели в каждую руку хватом сверху, ладонями к ногам. Вытяните руки прямо вверх к потолку, сохраняя небольшой изгиб в локтях. Медленно опустите гантели к груди, позволяя локтям развестися в стороны. Задержитесь на мгновение в нижней точке, затем верните гантели в исходное положение. Повторите необходимое количество повторений.","zh":"平躺在长凳上，双脚平放在地上，膝盖弯曲。 双手各握一个哑铃，正手握住，手掌朝向脚部。 将手臂伸直向上伸向天花板，保持肘部轻微弯曲。 慢慢地将哑铃降低到胸部，让肘部向两侧张开。 在底部暂停片刻，然后将哑铃推回到起始位置。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक बेंच पर सीधे लेट जाएँ। प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ आपके पैरों की ओर हों। अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को छत की ओर सीधा फैलाएँ। धीरे-धीरे डम्बल को अपनी छाती की ओर नीचे लाएँ, जिससे आपकी कोहनियाँ बगल की ओर फैल जाएँ। नीचे एक क्षण के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में धकेलें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Połóż się na ławce, stopy oprzyj płasko na podłodze, a kolana ugnij. Trzymaj w każdej dłoni hantlę chwytem nachwytem, dłonie skierowane w stronę stóp. Wyprostuj ręce prosto w stronę sufitu, utrzymując lekkie ugięcie w łokciach. Powoli opuszczaj hantle w stronę klatki piersiowej, pozwalając łokciom rozejść się na boki. Zatrzymaj się na chwilę na dole, a następnie wypchnij hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 눕고 발을 바닥에 평평하게 놓고 무릎을 구부립니다. 양손에 덤벨을 잡고 오버핸드 그립으로 손바닥이 발을 향하게 합니다. 팔을 천장 방향으로 곧게 펼쳐 팔꿈치에 약간의 굽힘을 유지합니다. 덤벨을 천천히 가슴 쪽으로 내리면서 팔꿈치를 옆으로 벌립니다. 바닥에서 잠시 멈춘 후 덤벨을 다시 시작 위치로 밀어 올립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Allonge-toi à plat sur un banc, les pieds à plat au sol et les genoux fléchis. Tiens un haltère dans chaque main avec une prise en pronation, les paumes tournées vers tes pieds. Étends les bras droit vers le plafond, en gardant une légère flexion dans les coudes. Abaisse lentement les haltères vers ta poitrine, en laissant tes coudes s''écarter vers les côtés. Marque une pause en bas, puis pousse les haltères vers le haut jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1624-UIbGx6H.jpg', 'videos/1624-UIbGx6H.gif', '© Gym visual — https://gymvisual.com/'),
(383, 'dumbbell reverse fly', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight down in front of you, palms facing each other. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi distanti alla larghezza delle spalle e tieni un manubrio in ciascuna mano. Piega leggermente le ginocchia e piega in avanti ai fianchi, mantenendo la schiena dritta. Allunga le braccia dritte davanti a te, palmi rivolti l''uno verso l''altro. Mantenendo una leggera piega dei gomiti, alza le braccia ai lati finché non sono parallele al suolo. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve her iki elinize de birer dambıl alın. Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin. Kollarınızı düz bir şekilde önünüze doğru uzatın, avuçlarınız birbirine baksın. Dirseklerinizi hafif bükerek kollarınızı yere paralel olana kadar yanlara doğru kaldırın. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели. Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой. Вытяните руки прямо перед собой, ладони обращены друг к другу. Сохраняя небольшой изгиб в локтях, поднимите руки в стороны, пока они не станут параллельны земле. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，每只手各握一个哑铃。 稍微弯曲膝盖，髋部向前转动，保持背部挺直。 将双臂伸直在身前，手掌相对。 保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें। अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें। अपनी भुजाओं को अपने सामने सीधा फैलाएँ, हथेलियाँ एक-दूसरे के सामने हों। अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy. Wyprostuj ręce prosto w dół przed sobą, dłonie skierowane do siebie. Utrzymując lekkie ugięcie w łokciach, unieś ręce na boki, aż będą równoległe do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"발을 어깨 넓이로 벌리고 양손에 덤벨을 잡습니다. 무릎을 약간 구부리고 엉덩이에서 구부리면서 등을 곧게 펼칩니다. 팔을 앞으로 곧게 내리되 손바닥이 서로 마주보게 합니다. 팔꿈치에 약간의 굽힘을 유지하면서 팔을 옆으로 들어올려 바닥과 평행하게 합니다. 맨 위에서 잠시 멈춘 후 천천히 팔을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit. Étends les bras droit vers le bas devant toi, les paumes tournées l''une vers l''autre. En gardant une légère flexion des coudes, lève les bras sur les côtés jusqu''à ce qu''ils soient parallèles au sol. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0383-EAs3xL9.jpg', 'videos/0383-EAs3xL9.gif', '© Gym visual — https://gymvisual.com/'),
(1330, 'dumbbell reverse grip incline bench one arm row', 'back', 'strength', 'back', 'dumbbell', 'biceps', 'upper back', '["biceps","shoulders"]'::jsonb, '{"en":"Set up an incline bench at a 45-degree angle. Place a dumbbell on the floor next to the bench. Stand facing the bench with your feet shoulder-width apart. Bend at the waist and place your left knee and left hand on the bench for support. Pick up the dumbbell with your right hand using a reverse grip (palm facing down). Keep your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body. Squeeze your back muscles at the top of the movement. Lower the dumbbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with your left arm.","it":"Installa una panca inclinata con un angolo di 45 gradi. Metti un manubrio sul pavimento accanto alla panca. Stai rivolto verso la panchina con i piedi alla larghezza delle spalle. Piegati in vita e appoggia il ginocchio sinistro e la mano sinistra sulla panca per sostenerti. Prendi il manubrio con la mano destra usando una presa invertita (palmo rivolto verso il basso). Tieni la schiena dritta e il core attivo. Tira il manubrio verso il petto, tenendo il gomito vicino al corpo. Stringi i muscoli della schiena nella parte alta del movimento. Abbassa il manubrio di nuovo alla posizione di partenza in modo controllato. Ripeti per il numero desiderato di ripetizioni. Cambia lato e ripeti l''esercizio con il braccio sinistro.","tr":"45 derecelik bir açıyla eğimli bir tezgah kurun. Tezgahın yanındaki yere bir dambıl yerleştirin. Ayaklarınız omuz genişliğinde açık olacak şekilde benche dönük durun. Belinizi bükün ve destek için sol dizinizi ve sol elinizi sehpanın üzerine yerleştirin. Ters tutuş kullanarak (avuç içi aşağı bakacak şekilde) sağ elinizle dambılı alın. Sırtınızı düz ve merkez bölgenizi meşgul tutun. Dirseğinizi vücudunuza yakın tutarak dambılı göğsünüze doğru çekin. Hareketin üst noktasında sırt kaslarınızı sıkın. Dambılı kontrollü bir şekilde başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın. Taraf değiştirin ve egzersizi sol kolunuzla tekrarlayın.","es":"Coloca un banco inclinado a un ángulo de 45 grados. Coloca una mancuerna en el suelo junto al banco. Ponte de pie frente al banco con los pies separados a la altura de los hombros. Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte. Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo). Mantén la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Aprieta los músculos de la espalda en la parte superior del movimiento. Baja la mancuerna de nuevo a la posición inicial de manera controlada. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo izquierdo.","ru":"Установите наклонную скамью под углом 45 градусов. Положите гантель на пол рядом со скамейкой. Встаньте лицом к скамье, поставив ноги на ширине плеч. Согнитесь в талии и положите левое колено и левую руку на скамью для поддержки. Возьмите гантель правой рукой обратным хватом (ладонью вниз). Держите спину прямо, а корпус напряженным. Подтяните гантель к груди, держа локоть близко к телу. Напрягите мышцы спины в верхней точке движения. Контролируемым образом опустите гантель обратно в исходное положение. Повторите необходимое количество повторений. Поменяйте сторону и повторите упражнение левой рукой.","zh":"设置一个 45 度角的上斜凳。 将哑铃放在长凳旁边的地板上。 面对长凳站立，双脚分开与肩同宽。 弯曲腰部，将左膝和左手放在长凳上以获得支撑。 用右手反握（手掌朝下）拿起哑铃。 保持背部挺直，核心肌群参与。 将哑铃向上拉向胸部，保持肘部靠近身体。 在动作的最高点挤压背部肌肉。 以受控的方式将哑铃放回起始位置。 重复所需的重复次数。 换边并用左臂重复练习。","hi":"45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें। बेंच के बगल में फर्श पर डम्बल रखें। अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बेंच की ओर मुंह करके खड़े हो जाएं। कमर को मोड़ें और अपने बाएँ घुटने और बाएँ हाथ को सहारे के लिए बेंच पर रखें। रिवर्स ग्रिप (हथेली नीचे की ओर) का उपयोग करके अपने दाहिने हाथ से डम्बल उठाएं। अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें। अपनी कोहनी को अपने शरीर के पास रखते हुए डम्बल को अपनी छाती की ओर ऊपर खींचें। आंदोलन के शीर्ष पर अपनी पीठ की मांसपेशियों को निचोड़ें। डम्बल को नियंत्रित तरीके से वापस प्रारंभिक स्थिति में लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ। करवट बदलें और अपने बाएं हाथ से व्यायाम दोहराएं।","pl":"Ustaw ławkę skośną pod kątem 45 stopni. Postaw hantlę na podłodze obok ławki. Stań przodem do ławki, w rozkroku na szerokość barków. Pochyl się w talii i oprzyj lewe kolano i lewą dłoń na ławce dla stabilizacji. Podnieś hantlę prawą ręką chwytem odwrotnym (dłoń skierowana w dół). Trzymaj proste plecy i napięty brzuch. Podciągnij hantlę w stronę klatki piersiowej, trzymając łokieć blisko ciała. Ściśnij mięśnie pleców na górze ruchu. Opuść hantlę z powrotem do pozycji wyjściowej w kontrolowany sposób. Powtórz zalecaną liczbę powtórzeń. Zmień strony i powtórz ćwiczenie lewą ręką.","ko":"인클라인 벤치를 45도 각도로 설정합니다. 덤벨을 벤치 옆 바닥에 놓습니다. 벤치를 향해 서서 발을 어깨 넓이로 벌립니다. 허리를 구부리고 왼쪽 무릎과 왼쪽 손을 벤치에 올려 지탱합니다. 역그립(손바닥 아래쪽)으로 덤벨을 오른손으로 집습니다. 등을 곧게 펼치고 코어를 발동합니다. 덤벨을 가슴 쪽으로 당기면서 팔꿈치를 몸에 가깝게 유지합니다. 동작의 맨 위에서 등 근육을 스쿠즈합니다. 제어되는 방식으로 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다. 왼팔로 운동을 반복하면서 옆을 바꿉니다.","fr":"Installe un banc incliné à un angle de 45 degrés. Place un haltère au sol à côté du banc. Tiens-toi face au banc, les pieds écartés à la largeur des épaules. Penche-toi au niveau de la taille et place ton genou gauche et ta main gauche sur le banc pour te soutenir. Attrape l''haltère avec ta main droite en prise inversée (paume tournée vers le bas). Garde le dos droit et ta sangle abdominale gainée. Tire l''haltère vers le haut en direction de ta poitrine, en gardant ton coude près de ton corps. Contracte les muscles de ton dos en haut du mouvement. Abaisse l''haltère jusqu''à la position de départ de manière contrôlée. Répète le nombre de répétitions souhaité. Change de côté et répète l''exercice avec ton bras gauche."}'::jsonb, 'images/1330-ZIViNh1.jpg', 'videos/1330-ZIViNh1.gif', '© Gym visual — https://gymvisual.com/'),
(1331, 'dumbbell reverse grip incline bench two arm row', 'back', 'strength', 'back', 'dumbbell', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Set up an incline bench at a 45-degree angle. Sit on the bench with your chest against the backrest and your feet flat on the ground. Hold a dumbbell in each hand with an underhand grip. Lean forward and let your arms hang straight down, fully extended. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.","it":"Installa una panca inclinata con un angolo di 45 gradi. Siediti sulla panchina con il petto appoggiato allo schienale e i piedi piatti a terra. Tieni un manubrio in ogni mano con una presa sottomano. Piegati in avanti e lascia che le braccia pendano dritte verso il basso, completamente estese. Tira i manubri verso il petto, stringendo le scapole insieme. Fermati un attimo in cima, poi abbassa lentamente i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"45 derecelik bir açıyla eğimli bir tezgah kurun. Göğsünüz sırtlığa dayalı ve ayaklarınız yere düz basacak şekilde bankta oturun. Her iki elinizde de alttan kavramayla birer dambıl tutun. Öne doğru eğilin ve kollarınızın tamamen uzatılmış şekilde düz bir şekilde aşağı sarkmasına izin verin. Dambılları göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo. Sujeta una mancuerna en cada mano con agarre supino. Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Установите наклонную скамью под углом 45 градусов. Сядьте на скамью, прижав грудь к спинке, а ноги поставьте на землю. Возьмите в каждую руку по гантели обратным хватом. Наклонитесь вперед и позвольте рукам свисать прямо вниз, полностью выпрямившись. Подтяните гантели к груди, сведя лопатки вместе. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"设置一个 45 度角的上斜凳。 坐在长凳上，胸部靠在靠背上，双脚平放在地上。 双手各握一个哑铃，反握。 身体前倾，双臂伸直下垂，完全伸展。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें। बेंच पर अपनी छाती को बैकरेस्ट से सटाकर बैठें और आपके पैर ज़मीन पर सपाट हों। प्रत्येक हाथ में एक डम्बल को अंडरहैंड ग्रिप से पकड़ें। आगे की ओर झुकें और अपनी भुजाओं को पूरी तरह फैलाकर सीधा नीचे लटका दें। अपने कंधे के ब्लेड को एक साथ दबाते हुए, डम्बल को अपनी छाती की ओर खींचें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Ustaw ławkę skośną pod kątem 45 stopni. Usiądź na ławce, opierając klatkę piersiową o oparcie, stopy płasko na podłodze. Trzymaj w każdej dłoni hantlę chwytem podchwytem. Pochyl się do przodu i pozwól rękom zwisać prosto w dół, w pełni wyprostowanym. Podciągnij hantle w stronę klatki piersiowej, ściskając łopatki. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"인클라인 벤치를 45도 각도로 설정합니다. 등받이에 가슴을 대고 벤치에 앉아 발을 바닥에 평평하게 놓습니다. 언더핸드 그립으로 양손에 덤벨을 잡습니다. 몸을 앞으로 구부리고 팔이 완전히 펼쳐진 상태로 곧게 내립니다. 덤벨을 가슴 쪽으로 당기면서 어깨 뼈를 함께 모으면서 스쿠즈합니다. 맨 위에서 잠시 멈춘 후 천천히 덤벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다.","fr":"Installe un banc incliné à un angle de 45 degrés. Assieds-toi sur le banc, la poitrine contre le dossier et les pieds à plat sur le sol. Tiens un haltère dans chaque main avec une prise en supination. Penche-toi en avant et laisse tes bras pendre droit vers le bas, entièrement tendus. Tire les haltères vers ta poitrine en contractant tes omoplates l''une vers l''autre. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1331-9pQSkH8.jpg', 'videos/1331-9pQSkH8.gif', '© Gym visual — https://gymvisual.com/'),
(2327, 'dumbbell reverse grip row (female)', 'back', 'strength', 'back', 'dumbbell', 'biceps', 'upper back', '["biceps","forearms"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with an overhand grip, palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Let your arms hang straight down, fully extended, with a slight bend in your elbows. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.","it":"Stai in piedi con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate. Tieni un manubrio in ciascuna mano con una presa sopra la mano, palmi rivolti verso il corpo. Piegati in avanti in vita, mantenendo la schiena dritta e il core attivo. Lascia che le braccia pendano dritte verso il basso, completamente estese, con una leggera piega dei gomiti. Tira i manubri verso il petto, stringendo le scapole insieme. Fermati un attimo in cima, poi abbassa lentamente i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun. Her iki elinizde de birer dambıl tutun ve avuçlarınız vücudunuza bakacak şekilde üstten tutun. Belinizi öne doğru eğin, sırtınızı düz tutun ve merkez bölgenizi meşgul edin. Dirseklerinizi hafif bir şekilde bükerek kollarınızın tamamen uzatılmış şekilde düz bir şekilde aşağı sarkmasına izin verin. Dambılları göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч и слегка согнуты в коленях. Возьмите по гантели в каждую руку хватом сверху, ладонями к телу. Наклонитесь вперед в талии, сохраняя спину прямой и напрягая корпус. Пусть ваши руки свисают прямо вниз, полностью выпрямлены, слегка согнуты в локтях. Подтяните гантели к груди, сведя лопатки вместе. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"站立，双脚分开与肩同宽，膝盖稍微弯曲。 双手各握一个哑铃，正手握握，手掌朝向身体。 腰部向前弯曲，保持背部挺直，核心肌群参与。 让你的手臂伸直垂下，完全伸展，肘部稍微弯曲。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं। प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ आपके शरीर की ओर हों। अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें। अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को सीधा नीचे लटकने दें, पूरी तरह फैला हुआ रखें। अपने कंधे के ब्लेड को एक साथ दबाते हुए, डम्बल को अपनी छाती की ओर खींचें। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, kolana lekko ugięte. Trzymaj w każdej dłoni hantlę chwytem nachwytem, dłonie skierowane w stronę ciała. Pochyl się do przodu w talii, utrzymując proste plecy i napięty brzuch. Pozwól rękom zwisać prosto w dół, w pełni wyprostowanym, z lekkim ugięciem w łokciach. Podciągnij hantle w stronę klatki piersiowej, ściskając łopatki. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"어깨너비로 발을 벌리고 무릎을 약간 구부려 선다. 각 손에 덤벨을 들되 손바닥이 몸을 향하도록 오버핸드 그립으로 잡는다. 허리에서 몸을 굽혀 등을 곧게 유지하고 복부에 힘을 준다. 팔을 곧게 아래로 내린 상태에서 팔꿈치에 약간의 굽힘이 있도록 한다. 덤벨을 가슴 쪽으로 당기면서 어깨 날개뼈를 함께 조인다. 맨 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내린다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et les genoux légèrement fléchis. Tiens un haltère dans chaque main avec une prise en pronation, les paumes tournées vers ton corps. Penche-toi vers l''avant au niveau de la taille en gardant ton dos droit et ta sangle abdominale gainée. Laisse tes bras pendre droit vers le bas, entièrement tendus, avec une légère flexion dans les coudes. Tire les haltères vers ta poitrine en contractant tes omoplates l''une vers l''autre. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/2327-Nh3mvOO.jpg', 'videos/2327-Nh3mvOO.gif', '© Gym visual — https://gymvisual.com/'),
(384, 'dumbbell reverse preacher curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Hold a dumbbell in each hand with an underhand grip, palms facing up. Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps. Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panca da predicatore con le braccia superiori appoggiate sul cuscinetto e il petto appoggiato al supporto. Tieni un manubrio in ogni mano con una presa sottomano, palmi rivolti verso l''alto. Mantenendo ferme le braccia superiori, espira e arriccia i manubri mentre contrai i bicipiti. Continua a arricciare i manubri finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e abbassa lentamente i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Üst kollarınız yastığa ve göğsünüz desteğe dayanacak şekilde bir vaiz bankına oturun. Her iki elinizde de birer dambıl tutun ve avuç içleriniz yukarı bakacak şekilde alttan tutun. Üst kollarınızı sabit tutarak, bisepslerinizi kasarken dambılları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar dambılları kıvırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba. Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps. Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью для проповедника, положив плечи на подушку и грудь на опору. Возьмите в каждую руку по гантели обратным хватом ладонями вверх. Удерживая плечи неподвижно, выдохните и согните гантели, сокращая бицепсы. Продолжайте сгибать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。 每只手握住一个哑铃，反握，手掌朝上。 保持上臂静止，呼气并弯曲哑铃，同时收缩二头肌。 继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपनी ऊपरी बांहों को पैड पर और अपनी छाती को सहारे पर टिकाकर एक उपदेशक बेंच पर बैठें। प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर। अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को मोड़ें। डम्बल को तब तक मोड़ना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce modlitewnej (Scotta), opierając ramiona na podkładce i klatkę piersiową o oparcie. Trzymaj w każdej dłoni hantlę chwytem podchwytem, dłonie skierowane do góry. Utrzymując nieruchome ramiona, wykonaj wydech i unieś hantle, napinając biceps. Unoś hantle, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"프리처 벤치에 앉아 위팔을 패드 위에 얹고 가슴을 지지대에 기댄다. 각 손에 덤벨을 들되 손바닥이 위를 향하도록 언더핸드 그립으로 잡는다. 위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 덤벨을 위로 올린다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다. 수축된 위치에서 잠깐 멈추면서 이두근을 조인다. 숨을 들이쉬면서 천천히 덤벨을 시작 위치로 낮춘다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc à prêcheur, le haut de tes bras posé sur le coussin et ta poitrine contre le support. Tiens un haltère dans chaque main avec une prise en supination, les paumes tournées vers le haut. En gardant le haut des bras immobile, expire et fléchis les haltères en contractant tes biceps. Continue à enrouler les haltères jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et abaisse lentement les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0384-O8Aq69u.jpg', 'videos/0384-O8Aq69u.gif', '© Gym visual — https://gymvisual.com/'),
(1675, 'dumbbell reverse spider curl', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Stai dritto con un manubrio in ogni mano, palmi rivolti verso il corpo e braccia completamente distese. Mantenendo ferme le braccia superiori, espira e arriccia i pesi mentre contrahi i bicipiti. Continua ad alzare i manubri finché i bicipiti non sono completamente contratti e i manubri non sono all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e inizia lentamente ad abbassare i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Her iki elinizde de birer dambıl olacak şekilde dik durun, avuçlarınız vücudunuza dönük ve kollarınız tamamen uzatılmış durumda. Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın. Bisepsleriniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar dambılları kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılları yavaşça başlangıç ​​pozisyonuna indirmeye başlayın. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте прямо, взяв в каждую руку по гантели, ладони обращены к телу, руки полностью выпрямлены. Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы. Продолжайте поднимать гантели до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно начните опускать гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"站直，双手各握一个哑铃，手掌朝向身体，双臂完全伸展。 保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气并慢慢开始将哑铃放回起始位置。 重复所需的重复次数。","hi":"प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों और भुजाएँ पूरी तरह फैली हुई हों। अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें। डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań prosto, trzymając w każdej dłoni hantlę, dłonie skierowane w stronę ciała, ręce w pełni wyprostowane. Utrzymując nieruchome ramiona, wykonaj wydech i unieś ciężarki, napinając biceps. Unoś hantle, aż biceps będzie maksymalnie napięty, a hantle znajdą się na wysokości barków. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli zacznij opuszczać hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"직립 자세로 서서 양손에 덤벨을 들되 손바닥이 몸을 향하고 팔을 완전히 펼친다. 위팔을 고정한 채 숨을 내쉬면서 이두근을 수축시켜 무게를 위로 올린다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다. 수축된 위치에서 잠깐 멈추면서 이두근을 조인다. 숨을 들이쉬면서 천천히 덤벨을 시작 위치로 내리기 시작한다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi bien droit avec un haltère dans chaque main, les paumes tournées vers ton corps et les bras complètement tendus. En gardant le haut des bras immobile, expire et fléchis les poids en contractant tes biceps. Continue à lever les haltères jusqu''à ce que tes biceps soient complètement contractés et que les haltères soient à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et commence lentement à abaisser les haltères jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1675-6sMAmNv.jpg', 'videos/1675-6sMAmNv.gif', '© Gym visual — https://gymvisual.com/'),
(385, 'dumbbell reverse wrist curl', 'lower arms', 'strength', 'lower arms', 'dumbbell', 'biceps', 'forearms', '["biceps","brachialis"]'::jsonb, '{"en":"Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the dumbbells towards your body. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panca o una sedia con i piedi piatti a terra. Tieni un manubrio in ogni mano con una presa sopra la mano, palmi rivolti verso il basso. Appoggia gli avambracci sulle cosce, lasciando che i polsi penzolano dal bordo. Piega lentamente i polsi verso l''alto, portando i manubri verso il corpo. Fermati un attimo in cima, poi abbassa lentamente i manubri fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun. Her iki elinizde de birer dambıl tutun ve avuç içleriniz aşağıya bakacak şekilde tutun. Ön kollarınızı uyluklarınıza yaslayın, bileklerinizin kenardan sarkmasına izin verin. Bileklerinizi yavaşça yukarı doğru kıvırarak dambılları vücudunuza doğru getirin. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco o silla con los pies apoyados en el suelo. Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью или стул, поставив ноги на землю. Возьмите по гантели в каждую руку хватом сверху, ладонями вниз. Положите предплечья на бедра, позволяя запястьям свисать с края. Медленно поднимите запястья вверх, приближая гантели к телу. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳或椅子上，双脚平放在地面上。 双手各握一个哑铃，正手握握，手掌朝下。 将前臂放在大腿上，让手腕悬在边缘。 慢慢向上弯曲手腕，将哑铃拉向身体。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें। प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ नीचे की ओर हों। अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ। धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, डम्बल को अपने शरीर की ओर लाएं। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce lub krześle, stopy oprzyj płasko na podłodze. Trzymaj w każdej dłoni hantlę chwytem nachwytem, dłonie skierowane w dół. Oprzyj przedramiona na udach, pozwalając nadgarstkom zwisać poza krawędzią. Powoli zginaj nadgarstki do góry, przyciągając hantle w stronę ciała. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치나 의자에 앉아 발을 땅에 댄다. 각 손에 덤벨을 들되 손바닥이 아래를 향하도록 오버핸드 그립으로 잡는다. 팔뚝을 허벅지 위에 올리고 손목이 가장자리에서 떨어지도록 한다. 천천히 손목을 위쪽으로 구부려 덤벨을 몸 쪽으로 당긴다. 맨 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 내린다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc ou une chaise, les pieds à plat sur le sol. Tiens un haltère dans chaque main avec une prise en pronation, les paumes tournées vers le bas. Pose tes avant-bras sur tes cuisses, en laissant tes poignets dépasser du bord. Enroule lentement tes poignets vers le haut, en ramenant les haltères vers ton corps. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0385-BLCvwr2.jpg', 'videos/0385-BLCvwr2.gif', '© Gym visual — https://gymvisual.com/'),
(1459, 'dumbbell romanian deadlift', 'upper legs', 'strength', 'upper legs', 'dumbbell', 'hamstrings', 'glutes', '["hamstrings","lower back"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly. Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi a larghezza delle spalle, tenendo un manubrio in ogni mano con una presa sopra la testa. Tenendo la schiena dritta e il core attivo, incurvati ai fianchi e abbassa i manubri verso terra, permettendo alle ginocchia di piegarsi leggermente. Abbassa i manubri finché non senti uno stiramento ai muscoli femorale, poi spingi attraverso i talloni e attiva i glutei per tornare alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın, her iki elinizde de birer dambıl tutun ve üstten kavrayın. Sırtınızı düz ve merkez bölgenizi meşgul tutarak, kalçalarınıza yaslanın ve dambılları yere doğru indirerek dizlerinizin hafifçe bükülmesine izin verin. Diz arkası kirişlerinizde bir gerginlik hissedene kadar dambılları indirin, ardından topuklarınızı itin ve başlangıç ​​pozisyonuna dönmek için kalça kaslarınızı çalıştırın. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, держите по гантели в каждой руке хватом сверху. Удерживая спину прямой, а корпус напряженным, наклонитесь в бедрах и опустите гантели к земле, слегка согнув колени. Опускайте гантели до тех пор, пока не почувствуете растяжение подколенных сухожилий, затем надавите на пятки и задействуйте ягодицы, чтобы вернуться в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，正握。 保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让膝盖稍微弯曲。 降低哑铃，直到感觉到腿筋拉伸，然后推动脚后跟并收紧臀肌，回到起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें। अपनी पीठ को सीधा और अपने कोर को व्यस्त रखते हुए, कूल्हों पर टिकाएं और डम्बल को जमीन की ओर झुकाएं, जिससे आपके घुटने थोड़े मुड़ जाएं। जब तक आप अपनी हैमस्ट्रिंग में खिंचाव महसूस न करें तब तक डम्बल को नीचे रखें, फिर अपनी एड़ियों से धक्का दें और अपने ग्लूट्स को जोड़कर प्रारंभिक स्थिति में लौट आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę chwytem nachwytem. Utrzymując proste plecy i napięty brzuch, pochyl się w biodrach i opuszczaj hantle w stronę podłogi, pozwalając kolanom lekko się ugiąć. Opuszczaj hantle, aż poczujesz rozciąganie w mięśniach dwugłowych uda, a następnie odepchnij się piętami i napnij pośladki, aby wrócić do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"어깨너비로 발을 벌리고 각 손에 덤벨을 들되 오버핸드 그립으로 잡는다. 등을 곧게 유지하고 복부에 힘을 준 채 엉덩이에서 몸을 구부려 덤벨을 땅 쪽으로 낮춘다. 무릎이 약간 구부러지도록 허용한다. 햄스트링에서 스트레칭을 느낄 때까지 덤벨을 낮춘 후 발뒤꿈치를 통해 힘을 주고 둔근을 수축시켜 시작 위치로 돌아온다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules, en tenant un haltère dans chaque main en prise pronation. En gardant le dos droit et ta sangle abdominale gainée, bascule au niveau des hanches et abaisse les haltères vers le sol, en laissant tes genoux se fléchir légèrement. Abaisse les haltères jusqu''à ce que tu ressentes un étirement dans tes ischio-jambiers, puis pousse sur tes talons et gaine tes fessiers pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/1459-rR0LJzx.jpg', 'videos/1459-rR0LJzx.gif', '© Gym visual — https://gymvisual.com/'),
(386, 'dumbbell rotation reverse fly', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Rotate your arms so that your palms are facing downwards. Slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.","it":"Stai con i piedi alla larghezza delle spalle e tieni un manubrio in ogni mano, con i palmi rivolti verso l''interno. Flette leggermente le ginocchia e piega in avanti sui fianchi, mantenendo la schiena dritta e il petto sollevato. Alza le braccia ai lati, mantenendo una leggera piega dei gomiti, finché non sono paralleli al pavimento. Ruota le braccia in modo che i palmi siano rivolti verso il basso. Abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Ayaklarınızı omuz genişliğinde açın ve avuç içleriniz içe bakacak şekilde her iki elinizde bir dambıl tutun. Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun. Kollarınızı yanlara doğru kaldırın, dirseklerinizi hafifçe bükerek yere paralel olana kadar kaldırın. Avuç içleriniz aşağıya bakacak şekilde kollarınızı çevirin. Kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Gira los brazos de modo que las palmas queden mirando hacia abajo. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями внутрь. Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх. Поднимите руки в стороны, сохраняя небольшой изгиб в локтях, пока они не станут параллельны полу. Поверните руки так, чтобы ладони были направлены вниз. Медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"双脚分开与肩同宽站立，双手各握一个哑铃，掌心向内。 稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。 将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。 旋转手臂，使手掌朝下。 慢慢地将手臂放回起始位置。 重复所需的重复次数。","hi":"अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां अंदर की ओर हों। अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें। अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे फर्श के समानांतर न हो जाएं। अपनी भुजाओं को इस प्रकार घुमाएँ कि आपकी हथेलियाँ नीचे की ओर हों। धीरे-धीरे अपनी भुजाओं को प्रारंभिक स्थिति में वापस लाएँ। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Stań w rozkroku na szerokość barków, trzymając w każdej dłoni hantlę, dłonie skierowane do wewnątrz. Ugnij lekko kolana i pochyl tułów w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową. Unieś ręce na boki, utrzymując lekkie ugięcie w łokciach, aż będą równoległe do podłogi. Obróć ręce tak, aby dłonie były skierowane w dół. Powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"어깨너비로 발을 벌리고 양손에 덤벨을 들되 손바닥이 안쪽을 향하도록 한다. 무릎을 약간 구부리고 엉덩이에서 몸을 구부려 등을 곧게 유지하고 가슴을 펼친다. 팔꿈치를 약간 구부린 채 팔을 옆쪽으로 들어올려 바닥과 평행하게 만든다. 손바닥이 아래를 향하도록 팔을 회전시킨다. 천천히 팔을 시작 위치로 낮춘다. 원하는 반복 횟수만큼 반복합니다.","fr":"Tiens-toi debout, les pieds écartés à la largeur des épaules et tiens un haltère dans chaque main, paumes tournées vers l''intérieur. Fléchis légèrement les genoux et bascule vers l''avant au niveau des hanches en gardant le dos droit et la poitrine relevée. Lève tes bras sur les côtés en gardant une légère flexion dans tes coudes, jusqu''à ce qu''ils soient parallèles au sol. Fais tourner tes bras de sorte que tes paumes soient tournées vers le bas. Abaisse lentement tes bras vers la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0386-prbWx1D.jpg', 'videos/0386-prbWx1D.gif', '© Gym visual — https://gymvisual.com/'),
(2397, 'dumbbell scott press', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'triceps', 'delts', '["triceps","chest"]'::jsonb, '{"en":"Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panchina con un manubrio in ciascuna mano, i palmi rivolti in avanti. Alza i manubri all''altezza delle spalle, con i gomiti piegati e i palmi rivolti in avanti. Premi i manubri verso l''alto finché le braccia non sono completamente estese. Fermati un attimo in cima, poi abbassa lentamente i manubri alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Her iki elinizde birer dambıl olacak şekilde, avuç içleriniz öne bakacak şekilde bir bankta oturun. Dirsekleriniz bükülü ve avuç içleriniz öne bakacak şekilde dambılları omuz yüksekliğine kaldırın. Kollarınız tamamen uzayıncaya kadar dambılları yukarı doğru bastırın. Tepe noktasında bir süre duraklayın, ardından dambılları yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, взяв в каждую руку по гантели ладонями вперед. Поднимите гантели на высоту плеч, согнув локти и повернув ладони вперед. Выжмите гантели вверх, пока руки полностью не выпрямятся. Задержитесь на мгновение в верхней точке, затем медленно опустите гантели обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳上，双手各握一个哑铃，手掌朝前。 将哑铃举至肩部高度，肘部弯曲，手掌朝前。 向上推哑铃，直到手臂完全伸展。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。","hi":"प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आगे की ओर हों। अपनी कोहनियों को मोड़कर और हथेलियों को आगे की ओर रखते हुए डम्बल को कंधे की ऊंचाई तक उठाएं। डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce, trzymając w każdej dłoni hantlę, dłonie skierowane do przodu. Unieś hantle na wysokość barków, z łokciami zgiętymi i dłońmi skierowanymi do przodu. Wypchnij hantle do góry, aż ramiona będą w pełni wyprostowane. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantle z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 양손에 덤벨을 들되 손바닥이 앞을 향하도록 한다. 덤벨을 어깨 높이로 올리되 팔꿈치를 구부리고 손바닥이 앞을 향하도록 한다. 덤벨을 위로 밀어올려 팔을 완전히 펼친다. 맨 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 낮춘다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc avec un haltère dans chaque main, paumes tournées vers l''avant. Lève les haltères à hauteur des épaules, tes coudes fléchis et tes paumes tournées vers l''avant. Pousse les haltères vers le haut jusqu''à ce que tes bras soient complètement tendus. Marque une pause en haut, puis abaisse lentement les haltères pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/2397-5vfAI0I.jpg', 'videos/2397-5vfAI0I.gif', '© Gym visual — https://gymvisual.com/'),
(387, 'dumbbell seated alternate front raise', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","biceps"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides. Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.","it":"Siediti su una panchina con la schiena dritta e i piedi piatti a terra. Tieni un manubrio in ogni mano con i palmi rivolti verso il corpo e le braccia distese lungo i lati. Tenendo le braccia dritte, alza un manubrio davanti a te finché non è parallelo al suolo. Fermati un attimo in cima, poi abbassa lentamente il manubrio fino alla posizione di partenza. Ripeti con l''altro braccio. Alternare tra le armi per il numero desiderato di ripetizioni.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Avuç içleriniz vücudunuza bakacak ve kollarınız yanlarınızda uzanacak şekilde her iki elinizde birer dambıl tutun. Kollarınızı düz tutarak önünüzdeki bir dambılı yere paralel oluncaya kadar kaldırın. Tepe noktasında bir süre duraklayın, ardından dambılı yavaşça başlangıç ​​pozisyonuna indirin. Diğer kolla tekrarlayın. İstenilen sayıda tekrar için kollar arasında geçiş yapın.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados. Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Возьмите по гантели в каждую руку ладонями к телу, а руки вытяните вниз по бокам. Держа руки прямыми, поднимите одну гантель перед собой до тех пор, пока она не станет параллельна земле. Задержитесь на мгновение в верхней точке, затем медленно опустите гантель обратно в исходное положение. Повторите с другой рукой. Чередуйте руки, выполняя желаемое количество повторений.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。 保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。 在顶部停顿片刻，然后慢慢将哑铃放回起始位置。 用另一只手臂重复上述步骤。 双臂交替进行所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। प्रत्येक हाथ में एक डम्बल पकड़ें, अपनी हथेलियों को अपने शरीर की ओर रखें और भुजाएँ अपनी तरफ नीचे की ओर फैलाएँ। अपनी भुजाओं को सीधा रखते हुए, एक डम्बल को अपने सामने तब तक उठाएँ जब तक कि वह ज़मीन के समानांतर न हो जाए। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं। दूसरे हाथ से दोहराएँ. दोहराव की वांछित संख्या के लिए भुजाओं के बीच वैकल्पिक करें।","pl":"Usiądź na ławce, trzymając plecy proste i stopy płasko na podłodze. Trzymaj w każdej dłoni hantlę, dłonie skierowane w stronę ciała, ręce wyprostowane wzdłuż boków ciała. Utrzymując proste ręce, unieś jedną hantlę przed sobą, aż będzie równoległa do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz drugą ręką. Kontynuuj naprzemienne wykonywanie ćwiczenia przez zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 등을 곧게 펴고 발을 땅에 댄다. 양손에 덤벨을 들되 손바닥이 몸을 향하고 팔을 아래로 펼친 상태로 옆에 둔다. 팔을 곧게 펼친 채 한쪽 덤벨을 몸 앞쪽으로 들어올려 바닥과 평행하게 만든다. 맨 위에서 잠깐 멈춘 후 천천히 덤벨을 시작 위치로 낮춘다. 다른 팔로 반복한다. 양팔을 교대로 반복하며 원하는 반복 횟수만큼 수행합니다.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un haltère dans chaque main, les paumes tournées vers ton corps et les bras étendus le long de tes flancs. En gardant les bras tendus, lève un haltère devant toi jusqu''à ce qu''il soit parallèle au sol. Marque une pause en haut, puis abaisse lentement l''haltère pour revenir à la position de départ. Répète avec l''autre bras. Alterne les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/0387-gH5fRsC.jpg', 'videos/0387-gH5fRsC.gif', '© Gym visual — https://gymvisual.com/'),
(1676, 'dumbbell seated alternate hammer curl on exercise ball', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'forearms', 'biceps', '["forearms"]'::jsonb, '{"en":"Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.","it":"Siediti su una palla da ginnastica con i piedi piatti a terra e la schiena dritta. Tieni un manubrio in ogni mano con i palmi rivolti verso il corpo e le braccia completamente estese. Tenendo ferme le braccia superiori, espira e arriccia un manubrio verso la spalla mantenendo il palmo rivolto verso il corpo. Continua ad alzare il manubrio finché i bicipiti non sono completamente contratti e il manubrio non è all''altezza delle spalle. Mantieni la posizione contratta per una breve pausa mentre stringi i bicipiti. Inspira e abbassa lentamente il manubrio alla posizione iniziale. Ripeti il movimento con il braccio opposto. Continuare ad alternare le braccia per il numero desiderato di ripetizioni.","tr":"Ayaklarınız yere düz basacak ve sırtınız düz olacak şekilde bir egzersiz topunun üzerine oturun. Avuç içleriniz vücudunuza bakacak ve kollarınız tamamen uzatılmış şekilde her elinizde bir dambıl tutun. Üst kollarınızı sabit tutarak nefes verin ve bir dambılı omzunuza doğru kıvırırken avucunuzu vücudunuza doğru tutun. Bisepsleriniz tamamen kasılana ve dambıl omuz hizasına gelene kadar dambılı kaldırmaya devam edin. Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun. Nefes alın ve dambılı yavaşça başlangıç ​​pozisyonuna indirin. Hareketi karşı kolla tekrarlayın. İstenilen sayıda tekrar için kolları değiştirerek devam edin.","es":"Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.","ru":"Сядьте на гимнастический мяч, поставив ноги на землю и выпрямив спину. Возьмите по гантели в каждую руку ладонями к телу и полностью выпрямленными руками. Удерживая плечи неподвижно, выдохните и согните одну гантель к плечу, держа ладонь к телу. Продолжайте поднимать гантель до тех пор, пока ваши бицепсы полностью не сократятся и гантель не окажется на уровне плеч. Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы. Вдохните и медленно опустите гантель обратно в исходное положение. Повторите движение противоположной рукой. Продолжайте чередовать руки желаемое количество повторений.","zh":"坐在健身球上，双脚平放在地上，背部挺直。 每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。 保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时保持手掌朝向身体。 继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。 挤压二头肌时，保持收缩位置短暂停顿。 吸气，慢慢将哑铃放回起始位置。 用另一只手臂重复该动作。 继续交替手臂进行所需的重复次数。","hi":"अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें। अपनी हथेलियों को अपने शरीर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें। अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपनी हथेली को अपने शरीर की ओर रखते हुए एक डम्बल को अपने कंधे की ओर मोड़ें। डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए। जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें। श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ। विपरीत भुजा से भी यही क्रिया दोहराएँ। दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।","pl":"Usiądź na piłce gimnastycznej, stopy oprzyj płasko na podłodze, a plecy trzymaj proste. Trzymaj w każdej dłoni hantlę, dłonie skierowane w stronę ciała, ręce w pełni wyprostowane. Utrzymując nieruchome ramiona, wykonaj wydech i unieś jedną hantlę w stronę barku, trzymając dłoń skierowaną w stronę ciała. Unoś hantlę, aż biceps będzie maksymalnie napięty, a hantla znajdzie się na wysokości barku. Zatrzymaj się na chwilę w napiętej pozycji, ściskając biceps. Wykonaj wdech i powoli opuść hantlę z powrotem do pozycji wyjściowej. Powtórz ruch przeciwną ręką. Kontynuuj naprzemienne wykonywanie ćwiczenia przez zalecaną liczbę powtórzeń.","ko":"운동공에 앉아 발을 땅에 댄 채 등을 곧게 펼친다. 양손에 덤벨을 들되 손바닥이 몸을 향하고 팔을 완전히 펼친다. 위팔을 고정한 채 숨을 내쉬면서 한쪽 덤벨을 어깨 쪽으로 위로 올리되 손바닥이 몸을 향하도록 유지한다. 이두근이 완전히 수축되고 덤벨이 어깨 높이에 올 때까지 계속 올린다. 수축된 위치에서 잠깐 멈추면서 이두근을 조인다. 숨을 들이쉬면서 천천히 덤벨을 시작 위치로 낮춘다. 반대쪽 팔로 같은 동작을 반복한다. 양팔을 교대로 반복하며 원하는 반복 횟수만큼 계속 수행합니다.","fr":"Assieds-toi sur un ballon d''exercice, les pieds à plat sur le sol et le dos droit. Tiens un haltère dans chaque main, les paumes tournées vers ton corps et les bras complètement étendus. En gardant le haut des bras immobile, expire et fléchis un haltère vers ton épaule en gardant ta paume tournée vers ton corps. Continue à lever l''haltère jusqu''à ce que ton biceps soit complètement contracté et que l''haltère soit à hauteur d''épaule. Maintiens la position contractée pendant une brève pause en contractant tes biceps. Inspire et abaisse lentement l''haltère jusqu''à la position de départ. Répète le mouvement avec le bras opposé. Continue à alterner les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/1676-QLRmNeT.jpg', 'videos/1676-QLRmNeT.gif', '© Gym visual — https://gymvisual.com/'),
(388, 'dumbbell seated alternate press', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'triceps', 'delts', '["triceps","chest"]'::jsonb, '{"en":"Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward. Press one dumbbell up overhead, fully extending your arm. Lower the dumbbell back down to shoulder height. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.","it":"Siediti su una panchina con un manubrio in ciascuna mano, i palmi rivolti in avanti. Alza i manubri all''altezza delle spalle, con i gomiti piegati e i palmi rivolti in avanti. Premi un manubrio sopra la testa, estendendo completamente il braccio. Abbassa il manubrio fino all''altezza delle spalle. Ripeti con l''altro braccio. Continuare ad alternare le braccia per il numero desiderato di ripetizioni.","tr":"Her iki elinizde birer dambıl olacak şekilde, avuç içleriniz öne bakacak şekilde bir bankta oturun. Dirsekleriniz bükülü ve avuç içleriniz öne bakacak şekilde dambılları omuz yüksekliğine kaldırın. Kolunuzu tamamen uzatarak bir dambılı yukarı doğru bastırın. Dambılı tekrar omuz hizasına kadar indirin. Diğer kolla tekrarlayın. İstenilen sayıda tekrar için kolları değiştirerek devam edin.","es":"Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.","ru":"Сядьте на скамью, взяв в каждую руку по гантели ладонями вперед. Поднимите гантели на высоту плеч, согнув локти и повернув ладони вперед. Выжмите одну гантель над головой, полностью выпрямляя руку. Опустите гантель обратно на высоту плеч. Повторите с другой рукой. Продолжайте чередовать руки желаемое количество повторений.","zh":"坐在长凳上，双手各握一个哑铃，手掌朝前。 将哑铃举至肩部高度，肘部弯曲，手掌朝前。 将一只哑铃举过头顶，完全伸展手臂。 将哑铃放回至肩膀高度。 用另一只手臂重复上述步骤。 继续交替手臂进行所需的重复次数。","hi":"प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आगे की ओर हों। अपनी कोहनियों को मोड़कर और हथेलियों को आगे की ओर रखते हुए डम्बल को कंधे की ऊंचाई तक उठाएं। अपनी बांह को पूरी तरह फैलाते हुए एक डम्बल को ऊपर की ओर दबाएं। डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ। दूसरे हाथ से दोहराएँ. दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।","pl":"Usiądź na ławce, trzymając w każdej dłoni hantlę, dłonie skierowane do przodu. Unieś hantle na wysokość barków, z łokciami zgiętymi i dłońmi skierowanymi do przodu. Wypchnij jedną hantlę do góry nad głowę, w pełni prostując rękę. Opuść hantlę z powrotem na wysokość barku. Powtórz drugą ręką. Kontynuuj naprzemienne wykonywanie ćwiczenia przez zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 양손에 덤벨을 들되 손바닥이 앞을 향하도록 한다. 덤벨을 어깨 높이로 올리되 팔꿈치를 구부리고 손바닥이 앞을 향하도록 한다. 한쪽 덤벨을 머리 위로 밀어올려 팔을 완전히 펼친다. 덤벨을 어깨 높이로 다시 내린다. 다른 팔로 반복한다. 양팔을 교대로 반복하며 원하는 반복 횟수만큼 계속 수행합니다.","fr":"Assieds-toi sur un banc avec un haltère dans chaque main, paumes tournées vers l''avant. Lève les haltères à hauteur des épaules, tes coudes fléchis et tes paumes tournées vers l''avant. Développe un haltère vers le haut au-dessus de ta tête, en tendant complètement ton bras. Abaisse l''haltère à hauteur des épaules. Répète avec l''autre bras. Continue à alterner les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/0388-QT5Q0nK.jpg', 'videos/0388-QT5Q0nK.gif', '© Gym visual — https://gymvisual.com/'),
(3546, 'dumbbell seated alternate shoulder', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'triceps', 'delts', '["triceps","upper back"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height. Press one dumbbell up overhead while keeping the other dumbbell at shoulder height. Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead. Continue alternating between arms for the desired number of repetitions.","it":"Siediti su una panchina con la schiena dritta e i piedi piatti a terra. Tieni un manubrio in ogni mano, palmi rivolti verso l''interno, e sollevali all''altezza delle spalle. Spingi un manubrio sopra la testa mentre l''altro mantiene l''altro all''altezza delle spalle. Abbassa il manubrio rialzato all''altezza delle spalle mentre contemporaneamente spingi l''altro manubrio sopra la testa. Continua ad alternare tra le braccia per il numero desiderato di ripetizioni.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Her iki elinize de birer dambıl tutun, avuç içleriniz içe doğru baksın ve onları omuz yüksekliğine kadar kaldırın. Bir dambılı başınızın üstüne doğru bastırırken diğer dambılı omuz hizasında tutun. Kaldırılmış dambılı tekrar omuz yüksekliğine indirin ve aynı anda diğer dambılı başınızın üstüne doğru bastırın. İstenilen sayıda tekrar için kollar arasında geçiş yapmaya devam edin.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros. Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros. Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza. Continúa alternando entre los brazos durante el número de repeticiones deseado.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Возьмите по гантели в каждую руку ладонями внутрь и поднимите их на высоту плеч. Поднимите одну гантель над головой, удерживая другую на уровне плеч. Опустите поднятую гантель обратно на высоту плеч, одновременно поднимая другую гантель над головой. Продолжайте чередовать руки необходимое количество повторений.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手各握一个哑铃，掌心向内，将哑铃举至肩高。 将一个哑铃举过头顶，同时将另一个哑铃保持在与肩同高的位置。 将举起的哑铃放回肩高，同时将另一个哑铃推过头顶。 继续交替手臂进行所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ अंदर की ओर हों, और उन्हें कंधे की ऊँचाई तक उठाएँ। एक डम्बल को ऊपर की ओर दबाएं जबकि दूसरे डम्बल को कंधे की ऊंचाई पर रखें। उठे हुए डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ और साथ ही दूसरे डम्बल को ऊपर की ओर दबाएँ। दोहराव की वांछित संख्या के लिए भुजाओं के बीच बारी-बारी से जारी रखें।","pl":"Usiądź na ławce, trzymając plecy proste i stopy płasko na podłodze. Trzymaj w każdej dłoni hantlę, dłonie skierowane do wewnątrz, i unieś je na wysokość barków. Wypchnij jedną hantlę do góry nad głowę, trzymając drugą hantlę na wysokości barku. Opuść uniesioną hantlę z powrotem na wysokość barku, jednocześnie wypychając drugą hantlę do góry nad głowę. Kontynuuj naprzemienne wykonywanie ćwiczenia przez zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 등을 곧게 펴고 발을 땅에 댄다. 양손에 덤벨을 들되 손바닥이 안쪽을 향하고 어깨 높이로 올린다. 한쪽 덤벨을 머리 위로 밀어올리되 다른 덤벨은 어깨 높이에 유지한다. 올린 덤벨을 어깨 높이로 내리면서 동시에 다른 덤벨을 머리 위로 밀어올린다. 양팔을 교대로 반복하며 원하는 반복 횟수만큼 계속 수행합니다.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un haltère dans chaque main, les paumes tournées vers l''intérieur, et lève-les à hauteur des épaules. Développe un haltère vers le haut au-dessus de ta tête tout en gardant l''autre haltère à hauteur des épaules. Abaisse l''haltère levé à hauteur des épaules tout en pressant simultanément l''autre haltère au-dessus de la tête. Continue à alterner entre les bras pour le nombre de répétitions souhaité."}'::jsonb, 'images/3546-q7qkONO.jpg', 'videos/3546-q7qkONO.gif', '© Gym visual — https://gymvisual.com/'),
(389, 'dumbbell seated bench extension', 'upper arms', 'strength', 'upper arms', 'dumbbell', 'shoulders', 'triceps', '["shoulders"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with both hands and extend your arms straight up above your head. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears. Pause for a moment, then raise the dumbbell back up to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panchina con la schiena dritta e i piedi piatti a terra. Tieni un manubrio con entrambe le mani e allunga le braccia dritte sopra la testa. Abbassa lentamente il manubrio dietro la testa, tenendo i gomiti vicino alle orecchie. Fermati un attimo, poi rialza il manubrio alla posizione di partenza. Ripeti per il numero desiderato di ripetizioni.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. İki elinizle bir dambılı tutun ve kollarınızı başınızın üzerine doğru uzatın. Dirseklerinizi kulaklarınıza yakın tutarak dambılı başınızın arkasına yavaşça indirin. Bir süre duraklayın, ardından dambılı tekrar başlangıç ​​pozisyonuna kaldırın. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Возьмите гантель обеими руками и вытяните руки прямо над головой. Медленно опустите гантель за голову, держа локти близко к ушам. Сделайте паузу на мгновение, затем поднимите гантель обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手握住哑铃，将手臂伸直至头顶上方。 慢慢地将哑铃放到脑后，保持肘部靠近耳朵。 暂停片刻，然后将哑铃举回到起始位置。 重复所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपने सिर के ऊपर फैलाएँ। अपनी कोहनियों को अपने कानों के पास रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ। एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce, trzymając plecy proste i stopy płasko na podłodze. Trzymaj hantlę obiema rękami i wyprostuj ręce prosto nad głową. Powoli opuszczaj hantlę za głowę, trzymając łokcie blisko uszu. Zatrzymaj się na chwilę, a następnie unieś hantlę z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 등을 곧게 펴고 발을 땅에 댄다. 양손으로 덤벨 하나를 들고 팔을 머리 위로 곧게 펼친다. 천천히 덤벨을 머리 뒤로 내리되 팔꿈치는 귀 근처에 가깝게 유지한다. 잠깐 멈춘 후 덤벨을 시작 위치로 올린다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un haltère des deux mains et étends les bras droit au-dessus de ta tête. Abaisse lentement l''haltère derrière ta tête, en gardant tes coudes près de tes oreilles. Marque une pause, puis ramène l''haltère vers le haut jusqu''à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/0389-JhYSVwT.jpg', 'videos/0389-JhYSVwT.gif', '© Gym visual — https://gymvisual.com/'),
(2317, 'dumbbell seated bent arm lateral raise', 'shoulders', 'strength', 'shoulders', 'dumbbell', 'trapezius', 'delts', '["trapezius","rhomboids"]'::jsonb, '{"en":"Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle. Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.","it":"Siediti su una panchina con la schiena dritta e i piedi piatti a terra. Tieni un manubrio in ogni mano con i palmi rivolti verso il corpo e le braccia piegate a 90 gradi. Tenendo i gomiti piegati, alza le braccia ai lati finché non sono parallele al suolo. Fermati un attimo in cima, poi abbassa lentamente le braccia fino alla posizione iniziale. Ripeti per il numero desiderato di ripetizioni.","tr":"Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun. Avuç içleriniz vücudunuza bakacak ve kollarınız 90 derecelik bir açıyla bükülmüş olacak şekilde her elinizde bir dambıl tutun. Dirseklerinizi bükülü tutarak kollarınızı yere paralel olana kadar yanlara doğru kaldırın. Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin. İstenilen sayıda tekrar için tekrarlayın.","es":"Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados. Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.","ru":"Сядьте на скамью, выпрямив спину и поставив ноги на землю. Возьмите по гантели в каждую руку ладонями к телу, руки согнуты под углом 90 градусов. Сохраняя локти согнутыми, поднимите руки в стороны, пока они не станут параллельны земле. Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение. Повторите необходимое количество повторений.","zh":"坐在长凳上，背部挺直，双脚平放在地上。 双手各握一个哑铃，手掌朝向身体，手臂弯曲成 90 度角。 保持肘部弯曲，将手臂向两侧抬起，直到与地面平行。 在顶部暂停片刻，然后慢慢将手臂放回起始位置。 重复所需的重复次数。","hi":"अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें। अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें और आपकी भुजाएँ 90 डिग्री के कोण पर मुड़ी हुई हों। अपनी कोहनियों को मोड़ते हुए, अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ। शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं। दोहराव की वांछित संख्या के लिए दोहराएँ।","pl":"Usiądź na ławce, trzymając plecy proste i stopy płasko na podłodze. Trzymaj w każdej dłoni hantlę, dłonie skierowane w stronę ciała, ręce zgięte pod kątem 90 stopni. Utrzymując zgięte łokcie, unieś ręce na boki, aż będą równoległe do podłogi. Zatrzymaj się na chwilę na górze, a następnie powoli opuść ręce z powrotem do pozycji wyjściowej. Powtórz zalecaną liczbę powtórzeń.","ko":"벤치에 앉아 등을 곧게 펴고 발을 땅에 댄다. 양손에 덤벨을 들되 손바닥이 몸을 향하고 팔을 90도 각도로 구부린다. 팔꿈치를 구부린 채로 팔을 옆쪽으로 들어올려 바닥과 평행하게 만든다. 맨 위에서 잠깐 멈춘 후 천천히 팔을 시작 위치로 내린다. 원하는 반복 횟수만큼 반복합니다.","fr":"Assieds-toi sur un banc, le dos droit et les pieds à plat sur le sol. Tiens un haltère dans chaque main, les paumes tournées vers ton corps et les bras fléchis à un angle de 90 degrés. En gardant les coudes fléchis, lève tes bras sur les côtés jusqu''à ce qu''ils soient parallèles au sol. Marque une pause en haut, puis abaisse lentement tes bras pour revenir à la position de départ. Répète le nombre de répétitions souhaité."}'::jsonb, 'images/2317-JzQbv7J.jpg', 'videos/2317-JzQbv7J.gif', '© Gym visual — https://gymvisual.com/')
